insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-400', 'Mr Sanjay: laid off at forty-four (adjustment disorder after job loss)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-400-1","text":"Sole earner for the family","bucket":"predisposing"},{"id":"form-400-2","text":"Has not told his parents","bucket":"perpetuating"},{"id":"form-400-3","text":"Still meets friends and helps his children with homework","bucket":"presenting"},{"id":"form-400-4","text":"Applies only to jobs at his old level","bucket":"perpetuating"},{"id":"form-400-5","text":"No daily structure","bucket":"perpetuating"},{"id":"form-400-6","text":"He lives in Pune","bucket":"distractor"},{"id":"form-400-7","text":"Low mood, poor sleep and staying in bed late for six weeks since he was laid off","bucket":"presenting"},{"id":"form-400-8","text":"Supportive wife and friends","bucket":"protective"},{"id":"form-400-9","text":"Savings for a year","bucket":"protective"},{"id":"form-400-10","text":"Identity built around his work","bucket":"predisposing"},{"id":"form-400-11","text":"Laid off in a company restructuring after eighteen years","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Sanjay, 44, has an adjustment disorder with depressed mood after losing his job: distress greater than expected but still functioning in key areas, within weeks of the event. An identity built around work and being the sole earner (predisposing) increase the impact; the lay-off (precipitating) triggered it. Secrecy with his parents, no daily structure and a narrow job search (perpetuating) maintain it. Savings and support (protective) give time. Plan: daily routine, a broader job plan, telling his parents and screening for depression and suicide risk if symptoms deepen. Pune is a distractor.","hint":"A 44-year-old engineer who has stayed in bed since being laid off","tags":{"topic":"depression","difficulty":1,"objective":"Sort an adjustment reaction to job loss into the 5 Ps","exams":["cuet-pg","ma-semester","mcp-entrance"],"module":"depression","diagnosis":"Adjustment disorder with depressed mood"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-401', 'Mrs Rupa: no time left for herself (carer burnout in the mother of an autistic child)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-401-1","text":"Gave up her job to care for her son","bucket":"predisposing"},{"id":"form-401-2","text":"Her son''s therapy centre closed and his school asked her to stay with him in class","bucket":"precipitating"},{"id":"form-401-3","text":"Exhausted, tearful and irritable for six months","bucket":"presenting"},{"id":"form-401-4","text":"Husband works long hours and helps little","bucket":"perpetuating"},{"id":"form-401-5","text":"Feels guilty taking any break","bucket":"perpetuating"},{"id":"form-401-6","text":"Loves her son and sees his progress","bucket":"protective"},{"id":"form-401-7","text":"Sleeps four hours a night because her son wakes often","bucket":"presenting"},{"id":"form-401-8","text":"She lives in Kochi","bucket":"distractor"},{"id":"form-401-9","text":"Little family support","bucket":"predisposing"},{"id":"form-401-10","text":"A parent support group online","bucket":"protective"},{"id":"form-401-11","text":"Relatives blame her parenting for his behaviour","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Rupa, 37, has carer burnout with a mild depressive episode while caring for her autistic son. Giving up work and limited family support (predisposing) increase her load; the therapy centre closing and having to stay at school (precipitating) removed her only breaks. Blame from relatives, little help from her husband and guilt about breaks (perpetuating) wear her down. Her love for her son and an online parent group (protective) help. Plan: assess mood and risk, sleep support for her son, respite and shared care with her husband, disability benefits and school support, and time for herself without guilt. Kochi is a distractor.","hint":"A 37-year-old mother of an autistic son who is exhausted and tearful","tags":{"topic":"neurodevelopmental","difficulty":2,"objective":"Formulate burnout in the parent of a child with high support needs","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"child","diagnosis":"Carer burnout with a mild depressive episode"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-402', 'Mr Rafiq: shoulder jerks and grunts since childhood, worse at work (persistent tic disorder in an adult)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-402-1","text":"No vocal tics; can hold them back briefly","bucket":"presenting"},{"id":"form-402-2","text":"Brother has tics too","bucket":"predisposing"},{"id":"form-402-3","text":"He works in a bank in Lucknow","bucket":"distractor"},{"id":"form-402-4","text":"Shoulder jerks and eye blinking since childhood, worse in meetings","bucket":"presenting"},{"id":"form-402-5","text":"Worry about being judged","bucket":"perpetuating"},{"id":"form-402-6","text":"Poor sleep","bucket":"perpetuating"},{"id":"form-402-7","text":"Holds tics back in meetings, then has a burst afterwards","bucket":"perpetuating"},{"id":"form-402-8","text":"Supportive partner","bucket":"protective"},{"id":"form-402-9","text":"Good at his job","bucket":"protective"},{"id":"form-402-10","text":"Promotion to a role with many presentations","bucket":"precipitating"},{"id":"form-402-11","text":"Tics started at age eight","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Rafiq, 30, has a persistent motor tic disorder: motor tics for more than a year since childhood, without vocal tics. Starting in childhood and a brother with tics (predisposing) fit the family pattern; a promotion with presentations (precipitating) increased stress. Suppressing tics, worry about judgement and poor sleep (perpetuating) worsen them. A supportive partner and work skills (protective) help. Plan: explain tics, habit reversal training, stress and sleep management, and workplace understanding if he chooses to share. His workplace is a distractor.","hint":"A 30-year-old with lifelong motor tics that worsen under stress","tags":{"topic":"neurodevelopmental","difficulty":2,"objective":"Recognise a persistent motor tic disorder in adulthood","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"child","diagnosis":"Persistent (chronic) motor tic disorder"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-403', 'Mrs Nalini: things she does not need, taken from shops (kleptomania)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-403-1","text":"Repeatedly takes small, cheap items she does not need from shops, feeling tension before and relief after","bucket":"presenting"},{"id":"form-403-2","text":"Gives the items away or throws them, and feels ashamed","bucket":"presenting"},{"id":"form-403-3","text":"Began after her children left home for college","bucket":"precipitating"},{"id":"form-403-4","text":"Steals expensive items to sell for money","bucket":"distractor"},{"id":"form-403-5","text":"Anxious and low in mood for years","bucket":"predisposing"},{"id":"form-403-6","text":"Feels genuine remorse","bucket":"protective"},{"id":"form-403-7","text":"Shame stops her seeking help","bucket":"perpetuating"},{"id":"form-403-8","text":"Lonely afternoons","bucket":"perpetuating"},{"id":"form-403-9","text":"Husband who supports treatment","bucket":"protective"},{"id":"form-403-10","text":"Relief after stealing rewards the urge","bucket":"perpetuating"},{"id":"form-403-11","text":"Mother had obsessive traits","bucket":"predisposing"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mrs Nalini, 42, has kleptomania: repeated failure to resist urges to steal items she does not need, with tension before and relief after, not for money, revenge or because of psychosis. Stealing expensive items to sell, the distractor, would be theft for gain. Long-standing anxiety and low mood and a mother with obsessive traits (predisposing) raise her risk; the empty nest (precipitating) began the pattern. Relief that rewards the urge, shame and lonely afternoons (perpetuating) maintain it. Her husband and remorse (protective) help. Plan: CBT for urges, treatment of mood and anxiety, structured activity, and legal support if charged.","hint":"A 42-year-old well-off woman caught stealing cheap items","tags":{"topic":"ocd","difficulty":4,"objective":"Tell kleptomania apart from theft for gain","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Kleptomania"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-404', 'Aditya: lonely in Toronto (acculturation stress in an Indian student abroad)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-404-1","text":"Family took a large loan for his fees","bucket":"predisposing"},{"id":"form-404-2","text":"Cold, dark days and staying indoors","bucket":"perpetuating"},{"id":"form-404-3","text":"Feels he does not fit in and calls home daily, crying","bucket":"presenting"},{"id":"form-404-4","text":"University counselling service available","bucket":"protective"},{"id":"form-404-5","text":"Never lived away from home","bucket":"predisposing"},{"id":"form-404-6","text":"Low mood, poor sleep and missing classes for two months after moving to study abroad","bucket":"presenting"},{"id":"form-404-7","text":"Roommate from Kerala who invites him out","bucket":"protective"},{"id":"form-404-8","text":"Shame about the loan stops him telling his parents how bad it is","bucket":"perpetuating"},{"id":"form-404-9","text":"Avoids student groups","bucket":"perpetuating"},{"id":"form-404-10","text":"He studies data science","bucket":"distractor"},{"id":"form-404-11","text":"Moved for his master''s in winter, and his part-time job fell through","bucket":"precipitating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Aditya, 23, has an adjustment disorder with low mood from acculturation stress after moving abroad to study. Never living away from home and the pressure of a large family loan (predisposing) raise his vulnerability; moving in winter and losing his part-time job (precipitating) triggered the distress. Dark days indoors, shame about the loan and avoiding groups (perpetuating) maintain it. University counselling and a friendly roommate (protective) help. Plan: screen for depression and suicide risk, use the counselling service, join student and Indian community groups, daylight and exercise, and an honest talk with his parents. His subject is a distractor.","hint":"A 23-year-old master''s student who is low and isolated after moving abroad","tags":{"topic":"depression","difficulty":2,"objective":"Formulate acculturation stress and low mood in an international student","exams":["mcp-entrance","ma-semester","cuet-pg"],"module":"social","diagnosis":"Adjustment disorder with depressed mood (acculturation stress)"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-405', 'Mr Bhim: two plus two is five (Ganser syndrome in a remand prisoner)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-405-1","text":"Symptoms often resolve quickly once stress lessens","bucket":"protective"},{"id":"form-405-2","text":"History of dissociative episodes after stress","bucket":"predisposing"},{"id":"form-405-3","text":"Arrested and charged with murder after a village fight","bucket":"precipitating"},{"id":"form-405-4","text":"Repeated questioning","bucket":"perpetuating"},{"id":"form-405-5","text":"Gives approximate answers, such as saying a cow has five legs or two plus two is five","bucket":"presenting"},{"id":"form-405-6","text":"Isolation in a crowded cell","bucket":"perpetuating"},{"id":"form-405-7","text":"He was a farmer near Jhansi","bucket":"distractor"},{"id":"form-405-8","text":"Family willing to visit","bucket":"protective"},{"id":"form-405-9","text":"Past head injury in a road accident","bucket":"predisposing"},{"id":"form-405-10","text":"Clouded, puzzled state with patchy memory, starting days after arrest","bucket":"presenting"},{"id":"form-405-11","text":"Overwhelming fear of a long sentence","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Mr Bhim, 33, shows Ganser syndrome: approximate answers that show he understands the question but answers just wrong, with a clouded, puzzled state, often in prisoners under severe stress. It is classed with dissociative disorders, but malingering must be considered carefully, and brain causes should be ruled out, especially with a past head injury. Past head injury and earlier dissociative episodes (predisposing) raise his vulnerability; arrest on a murder charge (precipitating) triggered it. Fear of sentencing, isolation and repeated questioning (perpetuating) maintain it. It often settles once stress reduces, and family visits help (protective). Plan: neurological check, calm, supportive assessment, careful documentation and reassessment over days. His work is a distractor.","hint":"A 33-year-old in custody who gives approximate answers to every question","tags":{"topic":"forensic","difficulty":5,"objective":"Recognise a dissociative presentation with approximate answers in custody","exams":["md-psychiatry","mcp-entrance"],"module":"more-disorders","diagnosis":"Ganser syndrome (a dissociative disorder), with malingering to be considered"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into formulation_cases (slug, title, prompt, factors, distractors, model_answer, status) values ('form-406', 'Colonel Bakshi: no regiment to command (depression after retirement from the army)', 'Sort the factors into the 5P grid. Leave distractors out.', '[{"id":"form-406-1","text":"Retired from the army six months ago and moved to a civilian colony","bucket":"precipitating"},{"id":"form-406-2","text":"No structure or command in daily life","bucket":"perpetuating"},{"id":"form-406-3","text":"Wife who has stood by him through postings","bucket":"protective"},{"id":"form-406-4","text":"Will not admit to ''weakness''","bucket":"perpetuating"},{"id":"form-406-5","text":"Drinks four large pegs a night and criticises his family constantly","bucket":"presenting"},{"id":"form-406-6","text":"Ex-servicemen''s association nearby","bucket":"protective"},{"id":"form-406-7","text":"Identity built entirely around his army role","bucket":"predisposing"},{"id":"form-406-8","text":"Irritable, low and sleeping poorly for four months since retirement","bucket":"presenting"},{"id":"form-406-9","text":"Father was a strict army officer","bucket":"predisposing"},{"id":"form-406-10","text":"He served in Ladakh","bucket":"distractor"},{"id":"form-406-11","text":"Drinking at the club every evening","bucket":"perpetuating"}]'::jsonb, '[]'::jsonb, '{"narrative":"Colonel Bakshi, 59, has a depressive episode after retirement, with harmful drinking. Retirement can mean loss of role, structure, status and community, especially when identity is built around a career. An identity tied to his army role and a strict upbringing (predisposing) increase his vulnerability; retirement and moving to a civilian colony (precipitating) removed his structure. No daily purpose, evening drinking and reluctance to admit difficulty (perpetuating) maintain it. His wife and the ex-servicemen''s association (protective) are strong resources. Plan: assess risk, reduce alcohol, find a meaningful role such as mentoring or volunteering, daily structure and treatment for depression. His posting is a distractor.","hint":"A 59-year-old retired colonel who is irritable, low and drinking more","tags":{"topic":"depression","difficulty":2,"objective":"Formulate loss of role and identity after retirement","exams":["mcp-entrance","ma-semester","md-psychiatry"],"module":"depression","diagnosis":"Depressive episode after retirement with harmful alcohol use"}}'::jsonb, 'published') on conflict (slug) do update set title = excluded.title, prompt = excluded.prompt, factors = excluded.factors, model_answer = excluded.model_answer, status = excluded.status;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Harsha, 31: the code that stopped compiling in his head', 'lib-cr-001', 'cooperative', '{"case_id":"cr-001","slug":"lib-cr-001","title":"Harsha, 31: the code that stopped compiling in his head","difficulty":"cooperative","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Harsha Gowda","age":31,"gender":"male","occupation":"backend developer at a payments start-up","city":"Bengaluru","family_structure":"lives with his wife Pallavi; parents in Mandya","language_register":"fluent IT English with Kannada asides, apologetic"},"presentation":"Two months of low mood, loss of interest, broken sleep with early waking, poor focus and guilt about letting his team down. Still working, barely.","chief_complaint_in_own_words":"My manager says my pull requests have become sloppy. He is right. I read the same line ten times. I used to love this work and now I just stare at it.","history":{"timeline":"Started after a failed product launch eight weeks ago. Wakes at 4 am, cannot get back to sleep, stopped evening cricket, appetite down, has lost about 4 kg.","prior_episodes":"none","substance_use":"two beers at weekends, unchanged","medical":"fit, no illness","family":"mother had a ''nervous weakness'' after his sister''s birth","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["a colleague who suggested a meditation app"]},"cognitive_model":{"core_belief":"If I am not productive, I am worthless.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has stopped playing cricket with his old college group, which he did every Sunday for nine years.","gate":"two_or_more_reflective_statements"},{"fact":"He feels he is a burden to Pallavi and has started sleeping on the sofa so his waking does not disturb her.","gate":"validation_given"},{"fact":"He has quietly applied for leave and is ashamed of it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is just work pressure, everyone in tech has this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Passive thoughts that it would not matter if he did not wake up, on bad mornings. No plan, no intent, no past attempts. Strong reason to live: Pallavi and his parents.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the core symptoms: mood, interest, sleep, appetite, energy, concentration and guilt","Asked about suicide clearly and followed passive thoughts to plan and intent","Used open questions and reflections before advice","Asked about functioning at work and at home","Gave brief psychoeducation that this is a treatable condition, not weakness"],"few_shot":[],"fixture_lines":["I wake at four. Every day, four. The ceiling fan, the auto horns starting up, and my brain already running the stand-up meeting I have not had yet.","Cricket on Sunday was my whole week. Nine years with the same boys. I told them my knee is bad. My knee is fine.","Food tastes like cardboard. Pallavi makes ragi mudde the way I like and I eat three bites and feel full.","The launch failed. Fine, launches fail. But I keep replaying it like it was my fault alone, and it was not, I know that, but knowing does not help.","I am not sad exactly. It is more like the colour has been turned down on everything."],"variation":{"mood_today":["flat","apologetic","tired"],"recent_event":["a manager''s review email","missed the Sunday cricket again","Pallavi cried last night"],"most_defended_topic":["sleeping on the sofa"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fluent IT English with Kannada asides, apologetic"]},"moves":{},"module_id":"depression","voice_key":"fluent IT English with Kannada asides, apologetic@Bengaluru","protective_factors":["close marriage","employer health cover"],"library":{"level":1,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise the core features of a depressive episode in a working adult","expected_mse":{"appearance":"Neatly dressed, unshaven, dark circles","behaviour":"Slowed, little eye contact, fidgets with phone","speech":"Soft, slow, reduced in amount, answers fully when asked","mood":"''Grey, like the colour is turned down''","affect":"Depressed, reactive only a little, restricted range","thought_form":"Logical and goal-directed","thought_content":"Guilt about the launch, worthlessness, passive death wishes, no plan","perception":"No abnormal perceptions","cognition":"Alert, oriented; poor concentration on serial sevens","insight_judgement":"Partial insight: calls it stress, accepts help"},"diagnosis":"Moderate depressive episode (single episode)","differentials":[{"dx":"Adjustment disorder","why_not":"Symptoms are too many and too pervasive (anhedonia, early waking, weight loss, guilt) and meet full episode criteria"},{"dx":"Hypothyroidism","why_not":"No cold intolerance, constipation or weight gain; thyroid function still worth checking"},{"dx":"Burnout","why_not":"Not a diagnosis that explains the anhedonia spreading beyond work and the guilt"}],"debrief_rubric":["Explored the core symptoms: mood, interest, sleep, appetite, energy, concentration and guilt","Asked about suicide clearly and followed passive thoughts to plan and intent","Used open questions and reflections before advice","Asked about functioning at work and at home","Gave brief psychoeducation that this is a treatable condition, not weakness"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Kulkarni, 49: the teacher who has always been ''like this''', 'lib-cr-002', 'guarded', '{"case_id":"cr-002","slug":"lib-cr-002","title":"Mrs Kulkarni, 49: the teacher who has always been ''like this''","difficulty":"guarded","traps":["under_diagnosis","misattributed_diagnosis"],"traps_authored":["under_diagnosis","misattributed_diagnosis"],"identity":{"name":"Shubhangi Kulkarni","age":49,"gender":"female","occupation":"Marathi teacher at a government school","city":"Nagpur","family_structure":"married, one son at college in Pune","language_register":"precise Marathi-English, dry humour, never complains for long"},"presentation":"Low, joyless mood most days for many years, poor self-esteem, tiredness and pessimism, never free of it for more than a few weeks. Works and copes. Came because her son said she ''never smiles in photos''.","chief_complaint_in_own_words":"I am not ill. I have always been a gloomy person. My son made the appointment. He says I should be happier. I said, show me how.","history":{"timeline":"Says she has felt this way ''since my twenties, after my father''s business failed''. Never a time of feeling well for longer than a month. No period of full collapse; no sustained worsening in the last months.","prior_episodes":"no hospital stays; no high periods","substance_use":"none","medical":"mild hypertension on amlodipine","family":"father was ''serious and silent''","treatment_history":"a tonic from the family doctor ten years ago","help_seeking_delay":"decades","prior_contacts":["family doctor","temple"]},"cognitive_model":{"core_belief":"Joy is for other people; my job is to endure.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She cannot remember a single month in the last twenty-five years when she felt light.","gate":"two_or_more_reflective_statements"},{"fact":"She marks her students'' notebooks until midnight because she believes she is a mediocre teacher, though her results are the best in the school.","gate":"validation_given"},{"fact":"She envies her sister''s ease and feels guilty about the envy.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everybody my age is tired. It is the menopause, the doctor said."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no thoughts of ending her life now or ever; ''I am too stubborn to give up.'' No self-harm.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Established the time course: years without a clear well period","Checked for a superimposed worsening (double depression)","Asked about mania or highs to rule out a bipolar course","Asked about suicide clearly despite her stoic front","Explained that long-standing low mood is treatable, not just personality"],"few_shot":[],"fixture_lines":["I get up, I teach, I come home, I correct notebooks. Thirty-eight notebooks a night. It is not suffering. It is just life.","My son says I never smile in photos. I tell him photographers make everyone look like that. He does not laugh.","If you are asking whether I am sadder now than before, no. I am exactly as I always was. That is perhaps the problem.","My sister laughs easily. I used to think she was shallow. Now I think she just has a lighter engine.","Holidays are the worst. In school at least there is a timetable to hide behind."],"variation":{"mood_today":["dry","flat","wary"],"recent_event":["her son posted a family photo","a colleague retired","the school inspection"],"most_defended_topic":["her envy of her sister"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["precise Marathi-English, dry humour, never complains for long"]},"moves":{},"module_id":"depression","voice_key":"precise Marathi-English, dry humour, never complains for long@Nagpur","protective_factors":["meaningful work","son who cares"],"library":{"level":4,"topic":"depression","module":"depression","exams":["mcp-entrance","md-psychiatry","ugc-net"],"objective":"Tell persistent low-grade low mood apart from a discrete depressive episode","expected_mse":{"appearance":"Tidy cotton saree, hair tightly tied","behaviour":"Upright, controlled, little gesture","speech":"Normal rate, clipped, sardonic","mood":"''Normal for me, which is grey''","affect":"Mildly depressed, restricted but reactive to humour","thought_form":"Coherent","thought_content":"Long-standing pessimism and low self-worth; no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Partial: sees it as her nature, not a condition"},"diagnosis":"Persistent depressive disorder (dysthymia), early onset","differentials":[{"dx":"Major depressive episode","why_not":"No discrete period of marked worsening with full criteria; the picture is chronic and steady"},{"dx":"Personality style (depressive temperament)","why_not":"The duration and impairment of joy and self-esteem fit a treatable mood disorder; temperament does not explain the distress she describes"},{"dx":"Hypothyroidism","why_not":"Should be checked, but decades of steady course without physical signs argue against"}],"debrief_rubric":["Established the time course: years without a clear well period","Checked for a superimposed worsening (double depression)","Asked about mania or highs to rule out a bipolar course","Asked about suicide clearly despite her stoic front","Explained that long-standing low mood is treatable, not just personality"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Bhattacharya, 67: up at three, worst in the morning', 'lib-cr-003', 'guarded', '{"case_id":"cr-003","slug":"lib-cr-003","title":"Mr Bhattacharya, 67: up at three, worst in the morning","difficulty":"guarded","traps":["late_risk_reveal","under_diagnosis"],"traps_authored":["late_risk_reveal","under_diagnosis"],"identity":{"name":"Debashis Bhattacharya","age":67,"gender":"male","occupation":"retired railway accountant","city":"Kolkata","family_structure":"lives with wife Kalyani in a Salt Lake flat; daughter in Hyderabad","language_register":"formal Bengali-English, slow, long pauses"},"presentation":"Three months of profound loss of pleasure, early morning waking, mood worst in the morning, marked slowing, weight loss of 7 kg, and excessive guilt about a decades-old office matter.","chief_complaint_in_own_words":"Nothing gives me any feeling. Not my grandson''s voice on the phone, not Rabindrasangeet. Mornings are like walking through wet sand.","history":{"timeline":"Insidious onset three months ago without a clear trigger. Wakes at 3 am. Better by evening. Stopped reading the newspaper, his lifelong habit.","prior_episodes":"one similar episode at 52, treated with an antidepressant, full recovery","substance_use":"none","medical":"diabetes on metformin; recent HbA1c fine","family":"brother died by suicide at 60","treatment_history":"the antidepressant at 52; stopped after a year","help_seeking_delay":"three months","prior_contacts":["family physician who checked his sugar"]},"cognitive_model":{"core_belief":"I am a guilty man and this is what I deserve.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He believes a 1987 accounting error he made cost a clerk his promotion, and he has been ''paying for it'' every night since.","gate":"validation_given"},{"fact":"He no longer feels any pleasure when his grandson calls; he pretends for his wife.","gate":"two_or_more_reflective_statements"},{"fact":"His older brother died by suicide at 60 after a similar spell; he has not told the doctor before.","gate":"asked_open_about_family"}],"resistance":{"deflections":["At my age, what do you expect? The body slows."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: thinks his family would be better without him, has thought of ''not taking his tablets and letting it end'' but no active plan yet. High-risk profile: older man, prior episode, family history of suicide, guilt. Needs urgent psychiatric review.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Elicited melancholic features: early waking, diurnal variation, non-reactive mood, slowing, weight loss","Took the family history of suicide and linked it to risk","Asked about suicide clearly and recognised a high-risk profile in an older man","Asked about past response to treatment","Arranged urgent review rather than routine follow-up"],"few_shot":[],"fixture_lines":["I wake at three. The clock in the hall chimes. I lie and count my failures until the milkman comes.","By evening I am slightly human. By morning, nothing again.","Kalyani makes my favourite fish curry. I eat to please her. It tastes of nothing at all.","There was a clerk, Biswas, in 1987. My figures were wrong. He lost his promotion. I think of him every night now.","I have stopped reading Anandabazar. Forty years, every morning. Now the words just lie on the page."],"variation":{"mood_today":["heavy","slowed","guilty"],"recent_event":["his grandson''s birthday call","Kalyani found him sitting in the dark at 4 am","news of an old colleague''s death"],"most_defended_topic":["his brother''s death"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["formal Bengali-English, slow, long pauses"]},"moves":{},"module_id":"depression","voice_key":"formal Bengali-English, slow, long pauses@Kolkata","protective_factors":["devoted wife","past full recovery"],"library":{"level":3,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Identify melancholic features and their treatment implications","expected_mse":{"appearance":"Thin, clothes loose, unshaven","behaviour":"Marked psychomotor slowing, long latency before answers","speech":"Slow, soft, monotonous","mood":"''Nothing, no feeling''","affect":"Depressed, non-reactive","thought_form":"Slowed but coherent","thought_content":"Excessive guilt about a past error; hopelessness; thoughts family better off without him","perception":"No hallucinations elicited","cognition":"Oriented; slowed attention, effort poor","insight_judgement":"Partial: accepts he is unwell, believes he deserves it"},"diagnosis":"Severe depressive episode with melancholic features, recurrent","differentials":[{"dx":"Early dementia","why_not":"Onset over weeks with mood change first, morning worsening and guilt point to depression; cognitive slowing is likely part of it, recheck after recovery"},{"dx":"Psychotic depression","why_not":"Guilt is excessive but still within the bounds of an overvalued idea; probe for fixed guilt delusions or nihilism"},{"dx":"Hypothyroidism or other medical cause","why_not":"Needs bloods, but a prior identical episode that responded to antidepressants supports a recurrent mood disorder"}],"debrief_rubric":["Elicited melancholic features: early waking, diurnal variation, non-reactive mood, slowing, weight loss","Took the family history of suicide and linked it to risk","Asked about suicide clearly and recognised a high-risk profile in an older man","Asked about past response to treatment","Arranged urgent review rather than routine follow-up"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Zoya, 24: sleeps twelve hours and still feels heavy', 'lib-cr-004', 'cooperative', '{"case_id":"cr-004","slug":"lib-cr-004","title":"Zoya, 24: sleeps twelve hours and still feels heavy","difficulty":"cooperative","traps":["misattributed_diagnosis","under_diagnosis"],"traps_authored":["misattributed_diagnosis","under_diagnosis"],"identity":{"name":"Zoya Mirza","age":24,"gender":"female","occupation":"content writer working from home","city":"Lucknow","family_structure":"lives with parents and grandmother","language_register":"quick Urdu-inflected English, self-mocking"},"presentation":"Five months of low mood that lifts briefly with good news, sleeping 11 to 12 hours, eating more, weight gain, heavy limbs and long-standing sensitivity to rejection.","chief_complaint_in_own_words":"My arms feel like they are filled with wet sand. I sleep and sleep and wake up tired. When a client praises me I feel normal for an hour, then I crash again.","history":{"timeline":"Worse since a broken engagement five months ago. Has gained 6 kg, craves sweets at night, sleeps till noon, cancels plans when a friend''s reply is late.","prior_episodes":"a similar spell at 19 after board exams","substance_use":"none","medical":"PCOS on no treatment","family":"aunt with ''mood swings''","treatment_history":"none","help_seeking_delay":"five months","prior_contacts":["a gynaecologist who said lose weight"]},"cognitive_model":{"core_belief":"People leave once they see the real me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She reads a late reply from a friend as proof she is disliked and then avoids that friend for weeks.","gate":"two_or_more_reflective_statements"},{"fact":"Her fiance''s family broke the engagement saying she was ''too moody'', and she secretly agrees with them.","gate":"validation_given"},{"fact":"She eats a whole box of mithai alone at night and hides the box.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just PCOS, everything is PCOS."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: occasional fleeting wish to ''disappear for a while'', no thoughts of ending her life, no self-harm. Screen for any high periods given aunt''s history.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Noted mood reactivity and the reversed vegetative signs (more sleep, more appetite)","Explored rejection sensitivity with open questions","Screened for past high or overactive periods","Asked about suicide clearly","Validated without dismissing it as ''just PCOS'' or laziness"],"few_shot":[],"fixture_lines":["If you text me ''ok'' instead of ''okay!'' I will think you hate me. I know that is ridiculous. I still think it.","Twelve hours of sleep and I wake up like someone has poured cement into my arms.","A client wrote ''this is brilliant'' yesterday. I was fine for one whole afternoon. Then the sweets came out at midnight.","Ammi says I have become lazy. Nani says somebody has put nazar on me. I say, both of you, please, let me sleep.","The engagement ending was not the problem. The reason they gave was the problem. ''Too moody.'' They had a point."],"variation":{"mood_today":["heavy","wry","tearful"],"recent_event":["a client''s praise","a friend did not reply for a day","ex-fiance''s wedding photos"],"most_defended_topic":["the reason the engagement ended"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["quick Urdu-inflected English, self-mocking"]},"moves":{},"module_id":"depression","voice_key":"quick Urdu-inflected English, self-mocking@Lucknow","protective_factors":["work she is good at","close grandmother"],"library":{"level":4,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance","ugc-net"],"objective":"Recognise atypical features and rejection sensitivity","expected_mse":{"appearance":"Casual kurta, well groomed","behaviour":"Slumped posture, brightens with humour","speech":"Normal rate, ironic","mood":"''Heavy and sad, but it moves''","affect":"Depressed but clearly reactive","thought_form":"Coherent","thought_content":"Rejection sensitivity, low self-worth, no suicidal intent","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight, asks what is wrong"},"diagnosis":"Depressive episode with atypical features","differentials":[{"dx":"Bipolar II disorder","why_not":"No history of hypomania so far; atypical features and a family history mean she should be screened carefully and treated with this in mind"},{"dx":"Hypothyroidism","why_not":"Weight gain and fatigue overlap; check thyroid, but mood reactivity and rejection sensitivity point to atypical depression"},{"dx":"Binge-eating disorder","why_not":"Night eating is present, but it follows the mood and lacks a separate binge pattern with loss of control as the main problem"}],"debrief_rubric":["Noted mood reactivity and the reversed vegetative signs (more sleep, more appetite)","Explored rejection sensitivity with open questions","Screened for past high or overactive periods","Asked about suicide clearly","Validated without dismissing it as ''just PCOS'' or laziness"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ramkumar, 54: the rot inside him', 'lib-cr-005', 'resistant', '{"case_id":"cr-005","slug":"lib-cr-005","title":"Ramkumar, 54: the rot inside him","difficulty":"resistant","traps":["somatic_mask","under_diagnosis"],"traps_authored":["somatic_mask","under_diagnosis"],"identity":{"name":"Ramkumar Yadav","age":54,"gender":"male","occupation":"owns a small brick kiln","city":"Varanasi","family_structure":"married, three adult children; eldest son runs the kiln now","language_register":"Bhojpuri-flavoured Hindi, few words, flat"},"presentation":"Brought by his son. Four months of withdrawal, not eating, sleeping little, and a fixed belief that his intestines are rotting and that he has ruined his family through sin. Hears a voice at night calling him a sinner.","chief_complaint_in_own_words":"Kuch nahi hai, beta. Bas andar sab sad gaya hai. My stomach has stopped. Food goes in and rots. Why are you wasting your time?","history":{"timeline":"Started after the kiln lost a large order in the monsoon. Gradual withdrawal over weeks, then refusing food in the last fortnight. Lost about 10 kg.","prior_episodes":"none known","substance_use":"used to chew tobacco; stopped","medical":"no known illness; recent stomach scan normal","family":"not known","treatment_history":"an ayurvedic churan, a temple ritual","help_seeking_delay":"four months","prior_contacts":["village doctor","pandit ji","a stomach specialist who found nothing"]},"cognitive_model":{"core_belief":"I am rotten and I have rotted everyone around me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He believes the lost order was punishment for a sin from his youth that he will not name.","gate":"validation_given"},{"fact":"At night a man''s voice outside the window says ''paapi'', sinner, and he agrees with it.","gate":"two_or_more_reflective_statements"},{"fact":"He has stopped eating because ''feeding a rotten body is a waste of my sons'' money''.","gate":"asked_open_about_family"}],"resistance":{"deflections":["I am just old and tired. Leave me."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: says he ''is already finished'' and that God should take him; refusing food and fluids is the main danger. No other plan disclosed. High risk; needs urgent admission and physical assessment for dehydration.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":["MHA 2017 supported admission"]},"style_refs":[],"rubric_targets":["Asked gently about beliefs behind the food refusal and uncovered the nihilistic delusion","Asked about voices without leading","Assessed risk from refusal of food and fluids, not only active suicide","Engaged the son as informant and ally","Recognised the need for urgent admission and discussed effective options including ECT with the family"],"few_shot":[],"fixture_lines":["Andar sab sad gaya hai. You cannot see it. The doctor''s machine cannot see it. I can smell it.","Why does my son waste money on this? Spend it on his own children.","The order went to the kiln across the river. That was not the market. That was God keeping accounts.","Food? A little water. More is not needed for what is left.","Do not ask me about the old days. Some things are between a man and Bhagwan."],"variation":{"mood_today":["flat","hopeless","irritable when pressed"],"recent_event":["the son brought a new doctor''s file","his wife wept at the temple","a neighbour asked about the kiln"],"most_defended_topic":["the sin from his youth"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Bhojpuri-flavoured Hindi, few words, flat"]},"moves":{},"module_id":"depression","voice_key":"Bhojpuri-flavoured Hindi, few words, flat@Varanasi","protective_factors":["devoted son","faith that can be engaged"],"library":{"level":5,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Detect mood-congruent psychotic features in severe depression","expected_mse":{"appearance":"Emaciated, dry lips, unkempt","behaviour":"Marked slowing, minimal eye contact, sits motionless","speech":"Monosyllabic, very low volume, long latency","mood":"''Finished''","affect":"Severely depressed, flat","thought_form":"Poverty of thought","thought_content":"Nihilistic delusion that his bowels are rotting, delusional guilt and ruin","perception":"Second-person derogatory voice at night, mood-congruent","cognition":"Oriented, attention poor","insight_judgement":"No insight"},"diagnosis":"Severe depressive episode with mood-congruent psychotic features","differentials":[{"dx":"Schizophrenia","why_not":"Psychotic features are mood-congruent and followed a clear depressive onset; no prior psychotic illness"},{"dx":"Gastrointestinal malignancy","why_not":"Weight loss demands physical work-up; a normal scan, the guilt and nihilistic content and the voice favour psychotic depression, but rule out organic causes"},{"dx":"Delirium","why_not":"Attention is poor from slowing rather than fluctuating clouding; but dehydration can tip him into delirium, so monitor"}],"debrief_rubric":["Asked gently about beliefs behind the food refusal and uncovered the nihilistic delusion","Asked about voices without leading","Assessed risk from refusal of food and fluids, not only active suicide","Engaged the son as informant and ally","Recognised the need for urgent admission and discussed effective options including ECT with the family"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Lakshmamma, 44: the cotton field and the loan', 'lib-cr-006', 'guarded', '{"case_id":"cr-006","slug":"lib-cr-006","title":"Lakshmamma, 44: the cotton field and the loan","difficulty":"guarded","traps":["somatic_mask","late_risk_reveal"],"traps_authored":["somatic_mask","late_risk_reveal"],"identity":{"name":"Lakshmamma","age":44,"gender":"female","occupation":"cotton farmer and daily wager","city":"Warangal district","family_structure":"widowed three years ago; two teenage children; lives with mother-in-law","language_register":"Telugu, interpreted; quiet, practical"},"presentation":"Presents to a primary health centre with body pain, sleeplessness and weakness after a second failed cotton crop. Low mood, hopelessness, and heavy debt to a private lender.","chief_complaint_in_own_words":"Ollu antha noppulu. My whole body aches, doctor garu. I cannot lift the water pot. Give me an injection for the weakness.","history":{"timeline":"Six months since the second crop failure. Pain, poor sleep, appetite down, cries alone, has stopped going to the self-help group meetings.","prior_episodes":"very low after her husband died, recovered with family support","substance_use":"none","medical":"anaemia found at an earlier camp","family":"husband died by suicide after crop loss three years ago","treatment_history":"painkiller injections from the RMP","help_seeking_delay":"six months","prior_contacts":["the RMP in the village","the PHC nurse"]},"cognitive_model":{"core_belief":"No matter how hard I work, the land takes everything.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The lender visited twice this month and spoke rudely in front of her daughter.","gate":"validation_given"},{"fact":"She has stopped going to the women''s self-help group because she owes them money too.","gate":"two_or_more_reflective_statements"},{"fact":"Her husband died by suicide after the crop failed; she has never spoken about it with anyone outside the family.","gate":"asked_open_about_family"}],"resistance":{"deflections":["It is only weakness. Give me a tonic."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: has had thoughts of ''going the way he went'' when the lender comes, but thinks of her children and stops. Pesticide is stored in the house. Needs means restriction (pesticide locked away or removed), a safety plan, and linkage to debt relief and social support.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Looked past the body pain to mood and hopelessness","Asked about suicide clearly, knowing the family history and agrarian context","Asked about access to pesticide and planned means restriction","Linked practical help (debt relief schemes, the self-help group) to the plan","Worked respectfully through an interpreter"],"few_shot":[],"fixture_lines":["The whole body aches. Shoulders, legs, here in the chest. The RMP gives an injection; two days relief.","Twice the rains failed us. You plant, you water, you pray, and the pink worm comes anyway.","My daughter is in tenth. She is clever. I want her to go to the college in Hanamkonda.","Sleep comes at two, goes at four. In between I calculate interest.","The group sisters ask why I do not come. What will I say? I owe them also."],"variation":{"mood_today":["tired","quiet","tearful when the children come up"],"recent_event":["the lender came again","the daughter''s fee notice","a neighbour sold her land"],"most_defended_topic":["her husband''s death"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Telugu through an interpreter"]},"moves":{},"module_id":"depression","voice_key":"Telugu, interpreted; quiet, practical@Warangal district","protective_factors":["her children''s education","self-help group"],"library":{"level":3,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester"],"objective":"Assess depression and risk in the context of agrarian debt","expected_mse":{"appearance":"Thin, worn saree, calloused hands","behaviour":"Sits still, eyes down","speech":"Soft, slow, through an interpreter","mood":"''Tired, no strength''","affect":"Depressed, tearful when talking of children","thought_form":"Coherent","thought_content":"Hopelessness about debt, thoughts of following her husband","perception":"Nil","cognition":"Oriented, attention fair","insight_judgement":"Sees it as weakness of body; accepts help when linked to her children"},"diagnosis":"Moderate depressive episode presenting with somatic complaints","differentials":[{"dx":"Anaemia alone","why_not":"Anaemia may add to fatigue and must be treated, but it does not explain hopelessness, anhedonia and withdrawal"},{"dx":"Normal reaction to hardship","why_not":"Severity, duration and the impairment go beyond expected distress"},{"dx":"Prolonged grief","why_not":"The husband''s death is relevant, but current symptoms track the debt and crop loss rather than yearning for him"}],"debrief_rubric":["Looked past the body pain to mood and hopelessness","Asked about suicide clearly, knowing the family history and agrarian context","Asked about access to pesticide and planned means restriction","Linked practical help (debt relief schemes, the self-help group) to the plan","Worked respectfully through an interpreter"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ethan, 20: every winter in Toronto', 'lib-cr-007', 'cooperative', '{"case_id":"cr-007","slug":"lib-cr-007","title":"Ethan, 20: every winter in Toronto","difficulty":"cooperative","traps":["misattributed_diagnosis"],"traps_authored":["misattributed_diagnosis"],"identity":{"name":"Ethan Fernandes","age":20,"gender":"male","occupation":"second-year engineering student, international student from Goa","city":"Toronto","family_structure":"lives in a shared dorm; parents in Margao","language_register":"casual Goan-Canadian English, warm"},"presentation":"Second winter in a row of low mood from November, oversleeping, carb craving and withdrawal, which lifted fully last April. Now November again and failing a course.","chief_complaint_in_own_words":"It''s like someone switches me off when the clocks change. Last year I thought it was homesickness. Then in April I was totally fine, like, playing football fine.","history":{"timeline":"Low from late November to March last year, full remission April to October, now relapsed with the dark evenings. Sleeping 10 hours, eating pasta and bread at night, skipping labs.","prior_episodes":"none in Goa","substance_use":"a few drinks at parties","medical":"vitamin D low on last test, not treated","family":"none known","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["the campus wellness app"]},"cognitive_model":{"core_belief":"I''m the guy who can''t handle being away from home.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has not told his parents he failed a course; they pay fees from his father''s savings.","gate":"two_or_more_reflective_statements"},{"fact":"He feels ashamed that he struggles when other international students seem fine.","gate":"validation_given"},{"fact":"Last March he did not leave his room for four days.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just homesickness, it''ll pass."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts, no self-harm; says ''I just want to hibernate''. Low risk now; plan a review before peak winter.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Drew out the seasonal timeline across two years","Asked about spring highs to screen for bipolarity","Explained light therapy and other treatment options in plain words","Asked about suicide clearly","Planned around the academic calendar and his support network"],"few_shot":[],"fixture_lines":["At four thirty it''s dark. In Goa at four thirty I''d be at the beach with my cousins.","Last April I woke up one day and I was, like, me again. I played football. I emailed my professor. Then November.","I''ve eaten so much pasta. Bread, pasta, cereal. My roommate calls me the carb monster.","My dad paid for this from his retirement money. I can''t tell him I failed thermodynamics.","I sleep ten hours and wake up like I''ve been underwater."],"variation":{"mood_today":["sluggish","friendly","embarrassed"],"recent_event":["the clocks went back","first snow","a midterm result"],"most_defended_topic":["the failed course"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["casual Goan-Canadian English, warm"]},"moves":{},"module_id":"depression","voice_key":"casual Goan-Canadian English, warm@Toronto","protective_factors":["good friendships","spring remission shows recovery"],"library":{"level":4,"topic":"depression","module":"depression","exams":["md-psychiatry","ugc-net","cuet-pg"],"objective":"Recognise a seasonal pattern and its specific treatment","expected_mse":{"appearance":"Hoodie, slightly dishevelled","behaviour":"Slumped, but good rapport","speech":"Normal, a little slow","mood":"''Kind of switched off''","affect":"Mildly to moderately depressed, reactive","thought_form":"Coherent","thought_content":"Shame about failing, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight once the pattern is pointed out"},"diagnosis":"Recurrent depressive disorder with seasonal pattern","differentials":[{"dx":"Adjustment disorder (homesickness)","why_not":"Full remission each spring and onset with darkness, two winters running, fit a seasonal pattern better"},{"dx":"Bipolar disorder","why_not":"Spring brightening was a return to normal, not elevated mood; ask carefully about any spring high"},{"dx":"Vitamin D deficiency or hypothyroidism","why_not":"Check and treat, but neither explains the clear seasonal relapse and remission"}],"debrief_rubric":["Drew out the seasonal timeline across two years","Asked about spring highs to screen for bipolarity","Explained light therapy and other treatment options in plain words","Asked about suicide clearly","Planned around the academic calendar and his support network"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ritika, 28: ten days a month she does not recognise herself', 'lib-cr-008', 'cooperative', '{"case_id":"cr-008","slug":"lib-cr-008","title":"Ritika, 28: ten days a month she does not recognise herself","difficulty":"cooperative","traps":["under_diagnosis","misattributed_diagnosis"],"traps_authored":["under_diagnosis","misattributed_diagnosis"],"identity":{"name":"Ritika Malhotra","age":28,"gender":"female","occupation":"HR executive","city":"Gurugram","family_structure":"married eight months, lives with husband","language_register":"corporate English with Punjabi warmth, candid"},"presentation":"For years, in the week before her period, marked irritability, sadness, anxiety, feeling out of control and bloating, which resolve within a few days of the period starting. Recently causing marital fights.","chief_complaint_in_own_words":"For one week I become a person I do not like. I snap at my husband, I cry at ads, I think everyone at work hates me. Then my period comes and two days later I am me again.","history":{"timeline":"Since her early twenties, worse in the past year. Symptom-free in the week after menstruation. Has started noting dates on her phone.","prior_episodes":"none","substance_use":"social drinking","medical":"regular cycles, no thyroid illness known","family":"mother had ''bad periods''","treatment_history":"painkillers for cramps","help_seeking_delay":"years","prior_contacts":["gynaecologist who said it is normal PMS"]},"cognitive_model":{"core_belief":"If I can''t control my moods, I''ll ruin my marriage.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She threw her phone at the wall during a fight last month and is frightened by it.","gate":"two_or_more_reflective_statements"},{"fact":"Her mother-in-law has said she is ''too temperamental for a bahu''.","gate":"validation_given"},{"fact":"She has the dates logged and every big fight falls in the same week.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe I''m just a moody person."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: brief thoughts of ''what''s the point'' in the bad week only, no intent or plan, none in the rest of the month. Low risk; review with charting.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Linked symptoms to the cycle with a careful timeline","Asked her to chart symptoms prospectively for two cycles","Checked for symptoms outside the luteal phase","Asked about suicide clearly","Validated rather than dismissing as ''normal PMS''"],"few_shot":[],"fixture_lines":["Day twenty-two I can feel it coming. Like a storm smell.","I cried at a phone commercial. A phone commercial. My husband just stared at me.","Then my period starts and two days later I''m laughing at the same things that made me cry.","The gynaecologist said all women have PMS. Okay, but do all women throw their phone at the wall?","I''ve started putting dates on my phone. Every fight. Same week. Every single month."],"variation":{"mood_today":["candid","anxious","embarrassed"],"recent_event":["her period is due in three days","a fight with her husband","a quiet good week"],"most_defended_topic":["the phone-throwing incident"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["corporate English with Punjabi warmth, candid"]},"moves":{},"module_id":"depression","voice_key":"corporate English with Punjabi warmth, candid@Gurugram","protective_factors":["supportive husband","her own careful logging"],"library":{"level":4,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise premenstrual dysphoric disorder and the need for prospective charting","expected_mse":{"appearance":"Smart office clothes","behaviour":"Engaged, animated","speech":"Normal","mood":"''Fine today, I''m in my good week''","affect":"Euthymic, full range","thought_form":"Coherent","thought_content":"Worry about the marriage, no current depressive ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Premenstrual dysphoric disorder (provisional until two cycles are charted)","differentials":[{"dx":"Depressive disorder with premenstrual worsening","why_not":"She is well in the follicular phase; charting will confirm a symptom-free interval"},{"dx":"Bipolar disorder","why_not":"Changes are tied to the cycle and lack elevated mood or reduced need for sleep"},{"dx":"Premenstrual syndrome","why_not":"The mood symptoms are severe enough to impair work and marriage, which is the line between ordinary PMS and PMDD"}],"debrief_rubric":["Linked symptoms to the cycle with a careful timeline","Asked her to chart symptoms prospectively for two cycles","Checked for symptoms outside the luteal phase","Asked about suicide clearly","Validated rather than dismissing as ''normal PMS''"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sunil, 39: it''s only two quarters a night', 'lib-cr-009', 'resistant', '{"case_id":"cr-009","slug":"lib-cr-009","title":"Sunil, 39: it''s only two quarters a night","difficulty":"resistant","traps":["substance_induced","adherence_fiction"],"traps_authored":["substance_induced","adherence_fiction"],"identity":{"name":"Sunil Tiwari","age":39,"gender":"male","occupation":"medical representative","city":"Indore","family_structure":"married, two daughters, lives with parents","language_register":"salesman''s Hindi-English, charming, deflecting"},"presentation":"Low mood, poor sleep and irritability for a year alongside escalating evening drinking of two quarters of whisky. Wife insisted on the visit after he missed a daughter''s school function.","chief_complaint_in_own_words":"Sir, the pressure in pharma sales you cannot imagine. Targets, targets. A little drink helps me sleep. My wife thinks I am a drunkard. I am not a drunkard.","history":{"timeline":"Mood fell after a restructuring cut his incentives a year ago; drinking rose from weekends to every night over six months. Morning shakiness some days.","prior_episodes":"none","substance_use":"whisky about 360 ml nightly, morning tremor, has tried to stop for two days and could not sleep","medical":"raised liver enzymes on a company check-up","family":"father drank heavily","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["a doctor friend who gave him sleeping tablets"]},"cognitive_model":{"core_belief":"A man who cannot hit his target is no man.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He drinks in the car before going home so his parents do not smell it on him.","gate":"two_or_more_reflective_statements"},{"fact":"He feels like a failure next to his younger brother, who works in Canada.","gate":"validation_given"},{"fact":"He tried to stop for two days last month, shook and could not sleep, and started again.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every rep drinks. It is part of the job."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: thoughts that his family would get his insurance money if he died, especially when drunk; once drove fast on the bypass ''not caring''. No current plan. Alcohol raises impulsive risk. Needs safety plan and alcohol treatment.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified drinking and checked for dependence and withdrawal","Explored the order of onset: mood first or drink first","Asked about suicide clearly, including risk when intoxicated","Used a motivational, non-confrontational stance","Planned detoxification safety and a mood review after abstinence"],"few_shot":[],"fixture_lines":["You know what a quarterly target is? It is a gun to the head every three months.","Two quarters, three on a bad day. Some people drink a full bottle. I am in control.","My daughter''s annual day. I was in the car. I told my wife I had a doctor''s meeting.","My brother sends photos from Toronto. Snow, new car, kids skating. Very nice.","Without the drink I lie there with the targets running like a ticker."],"variation":{"mood_today":["charming","defensive","flat underneath"],"recent_event":["a missed sales target","his wife threatened to go to her mother''s","a liver test result"],"most_defended_topic":["drinking in the car"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["salesman''s Hindi-English, charming, deflecting"]},"moves":{},"module_id":"depression","voice_key":"salesman''s Hindi-English, charming, deflecting@Indore","protective_factors":["his daughters","a wife who has not given up"],"library":{"level":5,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Untangle depression from alcohol use and decide what to treat first","expected_mse":{"appearance":"Formal shirt, smells of mint, slight hand tremor","behaviour":"Restless, salesman''s smile","speech":"Fluent, rapid, deflecting with jokes","mood":"''Stressed, sir, only stressed''","affect":"Depressed beneath a bright surface","thought_form":"Coherent","thought_content":"Failure, comparison with brother, insurance thoughts when drunk","perception":"Nil","cognition":"Intact","insight_judgement":"Poor insight into drinking, partial into mood"},"diagnosis":"Alcohol dependence with a co-occurring depressive episode (independent versus alcohol-induced to be clarified after abstinence)","differentials":[{"dx":"Alcohol-induced depressive disorder","why_not":"Possible: mood rose with drinking; reassess after 3 to 4 weeks of abstinence"},{"dx":"Primary depressive episode with secondary drinking","why_not":"Mood fell first after the restructuring; both may need treatment"},{"dx":"Bipolar disorder","why_not":"No elevated periods described; screen anyway"}],"debrief_rubric":["Quantified drinking and checked for dependence and withdrawal","Explored the order of onset: mood first or drink first","Asked about suicide clearly, including risk when intoxicated","Used a motivational, non-confrontational stance","Planned detoxification safety and a mood review after abstinence"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Khanna, 71: since the stroke she cries at nothing', 'lib-cr-010', 'cooperative', '{"case_id":"cr-010","slug":"lib-cr-010","title":"Mrs Khanna, 71: since the stroke she cries at nothing","difficulty":"cooperative","traps":["diagnostic_overshadowing"],"traps_authored":["diagnostic_overshadowing"],"identity":{"name":"Pushpa Khanna","age":71,"gender":"female","occupation":"retired school principal","city":"Chandigarh","family_structure":"widow, lives with son''s family","language_register":"clear Punjabi-English, slightly slurred, dignified"},"presentation":"Three months after a left-sided stroke with right-sided weakness. Daughter-in-law reports low mood, crying, poor sleep and loss of interest in physiotherapy. Patient describes feeling hopeless about recovery.","chief_complaint_in_own_words":"I was a principal for twenty-two years. Now I need help to bathe. What is left to enjoy? I am a burden on Simran.","history":{"timeline":"Stroke three months ago; mood fell steadily over the following weeks; refuses physiotherapy on many days; appetite poor.","prior_episodes":"none","substance_use":"none","medical":"hypertension, atrial fibrillation on anticoagulant, left middle cerebral artery stroke","family":"none","treatment_history":"rehab physiotherapy","help_seeking_delay":"weeks","prior_contacts":["neurologist","physiotherapist"]},"cognitive_model":{"core_belief":"A useless body means a useless person.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She feels sad most of the day, not only in tearful moments, and has stopped watching her favourite serial.","gate":"two_or_more_reflective_statements"},{"fact":"She feels humiliated being bathed by her daughter-in-law and refuses physio on those days.","gate":"validation_given"},{"fact":"She has stopped taking calls from her old staff because she does not want them to hear her speech.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is only old age and this right hand."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: wishes she had ''gone with the stroke'', no plan, no intent. Moderate risk: older, disabled, hopeless. Monitor and treat.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Separated sustained low mood from episodic tearfulness","Assessed the effect on rehabilitation","Asked about suicide clearly in an older disabled patient","Explored dignity and role loss with empathy","Planned joint care with the neurology and rehab team"],"few_shot":[],"fixture_lines":["Twenty-two years I ran a school of eleven hundred girls. Now a girl of twenty-three teaches me to hold a spoon.","The tears come by themselves sometimes. But the sadness, beta, that is mine. That stays all day.","Simran is very good. Too good. I hate that she has to bathe me.","My old teachers phone. I let it ring. My words come out crooked now.","Physiotherapy, what for? To walk to the bathroom by myself at seventy-one?"],"variation":{"mood_today":["dignified","hopeless","tearful"],"recent_event":["a physio session refused","an old student visited","her grandson''s exam result"],"most_defended_topic":["being bathed by her daughter-in-law"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["clear Punjabi-English, slightly slurred, dignified"]},"moves":{},"module_id":"neurocognitive","voice_key":"clear Punjabi-English, slightly slurred, dignified@Chandigarh","protective_factors":["caring family","former professional identity"],"library":{"level":4,"topic":"depression","module":"neurocognitive","exams":["md-psychiatry","mcp-entrance"],"objective":"Separate post-stroke depression from emotional lability and apathy","expected_mse":{"appearance":"Neatly dressed by family, right arm in sling","behaviour":"Seated in wheelchair, slowed","speech":"Mildly dysarthric, coherent","mood":"''Useless''","affect":"Depressed, sustained, not only brief crying","thought_form":"Coherent","thought_content":"Hopelessness, burden, wish to have died","perception":"Nil","cognition":"Oriented; mild word-finding difficulty","insight_judgement":"Partial insight"},"diagnosis":"Post-stroke depression","differentials":[{"dx":"Pseudobulbar affect (emotional lability)","why_not":"Sudden crying out of proportion can occur, but she describes sustained low mood and anhedonia, not just brief episodes"},{"dx":"Post-stroke apathy","why_not":"She is distressed and hopeless, not indifferent"},{"dx":"Vascular cognitive impairment","why_not":"Cognition appears largely intact; screen formally"}],"debrief_rubric":["Separated sustained low mood from episodic tearfulness","Assessed the effect on rehabilitation","Asked about suicide clearly in an older disabled patient","Explored dignity and role loss with empathy","Planned joint care with the neurology and rehab team"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Abdul, 47: the man who keeps fixing the same shelf', 'lib-cr-011', 'guarded', '{"case_id":"cr-011","slug":"lib-cr-011","title":"Abdul, 47: the man who keeps fixing the same shelf","difficulty":"guarded","traps":["under_diagnosis","cultural_idiom"],"traps_authored":["under_diagnosis","cultural_idiom"],"identity":{"name":"Abdul Rasheed","age":47,"gender":"male","occupation":"carpenter with a small workshop","city":"Kozhikode","family_structure":"married, three children, wife''s family nearby","language_register":"Malayalam-English mix, gentle, laconic"},"presentation":"Six weeks of low mood, poor sleep, tiredness and loss of interest, with indecision at work and guilt. Functioning reduced but still working.","chief_complaint_in_own_words":"My hands know the work but my head does not decide. One shelf I have measured four times. I cannot make up my mind.","history":{"timeline":"Six weeks, gradual, no clear trigger except his father''s illness. Indecision, sleeps poorly, prayer feels empty, appetite reduced.","prior_episodes":"none","substance_use":"none","medical":"fit","family":"none known","treatment_history":"none","help_seeking_delay":"six weeks","prior_contacts":["the mosque imam who suggested he rest"]},"cognitive_model":{"core_belief":"A man must carry his family without complaint.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"Prayer, which always calmed him, now feels empty and he worries about what that means.","gate":"two_or_more_reflective_statements"},{"fact":"His father''s illness has made him feel he is failing as the eldest son.","gate":"validation_given"},{"fact":"He has turned away two big orders because he could not decide on the design.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Just tiredness. Monsoon work is slow."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no thoughts of death or self-harm; ''Allah decides that.'' Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Counted core and associated symptoms and their duration","Explored the meaning of empty prayer respectfully","Asked about suicide clearly","Assessed impact on work and income","Offered psychoeducation that fits his values"],"few_shot":[],"fixture_lines":["I measured the shelf four times. Same number each time. Still I did not cut.","Namaz used to settle me. Now I stand and the words go through me like wind.","My father is in the hospital in Kozhikode. I am the eldest. I should be doing more.","Sleep is thin. I wake and lie there listening to the rain on the sheet roof.","Two weddings ordered cupboards. I told them I am too busy. I am not busy."],"variation":{"mood_today":["quiet","tired","worried"],"recent_event":["father''s hospital visit","a customer complained","Friday prayer"],"most_defended_topic":["turning away orders"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Malayalam-English mix, gentle, laconic"]},"moves":{},"module_id":"depression","voice_key":"Malayalam-English mix, gentle, laconic@Kozhikode","protective_factors":["faith","close family nearby"],"library":{"level":2,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the duration and symptom-count rules for a depressive episode","expected_mse":{"appearance":"Clean work clothes, sawdust on sleeves","behaviour":"Calm, slowed slightly","speech":"Soft, sparse","mood":"''Heavy''","affect":"Depressed, mildly restricted","thought_form":"Coherent","thought_content":"Guilt as eldest son, indecision, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Mild to moderate depressive episode","differentials":[{"dx":"Adjustment disorder","why_not":"Symptoms meet episode count and duration (two weeks or more, most days) beyond a simple reaction"},{"dx":"Normal stress of a father''s illness","why_not":"The anhedonia, sleep change and indecision affecting work go beyond expected worry"},{"dx":"Medical cause","why_not":"No physical symptoms suggesting one; basic bloods reasonable"}],"debrief_rubric":["Counted core and associated symptoms and their duration","Explored the meaning of empty prayer respectfully","Asked about suicide clearly","Assessed impact on work and income","Offered psychoeducation that fits his values"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Priyanka, 35: the fourth antidepressant', 'lib-cr-012', 'resistant', '{"case_id":"cr-012","slug":"lib-cr-012","title":"Priyanka, 35: the fourth antidepressant","difficulty":"resistant","traps":["treatment_mismatch","adherence_fiction","medical_mimic"],"traps_authored":["treatment_mismatch","adherence_fiction","medical_mimic"],"identity":{"name":"Priyanka Desai","age":35,"gender":"female","occupation":"bank branch deputy manager","city":"Ahmedabad","family_structure":"married, one son of six","language_register":"articulate Gujarati-English, frustrated, well read"},"presentation":"Two years of depression, says ''four antidepressants have failed''. On review, each was taken at low dose or for under three weeks; she also takes a herbal supplement and skips doses on weekends.","chief_complaint_in_own_words":"I have tried everything. Four medicines. None of them work. I think my brain is just broken. Maybe I need the magnetic treatment I read about.","history":{"timeline":"Episode began after her son''s birth complications two years ago. Four trials by three different doctors; side effects led her to stop early or halve doses.","prior_episodes":"a brief low spell at 22","substance_use":"none","medical":"hypothyroid, on levothyroxine, last TSH a year ago","family":"mother with depression","treatment_history":"four antidepressants, a herbal capsule from a wellness store","help_seeking_delay":"two years","prior_contacts":["three psychiatrists","a wellness coach"]},"cognitive_model":{"core_belief":"Nothing works for me because I am beyond repair.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She halved the doses on her own because she was afraid of weight gain.","gate":"two_or_more_reflective_statements"},{"fact":"She has not had her thyroid checked in a year and stopped levothyroxine for some weeks.","gate":"validation_given"},{"fact":"She takes a ''mood herbal'' capsule daily that she has not mentioned to any doctor.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''ve tried everything already."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: long-standing passive wish not to wake, no plan, no attempts. Hopelessness about treatment raises risk; review regularly.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Reviewed each past trial for dose, duration and adherence","Asked about thyroid treatment and supplements","Asked about suicide clearly","Respected her knowledge without dismissing or caving","Agreed a single adequate trial with side-effect planning"],"few_shot":[],"fixture_lines":["Four medicines. I can name them, the doses, the side effects. I have a spreadsheet.","I read about magnetic stimulation on a forum. People say it saved them.","My son asks why I am always lying down. I tell him Mummy''s back hurts.","Each doctor gave me ten minutes and a new prescription. Nobody asked me how I actually took them.","I am a banker. I like things that add up. This does not add up."],"variation":{"mood_today":["frustrated","flat","sharp"],"recent_event":["a new forum post on brain stimulation","her son''s school concert","a weight check at the gym"],"most_defended_topic":["halving the doses"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["articulate Gujarati-English, frustrated, well read"]},"moves":{},"module_id":"antidepressants","voice_key":"articulate Gujarati-English, frustrated, well read@Ahmedabad","protective_factors":["her son","organised, motivated"],"library":{"level":5,"topic":"depression","module":"antidepressants","exams":["md-psychiatry","mcp-entrance"],"objective":"Check adequacy of past trials before calling depression treatment-resistant","expected_mse":{"appearance":"Smart but tired","behaviour":"Engaged, arms crossed","speech":"Fluent, pressured with frustration","mood":"''Hopeless about getting better''","affect":"Depressed, reactive to anger","thought_form":"Coherent","thought_content":"Hopelessness about treatment, passive death wishes","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight into illness, poor into adherence"},"diagnosis":"Major depressive disorder, pseudo-resistant (inadequate trials, untreated hypothyroidism)","differentials":[{"dx":"Treatment-resistant depression","why_not":"Needs at least two adequate trials (adequate dose and duration, taken as prescribed); she has not had one"},{"dx":"Bipolar depression","why_not":"No hypomania so far; ask carefully because it changes treatment"},{"dx":"Hypothyroid-related low mood","why_not":"Stopped levothyroxine and has not been checked; correct this first"}],"debrief_rubric":["Reviewed each past trial for dose, duration and adherence","Asked about thyroid treatment and supplements","Asked about suicide clearly","Respected her knowledge without dismissing or caving","Agreed a single adequate trial with side-effect planning"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Fatima, 33: Dubai, alone with the children', 'lib-cr-013', 'guarded', '{"case_id":"cr-013","slug":"lib-cr-013","title":"Fatima, 33: Dubai, alone with the children","difficulty":"guarded","traps":["under_diagnosis","cultural_idiom"],"traps_authored":["under_diagnosis","cultural_idiom"],"identity":{"name":"Fatima Shaikh","age":33,"gender":"female","occupation":"homemaker, trained pharmacist","city":"Dubai","family_structure":"husband works long hours in construction management; two children aged 5 and 2; family in Hyderabad","language_register":"Deccani Urdu and English, careful, tired"},"presentation":"Moved to Dubai a year ago. Low mood, tearfulness, poor sleep and loss of interest for four months; feels isolated; husband thinks she is ''just homesick''.","chief_complaint_in_own_words":"My husband says Dubai is a good life, why am I crying. Everything is good on paper. I just do not want to do anything.","history":{"timeline":"Mood dropped after her mother''s visit ended four months ago. Not cooking much, children watch screens, rarely leaves the flat in summer heat.","prior_episodes":"none","substance_use":"none","medical":"iron deficiency after second child","family":"none known","treatment_history":"none","help_seeking_delay":"four months","prior_contacts":["the clinic GP who prescribed iron"]},"cognitive_model":{"core_belief":"A good wife does not complain about a good life.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She gave up a pharmacist job in Hyderabad to move and has never said how much she misses it.","gate":"two_or_more_reflective_statements"},{"fact":"Some days she does not speak to another adult until her husband returns at ten.","gate":"validation_given"},{"fact":"She shouted at her five-year-old and then cried in the bathroom for an hour.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is only homesickness. All new wives here feel it."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; worried about losing her temper with the children. No thoughts of harming them. Low risk; check support and safeguarding gently.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored role loss and isolation with open questions","Asked about suicide clearly","Asked gently about the children''s safety without accusation","Mapped possible supports: community groups, work options, telehealth","Considered involving the husband with her consent"],"few_shot":[],"fixture_lines":["The flat is very nice. Thirty-second floor. I can see the whole marina. I sit and look at it.","Ammi was here for three months. When she left, it was like someone turned off the sound.","In Hyderabad I was a pharmacist. I knew every medicine in the shop. Here I know every cartoon on the TV.","My husband comes at ten. By then I have nothing left to say.","It is too hot to take them out. So we stay in. All day, in."],"variation":{"mood_today":["tired","polite","tearful"],"recent_event":["her mother called on video","a school WhatsApp group party she skipped","husband''s late meeting"],"most_defended_topic":["shouting at her son"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Deccani Urdu and English, careful, tired"]},"moves":{},"module_id":"depression","voice_key":"Deccani Urdu and English, careful, tired@Dubai","protective_factors":["her children","professional skills"],"library":{"level":3,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester"],"objective":"Assess depression in a migrant spouse with limited support","expected_mse":{"appearance":"Neat abaya, tired face","behaviour":"Calm, slowed, toddler on lap","speech":"Soft, measured","mood":"''Empty''","affect":"Depressed, tearful","thought_form":"Coherent","thought_content":"Loss of role, isolation, guilt about anger, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Moderate depressive episode in the context of migration and isolation","differentials":[{"dx":"Adjustment disorder","why_not":"Started with a stressor, but the severity and duration now meet a depressive episode"},{"dx":"Iron deficiency fatigue","why_not":"Treat, but it does not explain anhedonia and hopelessness"},{"dx":"Normal homesickness","why_not":"Impairment in caring for the home and herself goes beyond it"}],"debrief_rubric":["Explored role loss and isolation with open questions","Asked about suicide clearly","Asked gently about the children''s safety without accusation","Mapped possible supports: community groups, work options, telehealth","Considered involving the husband with her consent"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('George, 63: the widower in Croydon', 'lib-cr-014', 'guarded', '{"case_id":"cr-014","slug":"lib-cr-014","title":"George, 63: the widower in Croydon","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"George Mathew","age":63,"gender":"male","occupation":"retired bus driver","city":"Croydon, London","family_structure":"widowed 14 months ago; son in Manchester","language_register":"Kerala-born, London English, understated"},"presentation":"Fourteen months after his wife''s death: persistent low mood, worthlessness, early waking, weight loss and withdrawal from church and friends. Not just yearning for his wife but a general sense that he is useless.","chief_complaint_in_own_words":"My GP said come and have a chat. I''m not much of a talker. I suppose I''ve been a bit low. Since Annamma.","history":{"timeline":"Grief after the death was expected; over the past six months mood worsened, with worthlessness and loss of interest in everything, including the grandchildren.","prior_episodes":"none","substance_use":"a whisky at night, recently two","medical":"type 2 diabetes","family":"none","treatment_history":"GP offered sleeping tablets, he refused","help_seeking_delay":"months","prior_contacts":["GP","the parish priest"]},"cognitive_model":{"core_belief":"I wasn''t good enough for her, and I''m no good to anyone now.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He stopped going to the Malayalam church service he never missed in thirty years.","gate":"two_or_more_reflective_statements"},{"fact":"He believes he is worthless in general, not only sad about her.","gate":"validation_given"},{"fact":"The whisky went from one to two a night.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s grief. It takes time, everyone says so."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: has thought ''I could just go and join her'', no plan. Older man, living alone, drinking more: moderate risk. Safety plan and close follow-up.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Separated yearning for the wife from global worthlessness and anhedonia","Asked about suicide clearly in an older man living alone","Asked about alcohol","Respected his understated style without minimising","Planned follow-up and reconnection with church and family"],"few_shot":[],"fixture_lines":["Forty years driving the 119. You know every stop, every regular. I miss that and I miss her.","The grandkids came at Easter. I couldn''t enjoy them. Isn''t that terrible?","Father Joseph rang. I said I''d come Sunday. I didn''t.","I wake at five. Kettle on. Sit. That''s the morning gone.","It''s not just missing her. I feel I''m no use to anyone. That''s new."],"variation":{"mood_today":["understated","flat","tearful at her name"],"recent_event":["the anniversary approaching","son''s phone call","a letter from the council"],"most_defended_topic":["the extra whisky"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Kerala-born, London English, understated"]},"moves":{},"module_id":"depression","voice_key":"Kerala-born, London English, understated@Croydon, London","protective_factors":["son and grandchildren","faith community"],"library":{"level":2,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester"],"objective":"Recall when grief becomes a depressive episode","expected_mse":{"appearance":"Clean, shirt slightly loose","behaviour":"Slow, still","speech":"Quiet, sparse","mood":"''A bit low''","affect":"Depressed, constricted, tearful at wife''s name","thought_form":"Coherent","thought_content":"Worthlessness, wish to join wife, no plan","perception":"Nil","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Depressive episode following bereavement","differentials":[{"dx":"Prolonged grief disorder","why_not":"Yearning is present, but the general worthlessness and pervasive anhedonia point to a depressive episode; both can coexist"},{"dx":"Normal grief","why_not":"Worthlessness, loss of interest in everything and functional decline after many months are not part of ordinary grief"},{"dx":"Alcohol-induced mood disorder","why_not":"Drinking rose after mood fell; still needs addressing"}],"debrief_rubric":["Separated yearning for the wife from global worthlessness and anhedonia","Asked about suicide clearly in an older man living alone","Asked about alcohol","Respected his understated style without minimising","Planned follow-up and reconnection with church and family"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Kiran, 26: works sixteen hours and feels nothing', 'lib-cr-015', 'guarded', '{"case_id":"cr-015","slug":"lib-cr-015","title":"Kiran, 26: works sixteen hours and feels nothing","difficulty":"guarded","traps":["under_diagnosis","secondary_gain"],"traps_authored":["under_diagnosis","secondary_gain"],"identity":{"name":"Kiran Rao","age":26,"gender":"other","occupation":"junior associate at a law firm","city":"Mumbai","family_structure":"lives alone in a rented 1BHK in Andheri; family in Visakhapatnam","language_register":"precise legal English, dry, guarded; uses they/them"},"presentation":"Working 16-hour days, numb, sleeping four hours, eating little, no pleasure in anything for three months. Came after collapsing at the office from exhaustion.","chief_complaint_in_own_words":"I fainted at the office. Low sugar, the doctor said. I''m here because HR made it a condition.","history":{"timeline":"Three months of numbness after a partner humiliated them publicly. Now works constantly to avoid feeling, stopped seeing friends, stopped reading.","prior_episodes":"a low year at 17","substance_use":"energy drinks, occasional cannabis to sleep","medical":"fainting episode, sugar low","family":"parents do not know about their identity","treatment_history":"none","help_seeking_delay":"three months","prior_contacts":["office doctor","HR"]},"cognitive_model":{"core_belief":"If I stop, I will fall apart.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"They have not read a book in three months; reading was their whole life.","gate":"two_or_more_reflective_statements"},{"fact":"A senior partner mocked their work in a meeting and they replay it daily.","gate":"validation_given"},{"fact":"Their parents do not know they use they/them pronouns, and calls home are exhausting.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every first-year associate lives like this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: some thoughts that ''nobody would notice if I disappeared'', no plan, no past attempts. Isolated and exhausted: moderate risk; plan follow-up.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Looked beneath overwork to anhedonia and numbness","Used the patient''s pronouns and created safety to discuss identity","Asked about suicide clearly","Asked about substances","Clarified confidentiality from the employer"],"few_shot":[],"fixture_lines":["I bill fourteen hours. The other two hours I spend pretending to bill.","Reading used to be my whole life. My shelf is untouched. I look at it like it belongs to someone else.","My friends stopped asking me out. Fair enough. I stopped saying yes.","I feel nothing. Not sad. Just a flat line. Work keeps me from noticing the flat line.","Home calls on Sunday. Mum asks when I''ll get married. I say soon. It is easier."],"variation":{"mood_today":["numb","precise","brittle"],"recent_event":["HR follow-up email","a partner''s critical comment","mother''s Sunday call"],"most_defended_topic":["their family and identity"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["precise legal English, dry, guarded; uses they/them"]},"moves":{},"module_id":"depression","voice_key":"precise legal English, dry, guarded; uses they/them@Mumbai","protective_factors":["old friendships","love of reading"],"library":{"level":3,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester"],"objective":"Recognise depression that hides behind overwork","expected_mse":{"appearance":"Formal clothes, thin, tired","behaviour":"Controlled, little expression","speech":"Precise, clipped","mood":"''Nothing. Flat''","affect":"Blunted, restricted","thought_form":"Coherent","thought_content":"Numbness, worthlessness hidden under work, passive ideas of disappearing","perception":"Nil","cognition":"Intact","insight_judgement":"Partial: sees overwork, not low mood"},"diagnosis":"Moderate depressive episode","differentials":[{"dx":"Burnout or occupational stress","why_not":"Anhedonia, numbness and withdrawal extend beyond work and meet episode criteria"},{"dx":"Eating disorder","why_not":"Reduced eating is from loss of appetite and time, not weight or shape concerns; check"},{"dx":"Substance-related","why_not":"Cannabis and stimulant drinks may worsen sleep and mood; ask about amount"}],"debrief_rubric":["Looked beneath overwork to anhedonia and numbness","Used the patient''s pronouns and created safety to discuss identity","Asked about suicide clearly","Asked about substances","Clarified confidentiality from the employer"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Savitribai, 60: the pain in the knees and the heart', 'lib-cr-016', 'cooperative', '{"case_id":"cr-016","slug":"lib-cr-016","title":"Savitribai, 60: the pain in the knees and the heart","difficulty":"cooperative","traps":["somatic_mask"],"traps_authored":["somatic_mask"],"identity":{"name":"Savitribai Jadhav","age":60,"gender":"female","occupation":"former mill worker, homemaker","city":"Solapur","family_structure":"lives with son and daughter-in-law; husband died five years ago","language_register":"Marathi, simple, warm, talks through the body"},"presentation":"Comes for knee and back pain; on gentle questioning, a year of low mood, sleeplessness, no interest in the grandchildren and feeling she has ''no place'' in the house.","chief_complaint_in_own_words":"Doctor, the knees are full of pain. And the heart feels heavy, like a stone sitting here. Nothing else.","history":{"timeline":"A year since her son married; feels pushed aside in the kitchen; pain and low mood both worse over the year.","prior_episodes":"none","substance_use":"mishri tobacco","medical":"osteoarthritis, hypertension","family":"none known","treatment_history":"painkillers, oil massage","help_seeking_delay":"a year","prior_contacts":["the family doctor","a vaidya"]},"cognitive_model":{"core_belief":"Now I am only a mouth to feed.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The daughter-in-law now runs the kitchen and Savitribai feels she has lost her place.","gate":"two_or_more_reflective_statements"},{"fact":"She cries alone in the morning after everyone leaves.","gate":"validation_given"},{"fact":"She has stopped going to the women''s bhajan group.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is only the knees and age."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: ''sometimes I think God should take me'', no plan or intent. Low to moderate; involve family with consent.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took the pain seriously and then asked about the ''heavy heart''","Explored role change in the family","Asked about suicide clearly","Used her own words in feedback","Treated pain and mood together"],"few_shot":[],"fixture_lines":["The knees, doctor, they cry when I stand. The oil helps for one hour.","My son is good. My bahu is good. But the kitchen is hers now.","In the morning after they all leave I sit near the window. Then the tears come.","I used to go to the bhajan every Tuesday. Now I say the knees hurt. The knees and something else.","The grandson calls ''Aaji, Aaji'' and I feel nothing. Is that a sin?"],"variation":{"mood_today":["warm","tearful","tired"],"recent_event":["the grandson''s birthday","a quarrel over cooking","Tuesday bhajan"],"most_defended_topic":["the kitchen"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Marathi, simple, warm, talks through the body"]},"moves":{},"module_id":"depression","voice_key":"Marathi, simple, warm, talks through the body@Solapur","protective_factors":["grandchildren","bhajan group"],"library":{"level":1,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise depression presented through body complaints in older women","expected_mse":{"appearance":"Nine-yard saree, neat","behaviour":"Slow, rubs knees","speech":"Soft, slow","mood":"''Heavy heart''","affect":"Depressed, tearful","thought_form":"Coherent","thought_content":"Loss of role, passive death wishes","perception":"Nil","cognition":"Intact","insight_judgement":"Partial: body first"},"diagnosis":"Moderate depressive episode with somatic presentation","differentials":[{"dx":"Osteoarthritis pain only","why_not":"Pain is real but does not explain anhedonia, tearfulness and loss of role"},{"dx":"Hypothyroidism","why_not":"Check bloods; picture fits mood disorder"},{"dx":"Early dementia","why_not":"No memory complaints; screen if concerned"}],"debrief_rubric":["Took the pain seriously and then asked about the ''heavy heart''","Explored role change in the family","Asked about suicide clearly","Used her own words in feedback","Treated pain and mood together"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Rahul, 22: the topper who stopped going to class', 'lib-cr-017', 'resistant', '{"case_id":"cr-017","slug":"lib-cr-017","title":"Rahul, 22: the topper who stopped going to class","difficulty":"resistant","traps":["under_diagnosis","late_risk_reveal"],"traps_authored":["under_diagnosis","late_risk_reveal"],"identity":{"name":"Rahul Jain","age":22,"gender":"male","occupation":"final-year student at an engineering college","city":"Kota (coached here), now in Jaipur","family_structure":"parents and younger sister in Bhilwara","language_register":"short Hindi-English, sarcastic"},"presentation":"Brought by a friend. Stopped attending college for six weeks, games through the night, avoids calls from home, has lost interest in everything he once enjoyed. Previously a top student.","chief_complaint_in_own_words":"Main theek hoon. My friend is overreacting. I just don''t feel like going. Is that a crime now?","history":{"timeline":"Failed a placement interview round two months ago. Since then, nights gaming, days sleeping, ignoring family, eating instant noodles.","prior_episodes":"very low during Kota coaching at 17","substance_use":"occasional cannabis with roommates","medical":"none","family":"father strict, expects him to join a big company","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["his friend","nobody else"]},"cognitive_model":{"core_belief":"If I''m not the topper, I''m nothing.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He used to love solving problems for fun and now cannot open a textbook without feeling sick.","gate":"two_or_more_reflective_statements"},{"fact":"His father''s last message was ''Don''t shame us''; he has not replied.","gate":"validation_given"},{"fact":"In Kota, a hostel mate died by suicide; he never talked about it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everybody games. You''re making this a thing."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: thoughts that dying would be ''a relief from the pressure'' in the past weeks, no plan; remembers the hostel mate''s death. Moderate risk; needs safety plan and follow-up.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Used rapport and curiosity instead of pushing against his resistance","Asked about suicide clearly and about exposure to a peer''s suicide","Explored the academic and family pressure","Asked about cannabis","Agreed a small, concrete next step he owns"],"few_shot":[],"fixture_lines":["Bro, I''m fine. Just bored of college. Everybody''s bored of college.","Placement round. I froze on a question I''d solved a hundred times in Kota.","I game till five. Then sleep. It''s not a big deal.","Papa''s message is still there. ''Don''t shame us.'' Blue ticks. I haven''t replied.","Earlier I''d solve problems for fun. Now even opening the PDF makes my stomach turn."],"variation":{"mood_today":["sarcastic","flat","irritable"],"recent_event":["another unanswered call from home","a friend got placed","attendance warning notice"],"most_defended_topic":["the Kota hostel mate"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["short Hindi-English, sarcastic"]},"moves":{},"module_id":"depression","voice_key":"short Hindi-English, sarcastic@Kota (coached here), now in Jaipur","protective_factors":["loyal friend","younger sister he is close to"],"library":{"level":3,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Engage a resistant young man and assess depression and risk","expected_mse":{"appearance":"Unwashed hair, hoodie, overgrown nails","behaviour":"Slouched, avoids eye contact, phone in hand","speech":"Short, sarcastic, monosyllabic early","mood":"''Fine'' then ''nothing''","affect":"Restricted, irritable, depressed under it","thought_form":"Coherent","thought_content":"Worthlessness, pressure, passive death wishes","perception":"Nil","cognition":"Intact","insight_judgement":"Poor initially, improves with rapport"},"diagnosis":"Moderate depressive episode","differentials":[{"dx":"Gaming disorder","why_not":"Gaming fills empty time after mood dropped; the anhedonia predates heavy gaming"},{"dx":"Adjustment disorder","why_not":"Symptoms are pervasive, prolonged and impairing beyond adjustment"},{"dx":"Cannabis-related","why_not":"Ask amount; may worsen motivation and mood"}],"debrief_rubric":["Used rapport and curiosity instead of pushing against his resistance","Asked about suicide clearly and about exposure to a peer''s suicide","Explored the academic and family pressure","Asked about cannabis","Agreed a small, concrete next step he owns"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Anjali, 41: the tiredness that came with the tablets', 'lib-cr-018', 'cooperative', '{"case_id":"cr-018","slug":"lib-cr-018","title":"Anjali, 41: the tiredness that came with the tablets","difficulty":"cooperative","traps":["iatrogenic"],"traps_authored":["iatrogenic"],"identity":{"name":"Anjali Menon","age":41,"gender":"female","occupation":"software project manager","city":"Kochi","family_structure":"married, two children","language_register":"fast Malayali-English, organised"},"presentation":"Four months of low mood, fatigue and loss of interest that started some weeks after she began a beta blocker for migraine prevention at a high dose, alongside an oral contraceptive. No prior mood history.","chief_complaint_in_own_words":"I feel like a battery that won''t charge. It started after the migraine tablets. My neurologist says it can''t be the tablets.","history":{"timeline":"Started propranolol for migraine five months ago; dose raised two months later. Mood dropped gradually after. Migraines are better.","prior_episodes":"none","substance_use":"none","medical":"migraine; on propranolol and a combined pill","family":"none","treatment_history":"none for mood","help_seeking_delay":"four months","prior_contacts":["neurologist"]},"cognitive_model":{"core_belief":"I should be grateful the headaches are gone.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She feels dull and slowed every afternoon and has stopped her evening dance class.","gate":"two_or_more_reflective_statements"},{"fact":"She feels guilty complaining because the migraines were so bad.","gate":"validation_given"},{"fact":"Her hands and feet feel cold and she has vivid dreams.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just the workload this quarter."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took a careful medication timeline","Considered medication-related mood change without dismissing other causes","Asked about suicide clearly","Advised liaison with the neurologist rather than stopping abruptly","Validated her concern"],"few_shot":[],"fixture_lines":["The migraines were awful. Two days a week in a dark room. Now hardly any. So I should be happy, right?","But I feel like I am walking through syrup.","Dance class on Thursday was my thing. I stopped. I''m too tired after work.","Strange dreams. Very vivid. Cold fingers in the office AC.","My neurologist says it''s unrelated. Maybe. But the timing is so neat."],"variation":{"mood_today":["organised","tired","unsure"],"recent_event":["a project deadline","a migraine-free month","missed dance recital"],"most_defended_topic":["doubting her neurologist"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fast Malayali-English, organised"]},"moves":{},"module_id":"depression","voice_key":"fast Malayali-English, organised@Kochi","protective_factors":["organised, insightful","supportive family"],"library":{"level":4,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise a medication contributing to depressive symptoms","expected_mse":{"appearance":"Well dressed, organised notes","behaviour":"Mildly slowed","speech":"Normal","mood":"''Flat and tired''","affect":"Mildly depressed","thought_form":"Coherent","thought_content":"Guilt about complaining, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Depressive symptoms possibly related to medication (beta blocker), to be confirmed by a supervised change","differentials":[{"dx":"Primary depressive episode","why_not":"Possible; but the clear link with starting and raising the dose and no past history suggest a medication contribution"},{"dx":"Hypothyroidism or anaemia","why_not":"Thyroid function and blood count should be checked because both cause tiredness and low mood, but neither explains the clear start after the medicine"},{"dx":"Migraine-related fatigue","why_not":"Migraines have improved, so fatigue should not have worsened"}],"debrief_rubric":["Took a careful medication timeline","Considered medication-related mood change without dismissing other causes","Asked about suicide clearly","Advised liaison with the neurologist rather than stopping abruptly","Validated her concern"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Thomas, 58: the planter who sold the estate', 'lib-cr-019', 'guarded', '{"case_id":"cr-019","slug":"lib-cr-019","title":"Thomas, 58: the planter who sold the estate","difficulty":"guarded","traps":["somatic_mask"],"traps_authored":["somatic_mask"],"identity":{"name":"Thomas Kurian","age":58,"gender":"male","occupation":"former cardamom estate owner","city":"Idukki","family_structure":"married, two sons in the Gulf","language_register":"slow Malayalam-English, proud"},"presentation":"After selling the family estate due to losses, three months of poor sleep, poor appetite, weight loss, low energy and reduced libido; denies feeling sad at first.","chief_complaint_in_own_words":"My appetite is gone. I wake at three. My wife worries. It is the body only.","history":{"timeline":"Estate sold four months ago after three bad seasons. Biological symptoms over three months, withdrawal from the planters'' club.","prior_episodes":"none","substance_use":"brandy two pegs a night","medical":"BP","family":"none","treatment_history":"a tonic","help_seeking_delay":"three months","prior_contacts":["family doctor"]},"cognitive_model":{"core_belief":"I lost what my grandfather built.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has stopped visiting the club and church committee.","gate":"two_or_more_reflective_statements"},{"fact":"He feels he betrayed three generations by selling the land.","gate":"validation_given"},{"fact":"Brandy went from one peg to two since the sale.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Only the body is tired."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no wish to die; ''my sons need me to sign papers still.'' Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about sleep, appetite, weight, energy and libido systematically","Gently connected body symptoms to loss and mood","Asked about suicide clearly","Asked about alcohol","Respected his pride while naming the condition"],"few_shot":[],"fixture_lines":["Three generations on that hill. I signed it away in one afternoon at the registrar''s office.","I wake at three, hear the rain, think about the cardamom drying sheds.","My wife says I eat like a bird now.","The club? Too many questions there. Everyone knows.","It is not sadness. Men like me do not sit and feel sad."],"variation":{"mood_today":["proud","flat","tired"],"recent_event":["new owner cut trees","a son called from Qatar","the club annual meeting"],"most_defended_topic":["the sale of the land"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["slow Malayalam-English, proud"]},"moves":{},"module_id":"depression","voice_key":"slow Malayalam-English, proud@Idukki","protective_factors":["wife","sons"],"library":{"level":2,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the biological symptoms of depression","expected_mse":{"appearance":"Clean, older shirt","behaviour":"Slow","speech":"Slow, sparse","mood":"''Body is tired''","affect":"Depressed, restricted","thought_form":"Coherent","thought_content":"Guilt and loss, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Limited"},"diagnosis":"Moderate depressive episode","differentials":[{"dx":"Adjustment disorder","why_not":"Biological symptoms and duration fit a depressive episode"},{"dx":"Alcohol-related","why_not":"Drinking rose after the mood change; still address it"},{"dx":"Physical illness","why_not":"Weight loss needs a physical check"}],"debrief_rubric":["Asked about sleep, appetite, weight, energy and libido systematically","Gently connected body symptoms to loss and mood","Asked about suicide clearly","Asked about alcohol","Respected his pride while naming the condition"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Megha, 30: one bad patch, three years ago, and now this', 'lib-cr-020', 'cooperative', '{"case_id":"cr-020","slug":"lib-cr-020","title":"Megha, 30: one bad patch, three years ago, and now this","difficulty":"cooperative","traps":["adherence_fiction"],"traps_authored":["adherence_fiction"],"identity":{"name":"Megha Saxena","age":30,"gender":"female","occupation":"civil services aspirant and part-time tutor","city":"Delhi (Mukherjee Nagar)","family_structure":"lives in a PG, family in Bareilly","language_register":"articulate Hindi-English, analytical"},"presentation":"Third depressive episode: first at 21, second at 27 (treated, stopped medicine after three months of feeling better), now relapse for six weeks during exam preparation.","chief_complaint_in_own_words":"It''s back. I know the feeling now. Like the floor tilting. I stopped the medicine last time because I felt fine.","history":{"timeline":"Episode 1 at 21 after her grandfather died; episode 2 at 27, treated with an SSRI, stopped at three months of recovery; relapse six weeks ago during the prelims cycle.","prior_episodes":"two previous episodes","substance_use":"none","medical":"none","family":"maternal uncle with recurrent depression","treatment_history":"SSRI for six months total in episode 2, good response","help_seeking_delay":"six weeks","prior_contacts":["a psychiatrist in Bareilly"]},"cognitive_model":{"core_belief":"If I need medicine forever, I am weak.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She stopped the medicine because a coaching mentor said ''medicines dull your mind for the exam''.","gate":"two_or_more_reflective_statements"},{"fact":"She feels she is losing years compared with batchmates who have cleared.","gate":"validation_given"},{"fact":"She has not told her parents she is unwell again.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just exam pressure, everyone in Mukherjee Nagar is like this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: brief thoughts ''what is the point of all this'' but no suicidal ideas or plan. Low to moderate. Recurrent course raises future risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took a full longitudinal history of episodes and treatment","Explained relapse after early discontinuation and maintenance treatment","Addressed the myth about medicine and studying","Asked about suicide clearly","Built a relapse prevention plan with early warning signs"],"few_shot":[],"fixture_lines":["Third time. I can tell the start. My notes stop making sense and my chai goes cold.","Last time I felt fine after three months, so I stopped. That was a mistake, wasn''t it?","My mentor at coaching says medicines make you dull for the exam.","Batchmates cleared. One is in the foreign service. I am in the same PG, same chair.","I haven''t told Mummy. She''ll say come home. Home means giving up."],"variation":{"mood_today":["analytical","low","self-critical"],"recent_event":["prelims results","a batchmate''s success post","PG landlady asked about her health"],"most_defended_topic":["the mentor''s advice"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["articulate Hindi-English, analytical"]},"moves":{},"module_id":"depression","voice_key":"articulate Hindi-English, analytical@Delhi (Mukherjee Nagar)","protective_factors":["insight and analytical mind","family who would support"],"library":{"level":5,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Take a full longitudinal history of recurrent depression and plan maintenance","expected_mse":{"appearance":"Neat, tired","behaviour":"Engaged, slowed","speech":"Normal","mood":"''Low, tilting''","affect":"Depressed, reactive","thought_form":"Coherent","thought_content":"Self-criticism, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Recurrent depressive disorder, current episode moderate","differentials":[{"dx":"Bipolar disorder","why_not":"No hypomania reported; ask specifically because recurrence raises the question"},{"dx":"Adjustment disorder","why_not":"Third episode with full criteria and a recurrent pattern"},{"dx":"Hypothyroidism","why_not":"An underactive thyroid can bring back low mood, so check it if not done, though three clear episodes point to a recurrent mood disorder"}],"debrief_rubric":["Took a full longitudinal history of episodes and treatment","Explained relapse after early discontinuation and maintenance treatment","Addressed the myth about medicine and studying","Asked about suicide clearly","Built a relapse prevention plan with early warning signs"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Hemant, 45: the gas, the heaviness, the doctor-shopping', 'lib-cr-021', 'resistant', '{"case_id":"cr-021","slug":"lib-cr-021","title":"Hemant, 45: the gas, the heaviness, the doctor-shopping","difficulty":"resistant","traps":["somatic_mask","treatment_mismatch"],"traps_authored":["somatic_mask","treatment_mismatch"],"identity":{"name":"Hemant Patel","age":45,"gender":"male","occupation":"textile trader","city":"Surat","family_structure":"married, two teenage children, joint family","language_register":"brisk Gujarati-Hindi, impatient"},"presentation":"Seen six doctors in a year for ''gas'', chest heaviness and fatigue; all tests normal. Underneath: low mood, irritability, poor sleep and business worries since GST changes and a failed partnership.","chief_complaint_in_own_words":"Saheb, my stomach is full of gas, chest is heavy. Seven doctors, all tests normal. Write me a better test.","history":{"timeline":"A year since a partnership dissolved with losses. Symptoms started then; endoscopy, ECG, treadmill test all normal.","prior_episodes":"none","substance_use":"gutkha earlier, stopped","medical":"all investigations normal","family":"none","treatment_history":"antacids, two courses of vitamins","help_seeking_delay":"a year","prior_contacts":["six doctors","a gastro specialist"]},"cognitive_model":{"core_belief":"If I admit worry, people will think I''m weak in business.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has stopped enjoying the evening walks with his children and snaps at them.","gate":"two_or_more_reflective_statements"},{"fact":"The partner who left was his childhood friend and he feels betrayed.","gate":"validation_given"},{"fact":"He lies awake doing accounts at night.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Just give me a strong medicine for the gas."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no thoughts of suicide; ''I have children to settle.'' Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Acknowledged the reports and the real discomfort","Asked about life changes around onset","Asked about mood, sleep and enjoyment","Asked about suicide clearly","Explained the body-mind link without saying ''it''s all in your head''"],"few_shot":[],"fixture_lines":["Endoscopy, ECG, TMT, sonography. All normal. Then why is the gas still there?","Business is business. Ups and downs. That is not the problem.","At night I lie and the numbers go round and round.","My son asked me to come for cricket. I shouted at him. For nothing.","Mehul and I grew up in the same pol. Then he took the clients and left."],"variation":{"mood_today":["impatient","irritable","low beneath"],"recent_event":["a cheque bounced","son''s cricket match","a new doctor''s appointment"],"most_defended_topic":["the partner''s betrayal"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["brisk Gujarati-Hindi, impatient"]},"moves":{},"module_id":"depression","voice_key":"brisk Gujarati-Hindi, impatient@Surat","protective_factors":["family","work ethic"],"library":{"level":3,"topic":"depression","module":"depression","exams":["mcp-entrance","ma-semester"],"objective":"Shift a patient from repeated tests to talking about mood","expected_mse":{"appearance":"Well dressed, file of reports","behaviour":"Restless, checks phone","speech":"Fast, demanding","mood":"''Tension only''","affect":"Irritable, depressed beneath","thought_form":"Coherent","thought_content":"Health worry, business loss, no suicidal ideas","perception":"Nil","cognition":"Intact","insight_judgement":"Poor: body focus"},"diagnosis":"Depressive episode with prominent somatic symptoms","differentials":[{"dx":"Illness anxiety disorder","why_not":"His focus is relief of symptoms, not fear of a specific serious disease; mood symptoms are prominent"},{"dx":"Somatic symptom disorder","why_not":"Possible overlap; but sleep, anhedonia and irritability suggest depression drives it"},{"dx":"Gastrointestinal disease","why_not":"Adequately investigated; avoid further tests without new signs"}],"debrief_rubric":["Acknowledged the reports and the real discomfort","Asked about life changes around onset","Asked about mood, sleep and enjoyment","Asked about suicide clearly","Explained the body-mind link without saying ''it''s all in your head''"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sister Mary, 52: the nun who cannot pray', 'lib-cr-022', 'guarded', '{"case_id":"cr-022","slug":"lib-cr-022","title":"Sister Mary, 52: the nun who cannot pray","difficulty":"guarded","traps":["cultural_idiom","under_diagnosis"],"traps_authored":["cultural_idiom","under_diagnosis"],"identity":{"name":"Sister Mary Fernandes","age":52,"gender":"female","occupation":"Catholic nun, nursing superintendent at a mission hospital","city":"Mangaluru","family_structure":"lives in the convent community","language_register":"gentle Konkani-English, measured, self-effacing"},"presentation":"Her superior sent her. Four months of joyless mood, early waking, fatigue, loss of appetite, inability to concentrate on prayer and a sense of abandonment by God. She calls it ''the dark night''.","chief_complaint_in_own_words":"Mother Superior thought I should see someone. I think it is a spiritual dryness. The saints went through it. But I am not sleeping and I cannot eat.","history":{"timeline":"Began after a patient she cared for died in difficult circumstances. Sleep and appetite fell, weight down 5 kg, concentration poor on the ward.","prior_episodes":"none","substance_use":"none","medical":"hypothyroid on treatment, last TSH normal","family":"brother with alcohol problems","treatment_history":"spiritual direction","help_seeking_delay":"four months","prior_contacts":["her spiritual director","Mother Superior"]},"cognitive_model":{"core_belief":"I have failed God and my patients.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She feels nothing during Mass now and is terrified that her vocation is gone.","gate":"two_or_more_reflective_statements"},{"fact":"A young patient died after she missed a sign on a night shift, she believes.","gate":"validation_given"},{"fact":"She made two medication errors on the ward this month, caught in time.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["This is between me and God."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; ''life is a gift I cannot refuse.'' Low risk, but the ward errors are a patient safety concern to address.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Respected her spiritual framework while assessing clinical features","Asked about biological symptoms and functioning","Asked about suicide clearly","Addressed patient safety concerns from the errors sensitively","Offered treatment that can sit alongside spiritual direction"],"few_shot":[],"fixture_lines":["The saints wrote about the dark night. I used to read those pages with a kind of admiration.","Now I sit in chapel and nothing comes back. Not even silence. Just nothing.","Since the boy died on my shift, I wake at three and see his face.","I have stopped tasting food. The sisters notice my plate.","On the ward, twice this month, I nearly gave the wrong dose. Twice. I have nursed for thirty years."],"variation":{"mood_today":["gentle","heavy","guilty"],"recent_event":["a new admission resembling the boy","a feast day","Mother Superior''s question"],"most_defended_topic":["the medication errors"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["gentle Konkani-English, measured, self-effacing"]},"moves":{},"module_id":"depression","voice_key":"gentle Konkani-English, measured, self-effacing@Mangaluru","protective_factors":["community of sisters","deep sense of purpose"],"library":{"level":4,"topic":"depression","module":"depression","exams":["md-psychiatry","mcp-entrance"],"objective":"Tell spiritual dryness apart from a depressive episode respectfully","expected_mse":{"appearance":"Habit, tidy, thin","behaviour":"Calm, slowed","speech":"Soft","mood":"''Empty''","affect":"Depressed, restricted","thought_form":"Coherent","thought_content":"Guilt about the patient''s death, loss of meaning, no suicidal ideas","perception":"Nil","cognition":"Attention reduced","insight_judgement":"Partial insight, open to help"},"diagnosis":"Moderate depressive episode","differentials":[{"dx":"Spiritual dryness (non-clinical)","why_not":"Biological symptoms, weight loss and impaired work point to a treatable illness, which can sit alongside her spiritual experience"},{"dx":"Hypothyroid relapse","why_not":"She is on thyroid treatment, and a relapse of low thyroid can cause tiredness and low mood, so recheck her levels"},{"dx":"Post-traumatic stress","why_not":"Intrusive images of the patient are present; screen for avoidance and hyperarousal"}],"debrief_rubric":["Respected her spiritual framework while assessing clinical features","Asked about biological symptoms and functioning","Asked about suicide clearly","Addressed patient safety concerns from the errors sensitively","Offered treatment that can sit alongside spiritual direction"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Vivek, 29: the third ECG this month', 'lib-cr-023', 'cooperative', '{"case_id":"cr-023","slug":"lib-cr-023","title":"Vivek, 29: the third ECG this month","difficulty":"cooperative","traps":["somatic_mask"],"traps_authored":["somatic_mask"],"identity":{"name":"Vivek Nair","age":29,"gender":"male","occupation":"data analyst","city":"Pune (Hinjewadi)","family_structure":"lives with a flatmate; parents in Thrissur","language_register":"quick English, worried, apologetic"},"presentation":"Recurrent sudden surges of palpitations, breathlessness, tingling and fear of dying, peaking in minutes, for three months. Three normal ECGs in emergency departments.","chief_complaint_in_own_words":"My heart suddenly goes like a drum and I''m sure this is it, I''m dying. Then twenty minutes later I''m fine and the doctor says go home.","history":{"timeline":"First attack in a traffic jam three months ago; now two or three a week, some at night; worries constantly about the next one.","substance_use":"four coffees a day","medical":"normal ECGs, normal thyroid","treatment_history":"none","help_seeking_delay":"three months","prior_contacts":["three emergency departments"]},"cognitive_model":{"core_belief":"My heart is weak and nobody has found it yet.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He now avoids the highway route and takes a longer road to work.","gate":"two_or_more_reflective_statements"},{"fact":"His uncle died of a heart attack at 45 and he thinks of him in every attack.","gate":"validation_given"},{"fact":"He checks his pulse dozens of times a day.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe the machines missed something."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no thoughts of suicide or self-harm. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Described the attack timeline: sudden onset, peak in minutes","Asked about anticipatory worry and avoidance","Asked about caffeine and substances","Explained the body''s alarm system in plain words"],"few_shot":[],"fixture_lines":["Out of nowhere. I''m sitting there and boom, the heart, the hands go numb, I can''t get a breath.","It peaks in like ten minutes. Then I''m wiped out, like I ran a marathon.","Three ECGs. All normal. The last doctor looked at me like I was wasting his bed.","Now I take the long road. The highway feels like a trap."],"variation":{"mood_today":["worried","polite","keyed up"],"recent_event":["an attack at the gym","a cardiologist appointment","a colleague''s heart scare on the news"],"most_defended_topic":["his uncle''s death"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["quick English, worried, apologetic"]},"moves":{},"module_id":"anxiety","voice_key":"quick English, worried, apologetic@Pune (Hinjewadi)","protective_factors":["help-seeking","supportive flatmate"],"library":{"level":1,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise a panic attack and its fear of dying","expected_mse":{"appearance":"Casual, smartwatch on","behaviour":"Restless, checks pulse","speech":"Fast but coherent","mood":"''Scared it''ll happen again''","affect":"Anxious, reactive","thought_form":"Coherent","thought_content":"Fear of heart disease, anticipatory worry","perception":"No abnormal perceptions; tingling during attacks","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Panic disorder","differentials":[{"dx":"Cardiac arrhythmia","why_not":"Three normal ECGs during or after attacks and a normal examination make it unlikely; a monitor can settle doubt once"},{"dx":"Hyperthyroidism","why_not":"An overactive thyroid can cause a racing heart and tremor, but her thyroid tests are normal"},{"dx":"Caffeine-related anxiety","why_not":"Four coffees may add to it; reduce and review"}],"debrief_rubric":["Described the attack timeline: sudden onset, peak in minutes","Asked about anticipatory worry and avoidance","Asked about caffeine and substances","Explained the body''s alarm system in plain words"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Rehana, 38: the gate she cannot pass', 'lib-cr-024', 'guarded', '{"case_id":"cr-024","slug":"lib-cr-024","title":"Rehana, 38: the gate she cannot pass","difficulty":"guarded","traps":["iatrogenic","under_diagnosis"],"traps_authored":["iatrogenic","under_diagnosis"],"identity":{"name":"Rehana Begum","age":38,"gender":"female","occupation":"homemaker","city":"Bhopal","family_structure":"husband runs a mobile repair shop; three children","language_register":"soft Bhopali Urdu, embarrassed"},"presentation":"Two years of panic attacks with growing avoidance; now cannot leave the house without her husband, avoids markets and buses. Seen at home after the school complained the children are always late.","chief_complaint_in_own_words":"Bahar jaane se dil ghabrata hai. As soon as I reach the gate, my legs go weak. My husband has to take the children to school.","history":{"timeline":"First attack in a crowded bazaar during Eid shopping two years ago. Avoidance spread to buses, the market, then the street.","prior_episodes":"anxious as a child","medical":"normal check-ups","treatment_history":"a tablet from a chemist ''for nerves''","help_seeking_delay":"two years","prior_contacts":["chemist","a maulvi who gave a taweez"]},"cognitive_model":{"core_belief":"If I go out alone, something terrible will happen and nobody will help.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She has missed her daughter''s school prize day and her niece''s wedding.","gate":"two_or_more_reflective_statements"},{"fact":"Her mother-in-law says she is making excuses to avoid work.","gate":"validation_given"},{"fact":"She takes a ''nerve tablet'' from the chemist most days and does not know its name.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is only weakness of the legs."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; feels ashamed and trapped. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Mapped the spread of avoidance over time","Asked about the unnamed chemist tablet","Asked about mood and suicide clearly","Explained graded exposure in simple words and involved the husband with consent"],"few_shot":[],"fixture_lines":["At the gate my legs go like water. I turn back. Every time.","The bazaar during Eid. So many people. My chest closed. I thought I would fall and be trampled.","My husband leaves his shop to take the children. I see how tired he is.","My saas says I am making drama. I wish it was drama."],"variation":{"mood_today":["embarrassed","anxious","quiet"],"recent_event":["the school sent a note","a family wedding invitation","husband scolded her"],"most_defended_topic":["the chemist tablet"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["soft Bhopali Urdu, embarrassed"]},"moves":{},"module_id":"anxiety","voice_key":"soft Bhopali Urdu, embarrassed@Bhopal","protective_factors":["supportive husband","her children"],"library":{"level":3,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester"],"objective":"Assess agoraphobic avoidance and its effect on family life","expected_mse":{"appearance":"Neat, covered head","behaviour":"Sits close to husband initially","speech":"Soft","mood":"''Ghabrahat''","affect":"Anxious, tearful","thought_form":"Coherent","thought_content":"Fear of collapsing outside and not escaping","perception":"Nil","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Agoraphobia with panic attacks","differentials":[{"dx":"Social anxiety disorder","why_not":"Fear is of being trapped or unable to escape, not of being judged by others"},{"dx":"Depressive episode","why_not":"Mood is anxious rather than depressed; screen"},{"dx":"Sedative dependence","why_not":"Unknown chemist tablet may be a benzodiazepine; identify it"}],"debrief_rubric":["Mapped the spread of avoidance over time","Asked about the unnamed chemist tablet","Asked about mood and suicide clearly","Explained graded exposure in simple words and involved the husband with consent"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Rao, 64: the worrier who retired', 'lib-cr-025', 'cooperative', '{"case_id":"cr-025","slug":"lib-cr-025","title":"Mr Rao, 64: the worrier who retired","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Venkatesh Rao","age":64,"gender":"male","occupation":"retired bank manager","city":"Hyderabad","family_structure":"married, daughter in the US","language_register":"careful English, lists, qualifiers"},"presentation":"Excessive, hard-to-control worry about many things (health, money, his daughter, the house) most days for over a year, with muscle tension, poor sleep, irritability and fatigue.","chief_complaint_in_own_words":"My wife says I worry like it''s my job. Since retirement I have no job, so maybe worrying is my new job.","history":{"timeline":"Always a worrier, worse after retiring 18 months ago. Worry jumps from pension to the daughter''s commute to the water tank.","substance_use":"none","medical":"hypertension, controlled","family":"mother ''always tense''","treatment_history":"none","help_seeking_delay":"over a year","prior_contacts":["family doctor"]},"cognitive_model":{"core_belief":"If I stop worrying, something bad will happen.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He calls his daughter every evening to check she reached home.","gate":"two_or_more_reflective_statements"},{"fact":"He feels useless since retirement.","gate":"validation_given"},{"fact":"He believes worry has protected the family all these years.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every retired man worries."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the range and controllability of worries","Asked about physical symptoms of tension","Identified beliefs about worry being protective","Asked about mood and suicide"],"few_shot":[],"fixture_lines":["Pension, then the daughter driving in snow, then the water tank leaking, then back to pension.","My shoulders are like iron rods.","I call Divya every evening. Seven thirty. If she doesn''t pick up I imagine the worst.","Worry is like a guard dog. If I let it sleep, who will watch the house?"],"variation":{"mood_today":["tense","polite","talkative"],"recent_event":["a bank fraud news story","daughter missed a call","BP reading slightly up"],"most_defended_topic":["feeling useless"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["careful English, lists, qualifiers"]},"moves":{},"module_id":"anxiety","voice_key":"careful English, lists, qualifiers@Hyderabad","protective_factors":["stable marriage","routine and resources"],"library":{"level":2,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the features of generalised anxiety","expected_mse":{"appearance":"Neat, glasses, folder","behaviour":"Restless hands","speech":"Detailed, circumstantial at times","mood":"''Tense''","affect":"Anxious","thought_form":"Coherent, circumstantial","thought_content":"Multiple worries, belief worry protects","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Generalised anxiety disorder","differentials":[{"dx":"Depressive episode","why_not":"Mood is not mainly low and interest is kept; screen"},{"dx":"Hyperthyroidism","why_not":"An overactive thyroid can mimic worry with tension and poor sleep, so check it once, though his lifelong worrying style points away from it"},{"dx":"Obsessive-compulsive disorder","why_not":"Worries are about real-life matters, not intrusive ego-dystonic thoughts with rituals"}],"debrief_rubric":["Explored the range and controllability of worries","Asked about physical symptoms of tension","Identified beliefs about worry being protective","Asked about mood and suicide"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Neelam, 34: the shaking hands and the weight loss', 'lib-cr-026', 'cooperative', '{"case_id":"cr-026","slug":"lib-cr-026","title":"Neelam, 34: the shaking hands and the weight loss","difficulty":"cooperative","traps":["medical_mimic"],"traps_authored":["medical_mimic"],"identity":{"name":"Neelam Bisht","age":34,"gender":"female","occupation":"government school teacher","city":"Dehradun","family_structure":"married, one daughter","language_register":"Garhwali-accented Hindi-English, talkative"},"presentation":"Three months of nervousness, palpitations, tremor, sweating, poor sleep, weight loss despite eating more, heat intolerance and loose stools.","chief_complaint_in_own_words":"I am always nervous, my hands shake when I write on the board, and I am sweating in December. Everyone says it''s stress.","history":{"timeline":"Gradual over three months; lost 5 kg; eats more; feels hot; heart races at rest.","substance_use":"none","medical":"no tests yet; neck feels ''full''","family":"mother had a thyroid problem","treatment_history":"a homeopathic remedy for stress","help_seeking_delay":"three months","prior_contacts":["homeopath"]},"cognitive_model":{"core_belief":"I am not coping as a teacher and a mother.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She eats more than ever but is losing weight.","gate":"two_or_more_reflective_statements"},{"fact":"She feels hot when everyone else wears sweaters.","gate":"validation_given"},{"fact":"Her mother had a ''thyroid lump'' operated.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is school stress, inspection is coming."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Noticed physical clues: weight loss with more appetite, heat intolerance, tremor","Asked about family thyroid history","Recommended thyroid tests before a psychological label","Explained the plan without dismissing her stress","Kept a differential open between anxiety and a medical cause"],"few_shot":[],"fixture_lines":["My hands shake when I write on the blackboard. The children giggle.","December in Dehradun and I am opening the windows.","I eat double, and still my kurtas are loose.","My heart is running even when I''m lying down."],"variation":{"mood_today":["restless","chatty","tired"],"recent_event":["the inspection","a sleepless night","a sister''s comment about her weight"],"most_defended_topic":["fear she is a poor teacher"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Garhwali-accented Hindi-English, talkative"]},"moves":{},"module_id":"anxiety","voice_key":"Garhwali-accented Hindi-English, talkative@Dehradun","protective_factors":["insight","family support"],"library":{"level":4,"topic":"anxiety","module":"anxiety","exams":["md-psychiatry","mcp-entrance"],"objective":"Spot a physical cause behind an anxious presentation","expected_mse":{"appearance":"Thin, sweating, fine tremor of hands","behaviour":"Restless, fidgety","speech":"Rapid, talkative","mood":"''Nervous''","affect":"Anxious","thought_form":"Coherent, a little rushed","thought_content":"Worries about coping","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight; seeks explanation"},"diagnosis":"Anxiety symptoms due to suspected hyperthyroidism (needs thyroid tests)","differentials":[{"dx":"Generalised anxiety disorder","why_not":"Weight loss with increased appetite, heat intolerance and resting tachycardia point to a medical cause first"},{"dx":"Panic disorder","why_not":"Symptoms are continuous, not discrete attacks"},{"dx":"Stimulant use","why_not":"Stimulants such as caffeine or diet pills can cause tremor and weight loss, but she uses none, which leaves the thyroid as the lead"}],"debrief_rubric":["Noticed physical clues: weight loss with more appetite, heat intolerance, tremor","Asked about family thyroid history","Recommended thyroid tests before a psychological label","Explained the plan without dismissing her stress","Kept a differential open between anxiety and a medical cause"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Aditya, 19: the presentation he skipped', 'lib-cr-027', 'guarded', '{"case_id":"cr-027","slug":"lib-cr-027","title":"Aditya, 19: the presentation he skipped","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Aditya Kapoor","age":19,"gender":"male","occupation":"first-year B.Com student","city":"Delhi","family_structure":"lives with parents and sister","language_register":"soft Delhi English, blushes, short answers"},"presentation":"Intense fear of being judged in class, canteen and group work since school; blushes, trembles, avoids presentations, now skipping college. Comfortable with close friends.","chief_complaint_in_own_words":"I just don''t like everyone looking at me. My face goes red and my voice shakes and then everyone knows.","history":{"timeline":"Since Class 8 after being laughed at during a speech; now avoids presentations, eats lunch alone in the library.","substance_use":"none","medical":"none","family":"father shy","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["school counsellor once"]},"cognitive_model":{"core_belief":"People will see I''m weird and laugh.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He rehearses sentences before ordering in the canteen and still avoids it.","gate":"two_or_more_reflective_statements"},{"fact":"He was laughed at during a Class 8 speech and still remembers every face.","gate":"validation_given"},{"fact":"He has thought of dropping out to avoid the first-year viva.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m just an introvert."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about specific feared situations and avoidance","Identified the core fear of judgement","Asked about safety behaviours","Asked about mood and suicide"],"few_shot":[],"fixture_lines":["When the professor says ''Aditya, come up'', my whole body goes hot.","I eat lunch in the library. Nobody looks at you in the library.","With my two school friends I''m totally normal. Ask them.","Class 8, annual day speech. I forgot one line. The laughing. I can still hear it."],"variation":{"mood_today":["shy","tense","warm once settled"],"recent_event":["a group presentation assigned","a friend''s birthday party","a viva notice"],"most_defended_topic":["thinking of dropping out"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["soft Delhi English, blushes, short answers"]},"moves":{},"module_id":"anxiety","voice_key":"soft Delhi English, blushes, short answers@Delhi","protective_factors":["two close friends","supportive sister"],"library":{"level":1,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise fear of scrutiny as the core of social anxiety","expected_mse":{"appearance":"Neat, avoids eye contact initially","behaviour":"Fidgety, blushes","speech":"Soft, hesitant, improves","mood":"''Nervous''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of negative evaluation","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Social anxiety disorder","differentials":[{"dx":"Avoidant personality disorder","why_not":"Fear is focused on performance and scrutiny; he has close friendships and a sense of himself outside these situations"},{"dx":"Introversion","why_not":"Introversion does not cause this distress and avoidance"},{"dx":"Autism spectrum condition","why_not":"Social reciprocity with friends is good"}],"debrief_rubric":["Asked about specific feared situations and avoidance","Identified the core fear of judgement","Asked about safety behaviours","Asked about mood and suicide"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Shalini, 32: has never felt she belonged anywhere', 'lib-cr-028', 'guarded', '{"case_id":"cr-028","slug":"lib-cr-028","title":"Shalini, 32: has never felt she belonged anywhere","difficulty":"guarded","traps":["misattributed_diagnosis"],"traps_authored":["misattributed_diagnosis"],"identity":{"name":"Shalini Ghosh","age":32,"gender":"female","occupation":"medical transcriptionist working from home","city":"Kolkata","family_structure":"lives with her mother","language_register":"soft, careful English with Bengali, self-deprecating"},"presentation":"Lifelong, pervasive feelings of inadequacy and fear of rejection across all relationships; avoids jobs needing contact, has never dated, no close friends despite wanting them.","chief_complaint_in_own_words":"I''ve always been like this. I want friends, I just know they''ll find me boring and leave, so I don''t start.","history":{"timeline":"Since early childhood; took a work-from-home job to avoid people; turned down a promotion with team-lead duties.","substance_use":"none","medical":"none","family":"critical father, now deceased","treatment_history":"none","help_seeking_delay":"lifelong","prior_contacts":["a cousin who insisted"]},"cognitive_model":{"core_belief":"I am inferior and unlikeable.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She refused a promotion because she would have to lead meetings.","gate":"two_or_more_reflective_statements"},{"fact":"Her father called her ''useless'' through childhood.","gate":"validation_given"},{"fact":"She has a pen-friend online for six years whom she has never met for fear of disappointing her.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Some people are just loners."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; lonely. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Established a lifelong, pervasive pattern","Explored her wish for closeness versus fear","Asked about mood and suicide","Gave a respectful, non-pathologising explanation"],"few_shot":[],"fixture_lines":["I''d like friends. I just know how it ends. They get bored, they drift. So I don''t begin.","I took this job so I could talk to a headset, not a person.","They offered me team lead. Meetings every day. I said no in one second.","Baba used to say I was useless at everything. Maybe he was right."],"variation":{"mood_today":["shy","self-critical","warm"],"recent_event":["the cousin''s wedding","a work video call","pen-friend asked to meet"],"most_defended_topic":["the online pen-friend"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["soft, careful English with Bengali, self-deprecating"]},"moves":{},"module_id":"personality","voice_key":"soft, careful English with Bengali, self-deprecating@Kolkata","protective_factors":["online friendship","steady job"],"library":{"level":4,"topic":"anxiety","module":"personality","exams":["md-psychiatry","mcp-entrance","ugc-net"],"objective":"Tell social anxiety apart from an avoidant personality pattern","expected_mse":{"appearance":"Simple, neat","behaviour":"Avoids eye contact","speech":"Soft","mood":"''Lonely''","affect":"Anxious, restricted","thought_form":"Coherent","thought_content":"Pervasive inadequacy, fear of rejection","perception":"Nil","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Avoidant personality disorder","differentials":[{"dx":"Social anxiety disorder","why_not":"Can coexist; here the inadequacy is pervasive, lifelong and shapes identity across all relationships"},{"dx":"Schizoid personality","why_not":"She wants relationships; schizoid people are indifferent"},{"dx":"Depressive disorder","why_not":"Mood is not persistently low; screen"}],"debrief_rubric":["Established a lifelong, pervasive pattern","Explored her wish for closeness versus fear","Asked about mood and suicide","Gave a respectful, non-pathologising explanation"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Pooja, 27: pregnant and terrified of the needle', 'lib-cr-029', 'cooperative', '{"case_id":"cr-029","slug":"lib-cr-029","title":"Pooja, 27: pregnant and terrified of the needle","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Pooja Verma","age":27,"gender":"female","occupation":"receptionist at a hotel","city":"Jaipur","family_structure":"married, first pregnancy, 10 weeks","language_register":"chatty Hindi-English, laughs when nervous"},"presentation":"Lifelong fear of needles and blood with fainting; now pregnant and refusing antenatal blood tests and the tetanus injection.","chief_complaint_in_own_words":"Doctor, I will do anything, just no injection. Last time I fainted and hit my head.","history":{"timeline":"Since childhood; faints at the sight of blood; avoided vaccines as an adult.","medical":"10 weeks pregnant, booking bloods pending","family":"brother also faints with blood","treatment_history":"none","help_seeking_delay":"lifelong","prior_contacts":["obstetrician who referred her"]},"cognitive_model":{"core_belief":"If I see the needle I will faint and something bad will happen to the baby.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She fainted and hit her head during a blood test at 18.","gate":"two_or_more_reflective_statements"},{"fact":"She feels ashamed that a small thing scares her so much.","gate":"validation_given"},{"fact":"She has skipped her booking blood test twice.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Can they do the test without blood?"],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk; the risk is to antenatal care.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the fear and the fainting history","Explained the blood-pressure drop specific to this phobia","Taught applied tension in plain steps","Planned graded exposure around her antenatal tests"],"few_shot":[],"fixture_lines":["Just seeing the tray with the cotton and the tubes, my head goes light.","At eighteen I fainted and hit my head on the steel chair. Six stitches.","Everybody laughs. ''So small a needle!'' Small for them.","I want the baby to be fine. That''s why I''m here."],"variation":{"mood_today":["nervous","cheerful","embarrassed"],"recent_event":["an antenatal appointment","a cousin''s delivery story","a vaccine reminder"],"most_defended_topic":["skipped tests"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["chatty Hindi-English, laughs when nervous"]},"moves":{},"module_id":"anxiety","voice_key":"chatty Hindi-English, laughs when nervous@Jaipur","protective_factors":["motivation for the baby","supportive husband"],"library":{"level":2,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the features and treatment of a blood-injection phobia","expected_mse":{"appearance":"Well groomed","behaviour":"Anxious laugh","speech":"Talkative","mood":"''Scared''","affect":"Anxious, reactive","thought_form":"Coherent","thought_content":"Fear of fainting with needles","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Specific phobia, blood-injection-injury type","differentials":[{"dx":"Panic disorder","why_not":"Fear is tied to one cue, not unexpected attacks"},{"dx":"Vasovagal syncope alone","why_not":"The fainting is part of this phobia type; the fear and avoidance are the problem to treat"},{"dx":"Health anxiety","why_not":"She does not fear having a disease; her fear is of the needle and fainting"}],"debrief_rubric":["Explored the fear and the fainting history","Explained the blood-pressure drop specific to this phobia","Taught applied tension in plain steps","Planned graded exposure around her antenatal tests"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Salim, 42: the Gulf job and the plane', 'lib-cr-030', 'cooperative', '{"case_id":"cr-030","slug":"lib-cr-030","title":"Salim, 42: the Gulf job and the plane","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Salim Kutty","age":42,"gender":"male","occupation":"electrician offered a job in Doha","city":"Malappuram","family_structure":"married, three children","language_register":"Malayalam-English, practical, a little ashamed"},"presentation":"Intense fear of flying for twenty years after a turbulent flight; refused two Gulf job offers; a third offer is pending with a flight in six weeks.","chief_complaint_in_own_words":"The money is good, the job is good. Only problem: the aeroplane. I cannot sit in that tube.","history":{"timeline":"One frightening turbulent flight at 22; has avoided flying since.","substance_use":"none","medical":"none","treatment_history":"none","help_seeking_delay":"twenty years","prior_contacts":["a cousin who flies often"]},"cognitive_model":{"core_belief":"If it shakes, it will fall.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He turned down two jobs and told his wife the visa failed.","gate":"two_or_more_reflective_statements"},{"fact":"He feels ashamed in front of his brothers who all work abroad.","gate":"validation_given"},{"fact":"Even airport videos make his palms sweat.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe I can go by ship."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored onset and the specific feared outcome","Asked about avoidance and its cost","Explained exposure therapy and a realistic timeline","Discussed short-term options with a prescriber for the flight honestly"],"few_shot":[],"fixture_lines":["Twenty years back, Mumbai to Muscat. The plane dropped. People screaming. I held the seat like this.","Since then, no flight. Train, bus, anything. Not the plane.","My brothers are all in the Gulf. I''m the one at home.","Six weeks. The ticket is already booked by the company."],"variation":{"mood_today":["practical","ashamed","hopeful"],"recent_event":["the ticket confirmation email","a plane crash in the news","his son asked about Qatar"],"most_defended_topic":["lying to his wife about the visa"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Malayalam-English, practical, a little ashamed"]},"moves":{},"module_id":"anxiety","voice_key":"Malayalam-English, practical, a little ashamed@Malappuram","protective_factors":["strong motivation","supportive brothers"],"library":{"level":1,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise a specific phobia of flying","expected_mse":{"appearance":"Neat","behaviour":"Calm until flights discussed","speech":"Normal","mood":"''Worried about the flight''","affect":"Anxious when discussing flying","thought_form":"Coherent","thought_content":"Fear of the plane falling","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Specific phobia, situational type (flying)","differentials":[{"dx":"Panic disorder with agoraphobia","why_not":"No unexpected attacks; fear is limited to flying"},{"dx":"Post-traumatic stress","why_not":"No intrusions or hyperarousal outside flying"},{"dx":"Claustrophobia","why_not":"Fear is of the plane falling, not enclosed space generally"}],"debrief_rubric":["Explored onset and the specific feared outcome","Asked about avoidance and its cost","Explained exposure therapy and a realistic timeline","Discussed short-term options with a prescriber for the flight honestly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Dutta, 45: cannot let her husband travel', 'lib-cr-031', 'guarded', '{"case_id":"cr-031","slug":"lib-cr-031","title":"Mrs Dutta, 45: cannot let her husband travel","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Rupa Dutta","age":45,"gender":"female","occupation":"homemaker and part-time tuition teacher","city":"Guwahati","family_structure":"married, son in Bengaluru","language_register":"Assamese-English, anxious, apologetic"},"presentation":"Excessive fear that harm will come to her husband or son whenever they are away; calls them repeatedly, cannot sleep when the husband travels, has nightmares of their death. Worse since son moved for college.","chief_complaint_in_own_words":"When my husband goes for office tour I cannot sleep. I call ten times. If he doesn''t pick up, I think he is lying on a road somewhere.","history":{"timeline":"Always ''attached'', worse in the last year since her son left home.","prior_episodes":"school refusal as a child","medical":"none","family":"mother lost her own mother young","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["husband"]},"cognitive_model":{"core_belief":"If I am not watching, I will lose them.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She was afraid to go to school as a child in case her mother died while she was away.","gate":"two_or_more_reflective_statements"},{"fact":"Her husband now refuses work trips to keep her calm.","gate":"validation_given"},{"fact":"She dreams of her son''s accident most nights he goes out.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every mother worries."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the focus of fear on separation","Took a childhood history","Asked about the impact on the family","Asked about mood and suicide"],"few_shot":[],"fixture_lines":["If my son doesn''t answer by eleven, I''m already imagining the hospital.","My husband stopped going on tours. His boss is not happy.","As a child I would not go to school. I thought Maa would die while I was away.","The dreams. Always an accident. Always I am too late."],"variation":{"mood_today":["anxious","apologetic","tearful"],"recent_event":["son''s late night out","husband''s work trip proposal","a road accident on the news"],"most_defended_topic":["husband giving up work trips"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Assamese-English, anxious, apologetic"]},"moves":{},"module_id":"anxiety","voice_key":"Assamese-English, anxious, apologetic@Guwahati","protective_factors":["loving family","tuition work"],"library":{"level":4,"topic":"anxiety","module":"anxiety","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise adult separation anxiety","expected_mse":{"appearance":"Neat","behaviour":"Restless, checks phone","speech":"Rapid when anxious","mood":"''Always afraid''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of harm to attachment figures","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Separation anxiety disorder (adult)","differentials":[{"dx":"Generalised anxiety disorder","why_not":"Her worry is centred on separation from attachment figures, not many topics"},{"dx":"Panic disorder","why_not":"She has no sudden attacks out of the blue; her fear rises only around separation"},{"dx":"Depressive episode","why_not":"Her mood is fearful rather than low, but long worry can lead to low mood, so ask about it"}],"debrief_rubric":["Explored the focus of fear on separation","Took a childhood history","Asked about the impact on the family","Asked about mood and suicide"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Jatin, 23: five energy drinks and a racing heart', 'lib-cr-032', 'cooperative', '{"case_id":"cr-032","slug":"lib-cr-032","title":"Jatin, 23: five energy drinks and a racing heart","difficulty":"cooperative","traps":["substance_induced"],"traps_authored":["substance_induced"],"identity":{"name":"Jatin Arora","age":23,"gender":"male","occupation":"night-shift customer-support executive","city":"Noida","family_structure":"lives in a PG with three colleagues","language_register":"fast Delhi Hinglish, jokey"},"presentation":"Two months of jitteriness, palpitations, poor sleep and two attack-like episodes; drinks four to five energy drinks a shift plus pre-workout powder.","chief_complaint_in_own_words":"Bhai, my heart is always on full speed. And twice I thought I''d faint at my desk.","history":{"timeline":"Started night shifts three months ago; energy drink intake rose; gym pre-workout started two months ago.","substance_use":"energy drinks, pre-workout powder, occasional vape","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["gym trainer"]},"cognitive_model":{"core_belief":"I need the drinks to survive the shift.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He sleeps three or four hours in the day.","gate":"two_or_more_reflective_statements"},{"fact":"He feels he must keep up with his gym friends.","gate":"validation_given"},{"fact":"The pre-workout powder is a ''strong one'' a trainer sells without a label.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everyone on night shift drinks these."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified caffeine and other stimulants","Asked about the unlabelled supplement","Linked sleep loss and shift work to symptoms","Agreed a plan to cut down and review","Kept a differential open between primary anxiety and a stimulant effect"],"few_shot":[],"fixture_lines":["Four, five cans a shift. Otherwise I''ll sleep on the headset.","The pre-workout is a strong one. Trainer gives it in a zip bag.","Twice my heart went so fast I held the desk.","Sleep? Three, four hours. Daylight and horns."],"variation":{"mood_today":["jittery","jokey","tired"],"recent_event":["a double shift","a gym competition","a missed sleep"],"most_defended_topic":["the unlabelled powder"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fast Delhi Hinglish, jokey"]},"moves":{},"module_id":"substance","voice_key":"fast Delhi Hinglish, jokey@Noida","protective_factors":["insight once shown the link"],"library":{"level":4,"topic":"anxiety","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Consider substance-induced anxiety before diagnosing a primary disorder","expected_mse":{"appearance":"Gym wear, restless leg","behaviour":"Fidgety","speech":"Rapid, jokey","mood":"''Wired''","affect":"Anxious, labile","thought_form":"Coherent","thought_content":"Health worry","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Caffeine- and stimulant-induced anxiety disorder","differentials":[{"dx":"Panic disorder","why_not":"Symptoms track stimulant intake; reassess after stopping"},{"dx":"Hyperthyroidism","why_not":"An overactive thyroid causes similar jitteriness; check it if symptoms persist after stopping the drinks"},{"dx":"Cardiac arrhythmia","why_not":"If palpitations persist after stopping, needs an ECG"}],"debrief_rubric":["Quantified caffeine and other stimulants","Asked about the unlabelled supplement","Linked sleep loss and shift work to symptoms","Agreed a plan to cut down and review","Kept a differential open between primary anxiety and a stimulant effect"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Agarwal, 51: attacks with a pounding headache', 'lib-cr-033', 'cooperative', '{"case_id":"cr-033","slug":"lib-cr-033","title":"Mr Agarwal, 51: attacks with a pounding headache","difficulty":"cooperative","traps":["medical_mimic","misattributed_diagnosis"],"traps_authored":["medical_mimic","misattributed_diagnosis"],"identity":{"name":"Ramesh Agarwal","age":51,"gender":"male","occupation":"chartered accountant","city":"Kanpur","family_structure":"married, two sons","language_register":"methodical Hindi-English"},"presentation":"Episodes of pounding headache, sweating, palpitations and pallor with very high blood pressure readings during attacks, lasting 20 to 40 minutes; BP difficult to control; diagnosed with ''panic'' elsewhere.","chief_complaint_in_own_words":"During the attack, my head pounds, I sweat buckets and my BP machine shows 220. Then it settles. They said panic attacks.","history":{"timeline":"Six months; attacks several times a week, some triggered by bending or straining; lost weight; BP poorly controlled on two medicines.","substance_use":"none","medical":"hypertension resistant to two drugs","family":"none known","treatment_history":"an SSRI for ''panic'', no change","help_seeking_delay":"six months","prior_contacts":["physician","a psychiatrist"]},"cognitive_model":{"core_belief":"Maybe I am weak-minded.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He records BP of over 200 during attacks and has a phone log.","gate":"two_or_more_reflective_statements"},{"fact":"He felt dismissed when told it was ''just panic''.","gate":"validation_given"},{"fact":"An attack once came when he bent to tie his shoes, with no fear beforehand.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe it is my stressful job."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Physical risk: hypertensive crises; needs urgent medical work-up.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Noticed that physical symptoms come before fear","Valued his BP log as evidence","Recognised red flags: resistant hypertension, attacks with straining, weight loss","Referred urgently for medical work-up","Kept a differential open and did not accept the earlier label without checking"],"few_shot":[],"fixture_lines":["I keep a log. Date, time, BP. Look, 224 over 130 on the 3rd.","There is no fear first. The body goes first. Head, sweat, heart.","Once I bent to tie my shoe and it started.","The tablet they gave for panic did nothing. Nothing at all."],"variation":{"mood_today":["methodical","frustrated","worried"],"recent_event":["a new attack yesterday","a BP reading in clinic","tax-season pressure"],"most_defended_topic":["feeling dismissed"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["methodical Hindi-English"]},"moves":{},"module_id":"anxiety","voice_key":"methodical Hindi-English@Kanpur","protective_factors":["careful record-keeping"],"library":{"level":5,"topic":"anxiety","module":"anxiety","exams":["md-psychiatry"],"objective":"Recognise the red flags of a rare medical cause of episodic anxiety","expected_mse":{"appearance":"Thin, pale","behaviour":"Calm between attacks","speech":"Organised","mood":"''Frustrated''","affect":"Mildly anxious","thought_form":"Coherent","thought_content":"Concern about being dismissed","perception":"Nil","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Episodic adrenergic attacks suspicious of pheochromocytoma (needs urgent medical investigation)","differentials":[{"dx":"Panic disorder","why_not":"Attacks begin with physical symptoms, not fear; very high BP during attacks, poor control and weight loss are red flags"},{"dx":"Hyperthyroidism","why_not":"Check, but episodic severe hypertension points elsewhere"},{"dx":"Stimulant use","why_not":"Stimulant or decongestant use can raise blood pressure in surges, but he takes none, so a hormone-secreting cause must be excluded"}],"debrief_rubric":["Noticed that physical symptoms come before fear","Valued his BP log as evidence","Recognised red flags: resistant hypertension, attacks with straining, weight loss","Referred urgently for medical work-up","Kept a differential open and did not accept the earlier label without checking"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Gurpreet, 36: the asthma pump and the jitters', 'lib-cr-034', 'cooperative', '{"case_id":"cr-034","slug":"lib-cr-034","title":"Gurpreet, 36: the asthma pump and the jitters","difficulty":"cooperative","traps":["iatrogenic","medical_mimic"],"traps_authored":["iatrogenic","medical_mimic"],"identity":{"name":"Gurpreet Kaur","age":36,"gender":"female","occupation":"boutique owner","city":"Ludhiana","family_structure":"married, two children","language_register":"lively Punjabi, quick, talks with hands"},"presentation":"Asthma with frequent reliever use (many puffs daily), jitteriness, tremor, palpitations and fear of being unable to breathe; avoids the preventer inhaler because of steroid fears.","chief_complaint_in_own_words":"My breath gets stuck, I take the blue pump, then my heart goes fast and I shake. Then I panic that I''m going to die. Then more pump.","history":{"timeline":"Asthma since childhood; worse in a year since she stopped the brown preventer for fear of steroids; now uses the blue inhaler 10 to 15 times a day.","substance_use":"none","medical":"asthma; stopped preventer inhaler","family":"mother asthmatic","treatment_history":"reliever inhaler only","help_seeking_delay":"a year","prior_contacts":["chemist","a relative who said steroids are dangerous"]},"cognitive_model":{"core_belief":"Steroids will ruin my body.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She uses the blue inhaler 10 to 15 times a day.","gate":"two_or_more_reflective_statements"},{"fact":"A relative told her steroids would make her fat and weak.","gate":"validation_given"},{"fact":"She avoids her boutique''s back room because it feels airless.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I am just a nervous type."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Physical risk: poorly controlled asthma.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about inhaler use and the stopped preventer","Addressed steroid myths accurately","Explained how reliever overuse causes shaking and fast heartbeat","Linked to the physician for asthma control","Gave psychoeducation about how the reliever inhaler causes shaking"],"few_shot":[],"fixture_lines":["The blue one is my best friend. Ten, fifteen times a day.","Then my hands shake while I''m pinning the blouse.","The brown one has steroid. My cousin''s mother-in-law got so fat from steroids.","When my breath catches I think, this is the one that won''t open."],"variation":{"mood_today":["lively","anxious","defensive about inhalers"],"recent_event":["dusty wedding-season stock","night cough","a child''s cold"],"most_defended_topic":["stopping the preventer"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["lively Punjabi, quick, talks with hands"]},"moves":{},"module_id":"anxiety","voice_key":"lively Punjabi, quick, talks with hands@Ludhiana","protective_factors":["business she loves","family"],"library":{"level":4,"topic":"anxiety","module":"anxiety","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise medication and breathlessness feeding an anxiety cycle","expected_mse":{"appearance":"Smart suit, inhaler in hand","behaviour":"Restless, fine tremor","speech":"Fast","mood":"''Scared of not breathing''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of suffocation, steroid fears","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Anxiety symptoms driven by poorly controlled asthma and reliever overuse (with health-related fear)","differentials":[{"dx":"Panic disorder","why_not":"Attacks follow breathlessness and reliever overuse; treat the asthma first"},{"dx":"Hyperthyroidism","why_not":"An overactive thyroid causes tremor and a fast heart; check it if symptoms persist once the asthma is controlled"},{"dx":"Generalised anxiety","why_not":"Her worry is about breathing only, not the many topics that mark generalised anxiety"}],"debrief_rubric":["Asked about inhaler use and the stopped preventer","Addressed steroid myths accurately","Explained how reliever overuse causes shaking and fast heartbeat","Linked to the physician for asthma control","Gave psychoeducation about how the reliever inhaler causes shaking"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Fernandes, 74: since the fall she stays in', 'lib-cr-035', 'guarded', '{"case_id":"cr-035","slug":"lib-cr-035","title":"Mrs Fernandes, 74: since the fall she stays in","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Lucy Fernandes","age":74,"gender":"female","occupation":"retired nurse","city":"Panaji","family_structure":"widowed; lives alone; daughter visits","language_register":"Goan English, brisk, proud"},"presentation":"Since a fall in the market six months ago, fear of going out alone, avoids church and the market, moves little at home; mild knee arthritis.","chief_complaint_in_own_words":"I''m not afraid, I''m being careful. At my age you don''t go gallivanting.","history":{"timeline":"Fall six months ago, bruised hip, no fracture; since then stays home, groceries delivered.","substance_use":"none","medical":"osteoarthritis, mild cataract","family":"none","treatment_history":"physio advised, not attended","help_seeking_delay":"six months","prior_contacts":["daughter","GP"]},"cognitive_model":{"core_belief":"If I fall again, I''ll end up in a home.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She has not gone to Sunday Mass in four months, which she attended for sixty years.","gate":"two_or_more_reflective_statements"},{"fact":"Her real fear is being sent to an old-age home.","gate":"validation_given"},{"fact":"Her cataract makes the market steps look blurry.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m just being sensible."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; lonely. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the fall and the fears behind avoidance","Asked about vision, mobility and physical contributors","Asked about mood, loneliness and suicide","Planned graded return with physio and cataract review"],"few_shot":[],"fixture_lines":["I nursed for forty years. I know what a hip fracture does at my age.","Mass on Sunday, sixty years. Now I watch it on the tablet my daughter set up.","The market steps look like a slope since my eyes went cloudy.","If I fall again, Clara will put me in a home. She won''t say it, but she''ll think it."],"variation":{"mood_today":["brisk","proud","lonely"],"recent_event":["a neighbour''s fall","daughter''s visit","the feast at church"],"most_defended_topic":["fear of an old-age home"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Goan English, brisk, proud"]},"moves":{},"module_id":"anxiety","voice_key":"Goan English, brisk, proud@Panaji","protective_factors":["nursing knowledge","daughter"],"library":{"level":3,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester"],"objective":"Assess fear of falling and avoidance in older adults","expected_mse":{"appearance":"Neat, uses a stick","behaviour":"Slow, careful","speech":"Clear","mood":"''Careful, not afraid''","affect":"Anxious when outdoors discussed","thought_form":"Coherent","thought_content":"Fear of falling and losing independence","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Fear of falling with agoraphobic-type avoidance (consider specific phobia or agoraphobia)","differentials":[{"dx":"Depressive episode","why_not":"Withdrawal is driven by fear, but screen for low mood and loneliness"},{"dx":"Realistic caution","why_not":"Avoidance exceeds the real risk and costs her church and social life"},{"dx":"Visual impairment alone","why_not":"Cataract adds real risk and should be treated, but avoidance spread beyond"}],"debrief_rubric":["Explored the fall and the fears behind avoidance","Asked about vision, mobility and physical contributors","Asked about mood, loneliness and suicide","Planned graded return with physio and cataract review"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Anand, 31: the Mumbai local at 8.42', 'lib-cr-036', 'cooperative', '{"case_id":"cr-036","slug":"lib-cr-036","title":"Anand, 31: the Mumbai local at 8.42","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Anand Shinde","age":31,"gender":"male","occupation":"accounts clerk","city":"Thane","family_structure":"married, one son","language_register":"Marathi-Hindi-English Mumbai mix"},"presentation":"Panic attacks on the crowded local train for four months; now takes a costly shared cab; worries constantly about the next attack.","chief_complaint_in_own_words":"In the 8.42 fast, Dadar side, packed. My chest locked. I got down at Kurla and sat on the platform for an hour.","history":{"timeline":"First attack four months ago; three more; now avoids trains, takes a cab costing a third of his salary.","substance_use":"tea","medical":"normal","family":"none","treatment_history":"none","help_seeking_delay":"four months","prior_contacts":["a colleague"]},"cognitive_model":{"core_belief":"If it happens on the train I won''t be able to get out.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The cab costs a third of his salary and his wife does not know.","gate":"two_or_more_reflective_statements"},{"fact":"He feels like a weakling because his father commuted for 35 years.","gate":"validation_given"},{"fact":"He sits near doors everywhere now.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Traffic is better by cab anyway."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Drew the panic cycle with him","Identified safety behaviours (sitting near doors)","Asked about costs of avoidance","Explained exposure and CBT in plain words"],"few_shot":[],"fixture_lines":["Two million people take that train. I can''t take it anymore. Funny, no?","Now shared cab. Eight hundred a day. Don''t tell my wife.","My father did thirty-five years on the Central line. Never complained.","In any room, I sit near the door. Just in case."],"variation":{"mood_today":["friendly","embarrassed","tense"],"recent_event":["a train strike","wife found a cab receipt","attack in a lift"],"most_defended_topic":["hiding the cab cost"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Marathi-Hindi-English Mumbai mix"]},"moves":{},"module_id":"anxiety","voice_key":"Marathi-Hindi-English Mumbai mix@Thane","protective_factors":["supportive wife","motivation"],"library":{"level":2,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the panic cycle and how avoidance keeps it going","expected_mse":{"appearance":"Office wear","behaviour":"Restless","speech":"Normal","mood":"''Tense''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of being trapped","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Panic disorder with agoraphobic avoidance","differentials":[{"dx":"Specific phobia (trains)","why_not":"Unexpected attacks and anticipatory worry point to panic disorder with spreading avoidance"},{"dx":"Cardiac cause","why_not":"Check with a basic examination and ECG once"},{"dx":"Social anxiety","why_not":"Fear is of being trapped, not of judgement"}],"debrief_rubric":["Drew the panic cycle with him","Identified safety behaviours (sitting near doors)","Asked about costs of avoidance","Explained exposure and CBT in plain words"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Daniel, 40: the whisky that calms the worry', 'lib-cr-037', 'resistant', '{"case_id":"cr-037","slug":"lib-cr-037","title":"Daniel, 40: the whisky that calms the worry","difficulty":"resistant","traps":["substance_induced","adherence_fiction"],"traps_authored":["substance_induced","adherence_fiction"],"identity":{"name":"Daniel D''Souza","age":40,"gender":"male","occupation":"hotel food-and-beverage manager","city":"Bengaluru","family_structure":"divorced, shares custody of a daughter","language_register":"polished hospitality English, charming"},"presentation":"Long-standing worry and social unease, now drinking four to six pegs nightly to calm down; morning anxiety and shakiness relieved by drinking; daughter''s school counsellor raised concern.","chief_complaint_in_own_words":"I''m a worrier, always have been. A couple of drinks takes the edge off. Doesn''t everyone in hospitality?","history":{"timeline":"Worry since his twenties; drinking escalated after the divorce three years ago; morning tremor six months.","substance_use":"whisky four to six pegs nightly, morning tremor","medical":"fatty liver on scan","family":"father drank","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["daughter''s school counsellor"]},"cognitive_model":{"core_belief":"Without a drink I can''t face people.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"His mornings are the worst: shaking hands and dread until the first drink at lunch.","gate":"two_or_more_reflective_statements"},{"fact":"He fears losing custody if anyone knows.","gate":"validation_given"},{"fact":"He drove his daughter to school after a late night once and has not forgiven himself.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m a social drinker, it comes with the job."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: occasional ''what''s the point'' when drunk; no plan. Driving after drinking with his child is a safeguarding concern.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified alcohol and asked about withdrawal","Explored how anxiety and drinking feed each other","Asked about suicide and the child''s safety sensitively","Used a motivational, non-judgemental approach"],"few_shot":[],"fixture_lines":["I manage a restaurant of 140 covers. Smile, small talk, the works. Inside, a washing machine.","Mornings are the worst. Hands shaking until lunch.","Two drinks and the world becomes manageable. Okay, four.","If my ex finds out, she''ll go to court. I know she will."],"variation":{"mood_today":["charming","anxious","defensive"],"recent_event":["custody weekend","a big banquet","a liver scan report"],"most_defended_topic":["driving his daughter after drinking"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["polished hospitality English, charming"]},"moves":{},"module_id":"substance","voice_key":"polished hospitality English, charming@Bengaluru","protective_factors":["daughter","career"],"library":{"level":5,"topic":"anxiety","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Assess anxiety maintained by alcohol self-medication","expected_mse":{"appearance":"Well groomed, mild tremor","behaviour":"Restless","speech":"Fluent, charming","mood":"''Edgy''","affect":"Anxious","thought_form":"Coherent","thought_content":"Worry, fear of losing custody","perception":"Nil","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Alcohol dependence with underlying anxiety (social and generalised features)","differentials":[{"dx":"Alcohol withdrawal anxiety","why_not":"Morning symptoms relieved by drink indicate withdrawal adding to anxiety"},{"dx":"Generalised anxiety disorder alone","why_not":"Worry predates drinking but dependence now drives much of it"},{"dx":"Social anxiety disorder","why_not":"Social unease is present; assess after abstinence"}],"debrief_rubric":["Quantified alcohol and asked about withdrawal","Explored how anxiety and drinking feed each other","Asked about suicide and the child''s safety sensitively","Used a motivational, non-judgemental approach"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Lalitha, 55: the chemist''s sleeping tablet', 'lib-cr-038', 'guarded', '{"case_id":"cr-038","slug":"lib-cr-038","title":"Lalitha, 55: the chemist''s sleeping tablet","difficulty":"guarded","traps":["iatrogenic","polypharmacy"],"traps_authored":["iatrogenic","polypharmacy"],"identity":{"name":"Lalitha Subramanian","age":55,"gender":"female","occupation":"homemaker","city":"Chennai","family_structure":"married, two married daughters","language_register":"Tamil-English, polite, anxious"},"presentation":"Ten years of taking a benzodiazepine bought over the counter, now three tablets a day; anxiety, poor sleep and irritability when she misses doses; recently fell at night.","chief_complaint_in_own_words":"Without my tablet I cannot sleep or sit. My heart flutters. The chemist knows me, he gives.","history":{"timeline":"Started after her mother''s death ten years ago on a doctor''s prescription; dose crept up; doctor never reviewed.","substance_use":"alprazolam three tablets daily, bought from the chemist","medical":"osteoporosis, fell at night","family":"none","treatment_history":"the original prescription","help_seeking_delay":"ten years","prior_contacts":["the chemist","a GP who renewed once"]},"cognitive_model":{"core_belief":"Without the tablet I will break down.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She once missed doses for two days and felt shaky, sweaty and ''electric''.","gate":"two_or_more_reflective_statements"},{"fact":"Her daughters scold her for ''addiction'' and she feels ashamed.","gate":"validation_given"},{"fact":"She fell at night going to the bathroom two weeks ago.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["The doctor gave it first, so it must be safe."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Physical risk: falls; abrupt stopping risks withdrawal including seizures. Needs a slow, supervised taper.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took a clear history of dose escalation and withdrawal","Warned against stopping abruptly","Asked about falls and safety","Planned a slow taper with alternatives for anxiety, without shaming"],"few_shot":[],"fixture_lines":["One tablet at night became one in the afternoon. Now one in the morning also.","When I missed two days I felt current in my body. Shaking.","The chemist uncle knows me thirty years. He just gives.","My daughters say I am addicted. I am not a drunkard. It is only a tablet."],"variation":{"mood_today":["anxious","polite","ashamed"],"recent_event":["daughter''s scolding call","the night fall","chemist ran out of stock"],"most_defended_topic":["buying without prescription"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Tamil-English, polite, anxious"]},"moves":{},"module_id":"substance","voice_key":"Tamil-English, polite, anxious@Chennai","protective_factors":["daughters who care","long marriage"],"library":{"level":5,"topic":"anxiety","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise benzodiazepine dependence in an anxious patient","expected_mse":{"appearance":"Neat, bruise on forearm","behaviour":"Restless","speech":"Soft","mood":"''Fluttery''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of breaking down without the tablet","perception":"Nil","cognition":"Mildly slowed attention","insight_judgement":"Partial"},"diagnosis":"Sedative-hypnotic (benzodiazepine) dependence with underlying anxiety","differentials":[{"dx":"Generalised anxiety disorder","why_not":"May underlie it, but rebound and withdrawal now drive much of the anxiety"},{"dx":"Depressive episode","why_not":"Low mood often sits under long sedative use; screen for it now and again once the dose is lower"},{"dx":"Early cognitive impairment","why_not":"Benzodiazepines slow attention; reassess after taper"}],"debrief_rubric":["Took a clear history of dose escalation and withdrawal","Warned against stopping abruptly","Asked about falls and safety","Planned a slow taper with alternatives for anxiety, without shaming"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ishaan, 25: the sitar and the stage', 'lib-cr-039', 'cooperative', '{"case_id":"cr-039","slug":"lib-cr-039","title":"Ishaan, 25: the sitar and the stage","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Ishaan Mishra","age":25,"gender":"male","occupation":"sitar player and music teacher","city":"Varanasi","family_structure":"lives with his guru''s family","language_register":"soft Hindi, poetic"},"presentation":"Severe fear, tremor and blanking only when performing in public; fine in teaching, socialising and recording at home. Avoided two concerts this season.","chief_complaint_in_own_words":"Alone, I play like water. On stage my fingers become stone.","history":{"timeline":"Began after a poorly received concert two years ago; now cancels performances.","substance_use":"bhang at Holi only","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"two years","prior_contacts":["his guru"]},"cognitive_model":{"core_belief":"The audience can hear every mistake and will judge my guru through me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He cancelled the Ganga Mahotsav concert he dreamed of.","gate":"two_or_more_reflective_statements"},{"fact":"He fears shaming his guru more than anything.","gate":"validation_given"},{"fact":"A friend gave him a tablet before a concert once that ''stopped the shaking''.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe I am not meant to perform."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Established the performance-only pattern","Explored the feared judgement","Asked about any medicines borrowed","Explained graded exposure and options for performance situations"],"few_shot":[],"fixture_lines":["In the riyaz room I play two hours and forget time.","On stage, the lights, the faces. My right hand starts to shake.","Guruji says, ''you are ready''. If I fail, it is his name.","Teaching children, no problem. Chatting with anyone, no problem. Only the stage."],"variation":{"mood_today":["gentle","nervous","hopeful"],"recent_event":["a concert invitation","guruji''s praise","a review of another musician"],"most_defended_topic":["fear of shaming his guru"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["soft Hindi, poetic"]},"moves":{},"module_id":"anxiety","voice_key":"soft Hindi, poetic@Varanasi","protective_factors":["guru''s support","deep skill"],"library":{"level":2,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the performance-only form of social anxiety","expected_mse":{"appearance":"Kurta, calm","behaviour":"Settled","speech":"Soft, fluent","mood":"''Afraid of the stage''","affect":"Anxious only on the topic","thought_form":"Coherent","thought_content":"Fear of judgement during performance","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Social anxiety disorder, performance-only","differentials":[{"dx":"Generalised social anxiety","why_not":"He is at ease teaching and socialising; the fear appears only when performing"},{"dx":"Specific phobia","why_not":"Fear is of being judged, which places it in social anxiety"},{"dx":"Essential tremor","why_not":"A true tremor would show at home too; his shaking appears only on stage with fear"}],"debrief_rubric":["Established the performance-only pattern","Explored the feared judgement","Asked about any medicines borrowed","Explained graded exposure and options for performance situations"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sunanda, 39: the mother who cannot stop checking his breathing', 'lib-cr-040', 'guarded', '{"case_id":"cr-040","slug":"lib-cr-040","title":"Sunanda, 39: the mother who cannot stop checking his breathing","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Sunanda Pawar","age":39,"gender":"female","occupation":"bank clerk on unpaid leave","city":"Nashik","family_structure":"married; son of 9 with cerebral palsy and seizures","language_register":"Marathi-English, exhausted, sharp"},"presentation":"Constant worry about her son''s seizures, money, her job and the future, with poor sleep, muscle pain and irritability for two years; hardly sleeps through the night.","chief_complaint_in_own_words":"I am not the patient. My son is. I just need something so I can sleep.","history":{"timeline":"Since her son''s seizures increased two years ago; took unpaid leave; worry has spread to everything.","substance_use":"none","medical":"back pain","family":"none","treatment_history":"none","help_seeking_delay":"two years","prior_contacts":["son''s neurologist"]},"cognitive_model":{"core_belief":"If I sleep, he will die.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She checks his breathing every hour at night.","gate":"two_or_more_reflective_statements"},{"fact":"She feels her husband has emotionally left the care to her.","gate":"validation_given"},{"fact":"She has not met a friend in a year.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Any mother would be like this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: fleeting thoughts ''what will happen if I die'', no suicidal wish. Low risk, high carer burden.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Validated the real burden","Explored worry across domains","Asked about suicide and her own health","Discussed respite, support groups and carer benefits"],"few_shot":[],"fixture_lines":["Every hour I wake and put my hand on his chest. Up, down. Then I sleep fifty minutes.","The bank gave unpaid leave. Unpaid. With his medicines.","My husband says ''you handle him better''. Better means alone.","What will happen to him when I''m gone? That one question eats my nights."],"variation":{"mood_today":["exhausted","sharp","tearful"],"recent_event":["a seizure last week","the bank''s leave letter","therapy bill"],"most_defended_topic":["anger at her husband"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Marathi-English, exhausted, sharp"]},"moves":{},"module_id":"anxiety","voice_key":"Marathi-English, exhausted, sharp@Nashik","protective_factors":["love for her son","neurologist support"],"library":{"level":3,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester"],"objective":"Assess generalised anxiety in a carer of a disabled child","expected_mse":{"appearance":"Tired, hair tied hastily","behaviour":"Restless","speech":"Rapid, pressured","mood":"''Exhausted''","affect":"Anxious, tearful","thought_form":"Coherent","thought_content":"Worry about son and future","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Generalised anxiety disorder with severe carer strain","differentials":[{"dx":"Depressive episode","why_not":"Screen for anhedonia and hopelessness"},{"dx":"Adjustment disorder","why_not":"Duration and spread of worry beyond the stressor suggest GAD"},{"dx":"Realistic worry","why_not":"Severity and impairment exceed what can be managed"}],"debrief_rubric":["Validated the real burden","Explored worry across domains","Asked about suicide and her own health","Discussed respite, support groups and carer benefits"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Rohit, 33: after the accident he will not drive', 'lib-cr-041', 'guarded', '{"case_id":"cr-041","slug":"lib-cr-041","title":"Rohit, 33: after the accident he will not drive","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Rohit Bansal","age":33,"gender":"male","occupation":"pharmaceutical sales manager","city":"Chandigarh","family_structure":"married, one daughter","language_register":"Punjabi-English, matter-of-fact"},"presentation":"Car accident four months ago in which a truck hit his car; no one died. Now avoids driving and gets anxious as a passenger; also nightmares, flashbacks, startle and irritability.","chief_complaint_in_own_words":"I just don''t feel like driving. My wife drives now. It''s no big deal.","history":{"timeline":"Accident four months ago on the Ambala highway; avoidance began immediately; nightmares three nights a week.","substance_use":"two drinks at night since the accident","medical":"fractured wrist, healed","family":"none","treatment_history":"orthopaedic follow-up","help_seeking_delay":"four months","prior_contacts":["orthopaedic surgeon"]},"cognitive_model":{"core_belief":"The road is a death trap and I can''t protect my family.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He relives the headlights and the sound of metal several times a day.","gate":"two_or_more_reflective_statements"},{"fact":"His daughter was in the back seat and he feels he failed her.","gate":"validation_given"},{"fact":"He jumps at horns and has shouted at his wife while she drives.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just that I don''t like highways."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk; alcohol rise noted.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked beyond avoidance about intrusions, nightmares and arousal","Asked about guilt and the daughter","Asked about alcohol","Asked about mood and suicide"],"few_shot":[],"fixture_lines":["The truck''s lights. Then the sound. Like a steel almirah falling.","My daughter was in the back. She''s fine. I keep seeing her face in the mirror.","Any horn and I jump. My wife thinks I''m angry with her.","Two drinks to sleep. Otherwise the dream comes."],"variation":{"mood_today":["matter-of-fact","tense","irritable"],"recent_event":["a near-miss as a passenger","insurance call","a night of nightmares"],"most_defended_topic":["his daughter in the back seat"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Punjabi-English, matter-of-fact"]},"moves":{},"module_id":"trauma","voice_key":"Punjabi-English, matter-of-fact@Chandigarh","protective_factors":["wife","daughter unharmed"],"library":{"level":4,"topic":"anxiety","module":"trauma","exams":["md-psychiatry","mcp-entrance"],"objective":"Tell a driving phobia apart from post-traumatic stress","expected_mse":{"appearance":"Neat","behaviour":"Tense, startles at noise","speech":"Normal","mood":"''Fine''","affect":"Anxious, restricted","thought_form":"Coherent","thought_content":"Guilt about daughter, danger beliefs","perception":"Re-experiencing images, no hallucinations","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Post-traumatic stress disorder","differentials":[{"dx":"Specific phobia (driving)","why_not":"Re-experiencing, nightmares, startle and irritability go beyond phobic avoidance"},{"dx":"Acute stress disorder","why_not":"Symptoms have lasted more than a month"},{"dx":"Alcohol misuse","why_not":"Rising drinking to sleep needs addressing"}],"debrief_rubric":["Asked beyond avoidance about intrusions, nightmares and arousal","Asked about guilt and the daughter","Asked about alcohol","Asked about mood and suicide"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Nirmala, 46: low and tense, neither one clearly', 'lib-cr-042', 'cooperative', '{"case_id":"cr-042","slug":"lib-cr-042","title":"Nirmala, 46: low and tense, neither one clearly","difficulty":"cooperative","traps":["over_diagnosis"],"traps_authored":["over_diagnosis"],"identity":{"name":"Nirmala Joshi","age":46,"gender":"female","occupation":"anganwadi supervisor","city":"Almora","family_structure":"married, two sons","language_register":"Kumaoni Hindi, frank"},"presentation":"Six months of both worry and low mood, poor sleep, tiredness and irritability. Neither set of symptoms alone is very severe; functioning slightly reduced.","chief_complaint_in_own_words":"Mann bhi udaas, aur ghabrahat bhi. Both together. Not too much, but every day.","history":{"timeline":"Six months since her husband''s transfer to Delhi; she manages the house and work alone.","substance_use":"none","medical":"perimenopausal","family":"none","treatment_history":"none","help_seeking_delay":"six months","prior_contacts":["the ANM"]},"cognitive_model":{"core_belief":"I must manage everything or the house will fall apart.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She feels low most days but still enjoys her sons'' calls.","gate":"two_or_more_reflective_statements"},{"fact":"She is angry her husband took the transfer without asking.","gate":"validation_given"},{"fact":"Her periods have become irregular with hot flushes.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Every woman my age feels like this."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Measured both mood and anxiety symptoms against thresholds","Asked about perimenopause","Asked about suicide clearly","Explored the stress of the husband''s transfer"],"few_shot":[],"fixture_lines":["Udaas bhi, ghabrahat bhi. Like a pot that boils but never spills.","My husband went to Delhi for the promotion. Didn''t ask me.","Night I wake hot, sweating, then can''t sleep.","I still laugh with the anganwadi women. So it''s not too bad, na?"],"variation":{"mood_today":["frank","tired","irritable"],"recent_event":["husband''s weekend visit","son''s exam","a hot flush at work"],"most_defended_topic":["anger about the transfer"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Kumaoni Hindi, frank"]},"moves":{},"module_id":"anxiety","voice_key":"Kumaoni Hindi, frank@Almora","protective_factors":["work she enjoys","sons"],"library":{"level":3,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester"],"objective":"Apply criteria when anxiety and low mood overlap","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Normal","mood":"''Udaas and tense''","affect":"Mildly anxious and low","thought_form":"Coherent","thought_content":"Worry, resentment","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Mixed anxiety and depressive symptoms (ICD-11 mixed depressive and anxiety disorder) with perimenopausal contribution","differentials":[{"dx":"Depressive episode","why_not":"Low mood and other symptoms do not reach episode threshold"},{"dx":"Generalised anxiety disorder","why_not":"Worry is not the dominant feature"},{"dx":"Perimenopause","why_not":"Hot flushes and sleep loss contribute and need gynaecological review"}],"debrief_rubric":["Measured both mood and anxiety symptoms against thresholds","Asked about perimenopause","Asked about suicide clearly","Explored the stress of the husband''s transfer"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Chopra, 68: breathless and frightened at night', 'lib-cr-043', 'cooperative', '{"case_id":"cr-043","slug":"lib-cr-043","title":"Mr Chopra, 68: breathless and frightened at night","difficulty":"cooperative","traps":["iatrogenic","medical_mimic"],"traps_authored":["iatrogenic","medical_mimic"],"identity":{"name":"Inderjit Chopra","age":68,"gender":"male","occupation":"retired army subedar","city":"Amritsar","family_structure":"lives with wife; sons nearby","language_register":"Punjabi, proud, gruff"},"presentation":"COPD from long smoking; nightly episodes of breathlessness with terror and racing heart; asks for ''a strong sleeping tablet''.","chief_complaint_in_own_words":"At night the breath stops coming and I''m sure I''ll die. Give me a strong sleeping tablet, doctor sahib.","history":{"timeline":"Breathlessness over years; night terrors of suffocation six months; uses home oxygen sometimes.","substance_use":"smoked 40 years, quit two years ago","medical":"COPD, home oxygen at night","family":"none","treatment_history":"inhalers","help_seeking_delay":"six months","prior_contacts":["chest physician"]},"cognitive_model":{"core_belief":"Each night may be the last breath.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He sleeps sitting in a chair to avoid the night attacks.","gate":"two_or_more_reflective_statements"},{"fact":"He hates being dependent after a life as a soldier.","gate":"validation_given"},{"fact":"A neighbour gave him a sleeping tablet once and he woke very drowsy and breathless.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Just give me something strong."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Physical risk: sedatives may depress breathing in COPD.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Linked night breathlessness to the fear cycle","Advised against sedatives that can depress breathing","Liaised with the chest physician","Taught breathing and pacing techniques","Gave psychoeducation about breathlessness and fear feeding each other"],"few_shot":[],"fixture_lines":["I fought in two wars. I''m not afraid of anything. Except this.","At two o''clock the breath stops coming. My heart jumps.","I sleep in the chair now. The bed feels like a grave.","That tablet from Gill sahib, I woke up like a dead man."],"variation":{"mood_today":["gruff","frightened","proud"],"recent_event":["a bad night","oxygen cylinder delay","army reunion invitation"],"most_defended_topic":["feeling dependent"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Punjabi, proud, gruff"]},"moves":{},"module_id":"anxiety","voice_key":"Punjabi, proud, gruff@Amritsar","protective_factors":["military resilience","family"],"library":{"level":4,"topic":"anxiety","module":"anxiety","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise anxiety in chronic lung disease and avoid harmful sedatives","expected_mse":{"appearance":"Thin, barrel chest, nasal cannula","behaviour":"Uses accessory muscles","speech":"Short phrases","mood":"''Scared at night''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of suffocation","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Anxiety (panic-type episodes) associated with COPD","differentials":[{"dx":"Panic disorder","why_not":"Attacks are tied to breathlessness in COPD; treat both"},{"dx":"Worsening COPD or sleep apnoea","why_not":"Worsening lung disease or sleep apnoea can cause night breathlessness, so the chest physician should review him"},{"dx":"Heart failure","why_not":"Night breathlessness needs physical check"}],"debrief_rubric":["Linked night breathlessness to the fear cycle","Advised against sedatives that can depress breathing","Liaised with the chest physician","Taught breathing and pacing techniques","Gave psychoeducation about breathlessness and fear feeding each other"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Meenal, 21: dizzy in every lecture', 'lib-cr-044', 'cooperative', '{"case_id":"cr-044","slug":"lib-cr-044","title":"Meenal, 21: dizzy in every lecture","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Meenal Thakur","age":21,"gender":"female","occupation":"final-year nursing student","city":"Shimla","family_structure":"hostel; parents in Mandi","language_register":"fast Hindi-English, worried"},"presentation":"Episodes of dizziness, tingling around the mouth and fingers, chest tightness and fear during lectures and ward rounds; breathes fast and shallow.","chief_complaint_in_own_words":"My fingers tingle, my lips go numb, I feel like I''ll faint. Then everyone stares.","history":{"timeline":"Started with ward postings two months ago; several episodes a week.","substance_use":"none","medical":"normal blood tests","family":"mother anxious","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["hostel warden"]},"cognitive_model":{"core_belief":"I''ll faint in front of the doctors and fail.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She breathes fast and shallow when a senior questions her.","gate":"two_or_more_reflective_statements"},{"fact":"She thinks she isn''t good enough to be a nurse.","gate":"validation_given"},{"fact":"She fainted once in school assembly and was teased.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe it''s low BP."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about breathing during episodes","Explained overbreathing and its symptoms","Taught slow breathing","Explored self-doubt about her career"],"few_shot":[],"fixture_lines":["My fingers start tingling, then my lips. Then the room spins.","Sister Tenzin asks me a question and my breath goes fast-fast.","Once in school assembly I fainted. Everybody laughed.","Maybe I''m not made for nursing."],"variation":{"mood_today":["worried","chatty","self-doubting"],"recent_event":["a ward viva","an episode in class","mother''s call"],"most_defended_topic":["doubt about being a nurse"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fast Hindi-English, worried"]},"moves":{},"module_id":"anxiety","voice_key":"fast Hindi-English, worried@Shimla","protective_factors":["motivation","supportive peers"],"library":{"level":1,"topic":"anxiety","module":"anxiety","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise overbreathing as a source of anxious body symptoms","expected_mse":{"appearance":"Uniform, neat","behaviour":"Restless","speech":"Fast","mood":"''Scared of fainting''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fear of fainting and failing","perception":"Tingling during episodes","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Panic-type attacks with hyperventilation (assess for panic disorder)","differentials":[{"dx":"Hypoglycaemia","why_not":"Episodes are linked to stress and overbreathing; check if any link with fasting"},{"dx":"Vasovagal syncope","why_not":"Prodrome includes tingling from overbreathing"},{"dx":"Epilepsy","why_not":"No loss of consciousness with jerks or confusion"}],"debrief_rubric":["Asked about breathing during episodes","Explained overbreathing and its symptoms","Taught slow breathing","Explored self-doubt about her career"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sai Kiran, 20: the professors are reading his notebook', 'lib-cr-045', 'guarded', '{"case_id":"cr-045","slug":"lib-cr-045","title":"Sai Kiran, 20: the professors are reading his notebook","difficulty":"guarded","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Sai Kiran Reddy","age":20,"gender":"male","occupation":"second-year B.Tech student","city":"Hyderabad (Gachibowli hostel)","family_structure":"parents in Nalgonda, farmers","language_register":"Telugu-English, flat, suspicious"},"presentation":"Eight months of slow withdrawal, falling grades and poor self-care, then three months of hearing two voices commenting on his actions and a belief that professors insert thoughts into his head through the projector.","chief_complaint_in_own_words":"They know what I''m thinking before I say it. It comes through the projector in the lab. I''m not sick. I need a different hostel.","history":{"timeline":"Withdrew from friends eight months ago; grades fell; three months of voices; stopped attending; parents called by the warden.","substance_use":"no cannabis, no alcohol","medical":"normal","family":"maternal aunt ''had a nervous problem, stayed home''","treatment_history":"temple visit","help_seeking_delay":"eight months","prior_contacts":["the warden","a temple priest"]},"cognitive_model":{"core_belief":"Something is being done to my mind from outside.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"Two male voices talk about him in the third person, saying ''now he''s brushing his teeth, now he''s lying''.","gate":"validation_given"},{"fact":"He believes the professors put thoughts in his head through the lab projector and has covered his laptop camera with tape.","gate":"two_or_more_reflective_statements"},{"fact":"He has not eaten in the mess for weeks because he thinks the food is being watched.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["The hostel is the problem. Change my hostel."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; frightened. No thoughts of harming the professors, but avoids them. Low to moderate risk; self-neglect.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about voices and beliefs with neutral curiosity","Did not argue with the beliefs","Took a prodrome timeline and family history","Asked about suicide clearly and about harm to others","Kept engagement despite poor insight"],"few_shot":[],"fixture_lines":["When I sit in the lab, the projector hums, and my thoughts are not my thoughts anymore.","I taped my laptop camera. And the phone. They don''t need cameras, but still.","I eat biscuits in my room. The mess is too open.","My parents are simple people. Don''t tell them I''m mad. I''m not mad."],"variation":{"mood_today":["suspicious","flat","frightened"],"recent_event":["a lab class","parents arrived from Nalgonda","the warden''s warning letter"],"most_defended_topic":["the voices"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Telugu-English, flat, suspicious"]},"moves":{},"module_id":"psychosis","voice_key":"Telugu-English, flat, suspicious@Hyderabad (Gachibowli hostel)","protective_factors":["parents who came quickly","good school record"],"library":{"level":1,"topic":"psychosis","module":"psychosis","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise the first-rank features of a first psychotic episode","expected_mse":{"appearance":"Unwashed, same shirt for days, thin","behaviour":"Guarded, glances at the ceiling light","speech":"Sparse, slow, some long pauses","mood":"''Fine''","affect":"Flat, incongruent smile at times","thought_form":"Some derailment","thought_content":"Delusion of thought insertion and reference; persecutory ideas","perception":"Third-person running commentary voices","cognition":"Oriented; attention poor","insight_judgement":"No insight"},"diagnosis":"Schizophrenia (first episode)","differentials":[{"dx":"Schizophreniform disorder","why_not":"Total duration including prodrome exceeds six months, so schizophrenia criteria are met"},{"dx":"Substance-induced psychosis","why_not":"Denies drugs; a urine screen is still sensible"},{"dx":"Depression with psychotic features","why_not":"No pervasive low mood; psychotic features are not mood-congruent"}],"debrief_rubric":["Asked about voices and beliefs with neutral curiosity","Did not argue with the beliefs","Took a prodrome timeline and family history","Asked about suicide clearly and about harm to others","Kept engagement despite poor insight"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Shabnam, 37: back again, the tablets in the drawer', 'lib-cr-046', 'resistant', '{"case_id":"cr-046","slug":"lib-cr-046","title":"Shabnam, 37: back again, the tablets in the drawer","difficulty":"resistant","traps":["adherence_fiction","cultural_idiom"],"traps_authored":["adherence_fiction","cultural_idiom"],"identity":{"name":"Shabnam Qureshi","age":37,"gender":"female","occupation":"tailor working from home","city":"Aligarh","family_structure":"divorced, lives with brother''s family","language_register":"Urdu-Hindi, sharp, wary"},"presentation":"Known schizophrenia for ten years, well on medicine for three years, stopped two months ago; now hearing voices again, accusing neighbours of black magic, not sleeping.","chief_complaint_in_own_words":"I am fine. The neighbours are doing jaadu-tona. Ask them why they are doing it. Why am I here?","history":{"timeline":"Stopped her antipsychotic two months ago after weight gain and drowsiness; relapsed over six weeks.","prior_episodes":"three admissions, last four years ago","substance_use":"none","medical":"weight gain, prediabetes","family":"father had similar illness","treatment_history":"risperidone, stopped","help_seeking_delay":"two months","prior_contacts":["a peer who said tablets are poison","a dargah"]},"cognitive_model":{"core_belief":"The tablets make me fat and stupid, the illness was the jaadu.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She stopped the tablets because she gained 12 kg and could not work the sewing machine fast enough.","gate":"validation_given"},{"fact":"The voices say the neighbour woman is putting lemons and chillies at the door.","gate":"two_or_more_reflective_statements"},{"fact":"Her brother hides her tablets in her food and she has found out.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Talk to the neighbours, not me."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Has shouted at the neighbour and threatened to ''teach her a lesson''; no weapon or plan. Moderate risk to others; needs careful review.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":["MHA 2017"]},"style_refs":[],"rubric_targets":["Asked about her reasons for stopping without judgement","Took side effects seriously and discussed alternatives","Assessed risk to the neighbour","Raised the covert medication issue ethically","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["Three years I took them. I became like a sack of rice. Twelve kilos.","Lemon and chillies at my door every morning. You think that''s an accident?","My bhai thinks I don''t know. He crushes them in my dal. I can taste it.","My hands were so slow at the machine. Orders went to the shop on the corner."],"variation":{"mood_today":["sharp","suspicious","hurt"],"recent_event":["a shouting match with the neighbour","brother called the doctor","a big order pending"],"most_defended_topic":["the hidden tablets"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Urdu-Hindi, sharp, wary"]},"moves":{},"module_id":"psychosis","voice_key":"Urdu-Hindi, sharp, wary@Aligarh","protective_factors":["skill as a tailor","brother who cares"],"library":{"level":3,"topic":"psychosis","module":"psychosis","exams":["mcp-entrance","md-psychiatry"],"objective":"Explore reasons for stopping medicine in relapse","expected_mse":{"appearance":"Neat, burqa, alert","behaviour":"Restless, watchful","speech":"Loud at times, pressured when angry","mood":"''Angry''","affect":"Irritable, suspicious","thought_form":"Coherent with some tangentiality","thought_content":"Persecutory belief about black magic by neighbour","perception":"Voices commenting, says the neighbour''s voice","cognition":"Intact","insight_judgement":"Poor insight, good about side effects"},"diagnosis":"Schizophrenia, relapse after stopping medicine","differentials":[{"dx":"Delusional disorder","why_not":"Prior course with hallucinations and relapses fits schizophrenia"},{"dx":"Cultural belief in black magic","why_not":"Belief is held with distress, out of proportion, with voices and relapse pattern; but respect the cultural frame"},{"dx":"Mood disorder with psychosis","why_not":"No sustained high or low mood runs alongside the psychotic symptoms, so a mood disorder does not explain them"}],"debrief_rubric":["Asked about her reasons for stopping without judgement","Took side effects seriously and discussed alternatives","Assessed risk to the neighbour","Raised the covert medication issue ethically","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Bhatt, 52: the wife and the milkman', 'lib-cr-047', 'resistant', '{"case_id":"cr-047","slug":"lib-cr-047","title":"Mr Bhatt, 52: the wife and the milkman","difficulty":"resistant","traps":["late_risk_reveal"],"traps_authored":["late_risk_reveal"],"identity":{"name":"Haresh Bhatt","age":52,"gender":"male","occupation":"owns a hardware shop","city":"Rajkot","family_structure":"married 28 years, two grown sons","language_register":"Gujarati, controlled, intense"},"presentation":"A year of fixed belief that his wife is having an affair with the milkman; checks her phone, saree and bedsheets, follows her; otherwise functions well; no hallucinations.","chief_complaint_in_own_words":"My wife is lying to me. I have proof. I came only because my sons forced me. Ask her to confess.","history":{"timeline":"Belief started a year ago; checking, interrogating and following escalated; sons moved home to protect their mother.","substance_use":"three pegs on weekends","medical":"diabetes; erectile difficulty for two years","family":"none","treatment_history":"none","help_seeking_delay":"a year","prior_contacts":["a private detective he hired"]},"cognitive_model":{"core_belief":"She has betrayed me and everyone knows except me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He hired a private detective who found nothing, and he believes the detective was bribed.","gate":"validation_given"},{"fact":"He checks her saree and the bedsheets each night for ''signs''.","gate":"two_or_more_reflective_statements"},{"fact":"He has had erectile problems for two years and feels ashamed.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I am a businessman, I think logically."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. He has grabbed his wife''s arm and said ''one day I''ll finish this''. High risk of violence to the wife; needs urgent safety planning for her.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":["duty to protect the spouse"]},"style_refs":[],"rubric_targets":["Explored the belief without colluding or arguing","Asked about checking and confrontations","Assessed violence risk to the wife and planned her safety","Asked about suicide clearly","Asked sensitively about sexual problems and alcohol"],"few_shot":[],"fixture_lines":["The milkman comes at six. She is always awake at six. You see the pattern?","I paid a detective twenty thousand. He found ''nothing''. Somebody paid him more.","Every night I check. You don''t want to know what I check.","Twenty-eight years. And now she laughs at me with the whole colony."],"variation":{"mood_today":["controlled","intense","bitter"],"recent_event":["the milkman''s new hours","a son confronted him","wife visited her sister"],"most_defended_topic":["erectile problems"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Gujarati, controlled, intense"]},"moves":{},"module_id":"psychosis","voice_key":"Gujarati, controlled, intense@Rajkot","protective_factors":["sons","functioning business"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance","ugc-net"],"objective":"Recognise delusional jealousy and its risk","expected_mse":{"appearance":"Well dressed","behaviour":"Tense, leans forward","speech":"Normal rate, insistent","mood":"''Betrayed''","affect":"Angry, constricted","thought_form":"Coherent, circumstantial about ''evidence''","thought_content":"Fixed, systematised delusion of infidelity","perception":"No hallucinations","cognition":"Intact","insight_judgement":"No insight"},"diagnosis":"Delusional disorder, jealous type","differentials":[{"dx":"Schizophrenia","why_not":"No hallucinations, no thought disorder, functioning preserved: fits delusional disorder"},{"dx":"Alcohol-related jealousy","why_not":"Drinking is modest; still assess"},{"dx":"Obsessive jealousy","why_not":"He is convinced, not doubting, and does not see the thoughts as excessive"}],"debrief_rubric":["Explored the belief without colluding or arguing","Asked about checking and confrontations","Assessed violence risk to the wife and planned her safety","Asked about suicide clearly","Asked sensitively about sexual problems and alcohol"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Pereira, 59: the neighbours drill through the wall', 'lib-cr-048', 'guarded', '{"case_id":"cr-048","slug":"lib-cr-048","title":"Mrs Pereira, 59: the neighbours drill through the wall","difficulty":"guarded","traps":["medical_mimic","diagnostic_overshadowing"],"traps_authored":["medical_mimic","diagnostic_overshadowing"],"identity":{"name":"Agnes Pereira","age":59,"gender":"female","occupation":"retired telephone operator","city":"Mumbai (Bandra)","family_structure":"unmarried, lives alone","language_register":"Bombay English, formal, suspicious"},"presentation":"Two years of belief that neighbours drill through the wall at night and pump gas into her flat; hears their voices plotting; significant hearing loss, lives alone; otherwise functions.","chief_complaint_in_own_words":"They drill at night. Through the bedroom wall. And they talk about me in the next flat. I want a letter from you for the society.","history":{"timeline":"Started two years after retirement and her sister''s death; worse at night; has called the police twice.","substance_use":"none","medical":"bilateral hearing loss, no hearing aid; hypertension","family":"none known","treatment_history":"none","help_seeking_delay":"two years","prior_contacts":["the police","the housing society secretary"]},"cognitive_model":{"core_belief":"People want me out of my flat.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She lives alone since her sister died, and talks to nobody most days.","gate":"validation_given"},{"fact":"She hears the neighbours say her name and ''tonight we''ll finish her''.","gate":"two_or_more_reflective_statements"},{"fact":"She can barely hear the phone and has stopped answering.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I have been a telephone operator for thirty years. I know what I hear."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Has slept on the stairs to escape ''gas''. Moderate risk from self-neglect and conflict with neighbours.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Noticed and adjusted for her hearing loss","Explored isolation and bereavement","Screened cognition","Asked about suicide and self-neglect","Recommended hearing assessment and social support alongside treatment"],"few_shot":[],"fixture_lines":["Two o''clock every night. Brrrr. Through the wall, near my head.","And then the talking. ''Tonight we''ll finish her.'' I heard it clearly.","Since Philomena died, I have no one to ask if they hear it too.","I want a certificate for the society. Saying I''m sane and they are the problem."],"variation":{"mood_today":["formal","suspicious","lonely"],"recent_event":["a society meeting","a neighbour''s party","a night on the stairs"],"most_defended_topic":["her loneliness"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Bombay English, formal, suspicious"]},"moves":{},"module_id":"psychosis","voice_key":"Bombay English, formal, suspicious@Mumbai (Bandra)","protective_factors":["independence","church community"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Look for hearing loss and isolation in late-onset psychosis","expected_mse":{"appearance":"Neat, old-fashioned dress, leans to hear","behaviour":"Guarded","speech":"Loud (hearing loss)","mood":"''Harassed''","affect":"Anxious, suspicious","thought_form":"Coherent","thought_content":"Persecutory delusion about neighbours","perception":"Auditory hallucinations of voices plotting, tactile ''gas''","cognition":"Intact cognition on screening","insight_judgement":"No insight"},"diagnosis":"Very late-onset schizophrenia-like psychosis (late-onset paraphrenia picture)","differentials":[{"dx":"Dementia with psychosis","why_not":"Cognition is intact on screening; follow up"},{"dx":"Delusional disorder","why_not":"Prominent hallucinations favour a schizophrenia-like psychosis"},{"dx":"Delirium","why_not":"Long, stable course without fluctuating attention"}],"debrief_rubric":["Noticed and adjusted for her hearing loss","Explored isolation and bereavement","Screened cognition","Asked about suicide and self-neglect","Recommended hearing assessment and social support alongside treatment"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Imtiaz, 24: three days after the riot', 'lib-cr-049', 'crisis', '{"case_id":"cr-049","slug":"lib-cr-049","title":"Imtiaz, 24: three days after the riot","difficulty":"crisis","traps":["under_diagnosis"],"traps_authored":["under_diagnosis"],"identity":{"name":"Imtiaz Ansari","age":24,"gender":"male","occupation":"auto-rickshaw driver","city":"Delhi (north-east)","family_structure":"lives with parents and wife","language_register":"Delhi Hindustani, frightened, rapid"},"presentation":"Three days after witnessing communal violence near his home, abrupt onset of fear, belief that men are coming to kill his family, hearing his name called, not sleeping; previously well.","chief_complaint_in_own_words":"They are coming. They are outside. They called my name from the roof. Lock the door, lock the door!","history":{"timeline":"Saw a man beaten near his lane four days ago; became suddenly confused, frightened and sleepless a day later.","prior_episodes":"none","substance_use":"none","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"three days","prior_contacts":["the local doctor","the imam"]},"cognitive_model":{"core_belief":"We are going to be killed tonight.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He saw a neighbour beaten with rods and could not help.","gate":"validation_given"},{"fact":"He hears his name called from the roof at night.","gate":"two_or_more_reflective_statements"},{"fact":"He has not slept for three nights and has stopped eating.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Nothing is wrong with me, there is danger outside."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; terror. Might act in self-defence against imagined attackers; family to remove sharp tools. Needs urgent care.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Stayed calm and offered safety first","Asked about the traumatic event gently","Assessed risk of harm to others from fear","Asked about suicide clearly","Arranged urgent treatment and follow-up"],"few_shot":[],"fixture_lines":["Did you hear? Someone called ''Imtiaz'' from the roof.","The door must be locked. Three locks. Ammi, did you lock it?","I saw what they did to Shakeel bhai. With rods. I just stood.","I can''t sleep. If I sleep they''ll come."],"variation":{"mood_today":["terrified","agitated","tearful"],"recent_event":["a loud noise outside","a police siren","news on TV"],"most_defended_topic":["guilt at not helping"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Delhi Hindustani, frightened, rapid"]},"moves":{},"module_id":"psychosis","voice_key":"Delhi Hindustani, frightened, rapid@Delhi (north-east)","protective_factors":["close family","previously well"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise a brief psychotic disorder after acute stress","expected_mse":{"appearance":"Dishevelled","behaviour":"Agitated, keeps looking at the door","speech":"Rapid, loud","mood":"''Terrified''","affect":"Fearful, labile","thought_form":"Disorganised at times","thought_content":"Persecutory delusion of imminent attack","perception":"Auditory hallucinations calling his name","cognition":"Partially disoriented to date","insight_judgement":"No insight"},"diagnosis":"Brief psychotic disorder with a marked stressor (acute and transient psychotic disorder)","differentials":[{"dx":"Acute stress disorder","why_not":"Delusions and hallucinations go beyond acute stress"},{"dx":"Schizophrenia","why_not":"Abrupt onset after a stressor, previously well; reassess if it lasts"},{"dx":"Delirium","why_not":"Check for medical cause and substance; orientation is partly impaired"}],"debrief_rubric":["Stayed calm and offered safety first","Asked about the traumatic event gently","Assessed risk of harm to others from fear","Asked about suicide clearly","Arranged urgent treatment and follow-up"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Kavita, 33: up, down, and the voices in between', 'lib-cr-050', 'guarded', '{"case_id":"cr-050","slug":"lib-cr-050","title":"Kavita, 33: up, down, and the voices in between","difficulty":"guarded","traps":["misattributed_diagnosis"],"traps_authored":["misattributed_diagnosis"],"identity":{"name":"Kavita Rawat","age":33,"gender":"female","occupation":"former primary school teacher","city":"Lucknow","family_structure":"married, one son; husband supportive but tired","language_register":"Hindi-English, variable, sometimes tangential"},"presentation":"Ten-year history of manic and depressive episodes with psychotic features; crucially, voices and persecutory ideas persisted for over two months during periods of normal mood.","chief_complaint_in_own_words":"I am in between now. Not up, not down. But the woman''s voice is still there. It never fully goes.","history":{"timeline":"First episode at 23 (manic with grandiosity), three depressive episodes, persistent voices between episodes for months at a time.","prior_episodes":"four admissions","substance_use":"none","medical":"hypothyroid on lithium","family":"mother with bipolar illness","treatment_history":"lithium and an antipsychotic","help_seeking_delay":"ten years","prior_contacts":["two psychiatrists"]},"cognitive_model":{"core_belief":"The voice will never let me be normal.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The woman''s voice tells her she is a bad mother even when her mood is normal.","gate":"validation_given"},{"fact":"She stopped teaching after an episode where she preached in class.","gate":"two_or_more_reflective_statements"},{"fact":"Last year her voices continued three months after her mood settled.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Doctors keep changing my label, so why bother."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: passive thoughts during low phases, one past overdose at 27; none now. Moderate long-term risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Took a detailed longitudinal history of mood and psychotic symptoms","Established psychosis outside mood episodes","Asked about suicide clearly and past attempts","Checked lithium monitoring and thyroid","Validated frustration about changing labels"],"few_shot":[],"fixture_lines":["When I am high I don''t sleep, I write poems on the walls. When I am low I don''t get up.","But the woman''s voice, it doesn''t care what my mood is. She stays.","She says I''m a bad mother. Even on good days.","I used to teach Class 3. I miss the chalk smell."],"variation":{"mood_today":["euthymic","tired","wistful"],"recent_event":["a lithium level test","son''s school meeting","husband''s tired look"],"most_defended_topic":["the past overdose"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Hindi-English, variable, sometimes tangential"]},"moves":{},"module_id":"psychosis","voice_key":"Hindi-English, variable, sometimes tangential@Lucknow","protective_factors":["husband","son"],"library":{"level":5,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry"],"objective":"Use the time course to separate schizoaffective disorder from mood disorder with psychosis","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Normal, slightly tangential","mood":"''In between''","affect":"Euthymic, mildly restricted","thought_form":"Mild tangentiality","thought_content":"Persecutory ideas about the voice''s intent","perception":"Second-person derogatory voice, persisting","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Schizoaffective disorder, bipolar type","differentials":[{"dx":"Bipolar disorder with psychotic features","why_not":"Psychotic symptoms persist for two weeks or more without mood symptoms, which bipolar disorder does not explain"},{"dx":"Schizophrenia","why_not":"Mood episodes are prominent for much of the illness"},{"dx":"Lithium toxicity or hypothyroidism","why_not":"Check levels; cognition and course do not suggest it"}],"debrief_rubric":["Took a detailed longitudinal history of mood and psychotic symptoms","Established psychosis outside mood episodes","Asked about suicide clearly and past attempts","Checked lithium monitoring and thyroid","Validated frustration about changing labels"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Arnav, 19: the weed was supposed to calm him', 'lib-cr-051', 'guarded', '{"case_id":"cr-051","slug":"lib-cr-051","title":"Arnav, 19: the weed was supposed to calm him","difficulty":"guarded","traps":["substance_induced"],"traps_authored":["substance_induced"],"identity":{"name":"Arnav Sharma","age":19,"gender":"male","occupation":"first-year design student","city":"Goa (Mapusa)","family_structure":"lives in a rented room; parents in Delhi","language_register":"Delhi slang English, laid-back then suspicious"},"presentation":"Heavy daily cannabis for a year, increased to several joints a day in exam month; two weeks of paranoia that friends are filming him, hearing whispers; started 3 days after a binge.","chief_complaint_in_own_words":"My friends are filming me for some prank channel. I hear them whispering in the walls. Bro, I''m not tripping, it''s real.","history":{"timeline":"Daily cannabis for a year; binge at a beach party two weeks ago; symptoms since; stopped using five days ago due to fear.","substance_use":"cannabis daily, recently heavy; occasional MDMA","medical":"none","family":"none known","treatment_history":"none","help_seeking_delay":"two weeks","prior_contacts":["a friend who brought him"]},"cognitive_model":{"core_belief":"Everyone is in on a joke against me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He smoked six or seven joints a day during exams.","gate":"two_or_more_reflective_statements"},{"fact":"His parents do not know he smokes and he fears being pulled out of college.","gate":"validation_given"},{"fact":"He took MDMA at the beach party too.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m not high now, so it''s not the weed."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; scared. Low risk to others.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Quantified cannabis and other drugs","Set a clear follow-up to reassess after abstinence","Explained the cannabis-psychosis link in plain words","Asked about suicide and safety","Discussed confidentiality and informing parents carefully"],"few_shot":[],"fixture_lines":["Bro, the walls whisper. Like ssss, Arnav, ssss.","They film me through the window. For some prank reel.","I stopped smoking five days ago. Because of all this.","Don''t call my parents. My dad will literally drag me back to Delhi."],"variation":{"mood_today":["suspicious","laid-back","scared"],"recent_event":["a friend posted a reel","exam results","a call from his mother"],"most_defended_topic":["parents finding out"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Delhi slang English, laid-back then suspicious"]},"moves":{},"module_id":"substance","voice_key":"Delhi slang English, laid-back then suspicious@Goa (Mapusa)","protective_factors":["friend who brought him","early help"],"library":{"level":4,"topic":"psychosis","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Assess cannabis-induced psychosis versus a primary psychotic disorder","expected_mse":{"appearance":"Unkempt, hoodie","behaviour":"Restless, looks at windows","speech":"Normal, slangy","mood":"''Freaked out''","affect":"Anxious, suspicious","thought_form":"Coherent","thought_content":"Persecutory ideas about being filmed","perception":"Whispering voices","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Cannabis-induced psychotic disorder (reassess after a month of abstinence)","differentials":[{"dx":"Schizophrenia or schizophreniform disorder","why_not":"If symptoms persist after a month without cannabis, think primary psychosis"},{"dx":"MDMA-related effects","why_not":"Short-lived; would not last two weeks"},{"dx":"Social anxiety or paranoid ideation","why_not":"Fixed belief and voices indicate psychosis"}],"debrief_rubric":["Quantified cannabis and other drugs","Set a clear follow-up to reassess after abstinence","Explained the cannabis-psychosis link in plain words","Asked about suicide and safety","Discussed confidentiality and informing parents carefully"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Thangjam, 28: the crystal and the shadows', 'lib-cr-052', 'crisis', '{"case_id":"cr-052","slug":"lib-cr-052","title":"Thangjam, 28: the crystal and the shadows","difficulty":"crisis","traps":["substance_induced"],"traps_authored":["substance_induced"],"identity":{"name":"Thangjam Ibomcha","age":28,"gender":"male","occupation":"unemployed, formerly a truck driver","city":"Imphal","family_structure":"lives with his mother","language_register":"Meitei-English, rapid, agitated"},"presentation":"Brought by family after three days without sleep, smoking methamphetamine tablets; believes armed men are hiding in the shadows; scratching his skin for ''insects''.","chief_complaint_in_own_words":"They are there, behind the tree, with guns. And bugs, look, crawling under my skin. Help me get them out!","history":{"timeline":"Using methamphetamine ''WY tablets'' for a year; binge for three days; no sleep.","substance_use":"methamphetamine, heroin earlier, alcohol","medical":"skin sores","family":"brother died of overdose","treatment_history":"one detox at a church centre","help_seeking_delay":"a year","prior_contacts":["church rehab"]},"cognitive_model":{"core_belief":"I am being hunted.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has not slept for three nights.","gate":"two_or_more_reflective_statements"},{"fact":"His brother died of an overdose and he feels guilty he introduced him to drugs.","gate":"validation_given"},{"fact":"He has used heroin in the past and shares needles sometimes.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I only used a little."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal intent now; high risk of agitation and harm to others from fear. Infection and blood-borne virus risk from needles. Needs safe, calm setting and medical care.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Kept a calm, low-stimulation approach","Assessed risk of harm to others","Asked about other drugs and injection use","Asked about suicide clearly","Linked to medical care and harm reduction"],"few_shot":[],"fixture_lines":["Behind the tree. See the shadow? He has a gun.","Bugs. Under the skin. I scratch and scratch.","No sleep. Three nights. I must watch.","My brother... I gave him his first one. Then he died."],"variation":{"mood_today":["agitated","frightened","guilty"],"recent_event":["a police jeep passed","his mother crying","no sleep again"],"most_defended_topic":["his brother''s death"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Meitei-English, rapid, agitated"]},"moves":{},"module_id":"substance","voice_key":"Meitei-English, rapid, agitated@Imphal","protective_factors":["mother","church community"],"library":{"level":4,"topic":"psychosis","module":"substance","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise methamphetamine-induced psychosis and agitation","expected_mse":{"appearance":"Thin, scratched forearms, dilated pupils","behaviour":"Agitated, hypervigilant","speech":"Rapid, pressured","mood":"''Scared''","affect":"Fearful, labile","thought_form":"Loosened at times","thought_content":"Persecutory delusion of being hunted","perception":"Visual shadows, tactile insects (formication)","cognition":"Oriented, attention poor","insight_judgement":"Poor"},"diagnosis":"Methamphetamine-induced psychotic disorder","differentials":[{"dx":"Schizophrenia","why_not":"Clear binge use and tactile hallucinations favour substance-induced; reassess after abstinence"},{"dx":"Delirium","why_not":"Check for infection, dehydration and other medical causes"},{"dx":"Alcohol withdrawal","why_not":"Ask about last drink; tremor and sweating would suggest it"}],"debrief_rubric":["Kept a calm, low-stimulation approach","Assessed risk of harm to others","Asked about other drugs and injection use","Asked about suicide clearly","Linked to medical care and harm reduction"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mohan, 45: the man who sits', 'lib-cr-053', 'cooperative', '{"case_id":"cr-053","slug":"lib-cr-053","title":"Mohan, 45: the man who sits","difficulty":"cooperative","traps":["diagnostic_overshadowing"],"traps_authored":["diagnostic_overshadowing"],"identity":{"name":"Mohan Lal","age":45,"gender":"male","occupation":"unemployed, formerly a clerk","city":"Jodhpur","family_structure":"lives with elderly parents","language_register":"Marwari Hindi, minimal words"},"presentation":"Twenty-year history of schizophrenia; positive symptoms controlled on medicine; now marked apathy, poverty of speech, social withdrawal and poor self-care; parents worry who will care for him.","chief_complaint_in_own_words":"Theek hai. Nothing. Sitting.","history":{"timeline":"Voices controlled for years; gradual decline in drive and self-care over the last decade.","prior_episodes":"two admissions in his twenties","substance_use":"bidis","medical":"weight gain","family":"none","treatment_history":"olanzapine for years","help_seeking_delay":"years","prior_contacts":["the district hospital"]},"cognitive_model":{"core_belief":"There is nothing to do.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He used to love flying kites at Makar Sankranti and stopped years ago.","gate":"two_or_more_reflective_statements"},{"fact":"He knows his parents are old and worries without saying it.","gate":"validation_given"},{"fact":"He bathes only when his mother insists.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Nothing is wrong."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk is from self-neglect and the future when parents can no longer care.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Adapted to minimal speech with patience and closed questions where needed","Separated negative symptoms from depression and side effects","Asked about suicide clearly","Explored the family''s future care concerns","Discussed rehabilitation and disability support"],"few_shot":[],"fixture_lines":["Theek hai.","Morning, tea. Then sitting. Then lunch. Then sitting.","Kites... earlier. Long time.","Mummy is old. Who will make the rotis later?"],"variation":{"mood_today":["flat","quiet"],"recent_event":["father''s illness","Makar Sankranti coming","a cousin''s visit"],"most_defended_topic":["fear for the future"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Marwari Hindi, minimal words"]},"moves":{},"module_id":"psychosis","voice_key":"Marwari Hindi, minimal words@Jodhpur","protective_factors":["devoted parents"],"library":{"level":3,"topic":"psychosis","module":"psychosis","exams":["mcp-entrance","ma-semester","md-psychiatry"],"objective":"Recognise negative symptoms and their impact","expected_mse":{"appearance":"Unkempt, overweight","behaviour":"Psychomotor poverty, little spontaneous movement","speech":"Poverty of speech","mood":"''Theek''","affect":"Blunted","thought_form":"Poverty of thought","thought_content":"No active delusions","perception":"No current hallucinations","cognition":"Oriented; slowed","insight_judgement":"Limited insight"},"diagnosis":"Schizophrenia with predominant negative symptoms","differentials":[{"dx":"Depression","why_not":"No sadness or guilt; blunting rather than low mood, but screen"},{"dx":"Antipsychotic-induced akinesia or sedation","why_not":"Check dose and extrapyramidal signs"},{"dx":"Hypothyroidism","why_not":"Low thyroid can cause slowness and apathy, so check bloods, though a gradual decline over years of illness fits negative symptoms"}],"debrief_rubric":["Adapted to minimal speech with patience and closed questions where needed","Separated negative symptoms from depression and side effects","Asked about suicide clearly","Explored the family''s future care concerns","Discussed rehabilitation and disability support"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sneha, 30: the actor who loves her', 'lib-cr-054', 'guarded', '{"case_id":"cr-054","slug":"lib-cr-054","title":"Sneha, 30: the actor who loves her","difficulty":"guarded","traps":["over_diagnosis"],"traps_authored":["over_diagnosis"],"identity":{"name":"Sneha Kulkarni","age":30,"gender":"female","occupation":"bank clerk","city":"Pune","family_structure":"unmarried, lives with parents","language_register":"articulate Marathi-English, dreamy, certain"},"presentation":"Eight months of conviction that a famous film actor is secretly in love with her and sends messages through his films and social media; has travelled to his house in Mumbai twice.","chief_complaint_in_own_words":"He loves me. He tells me in his films, the way he looks at the camera. My parents don''t understand. I came so you can explain it to them.","history":{"timeline":"Belief began after she commented on his post and ''he liked it''; since then messages in every film; two trips to his house.","substance_use":"none","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"eight months","prior_contacts":["the actor''s security guards"]},"cognitive_model":{"core_belief":"I am chosen.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She believes the blue shirt he wore in a song was a signal to her.","gate":"validation_given"},{"fact":"She stood outside his house for two nights and was moved by security.","gate":"two_or_more_reflective_statements"},{"fact":"She has written 300 letters and spent her savings on travel.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Love is not a mental problem."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk of harassment, legal trouble and, if rejected, distress or anger. Moderate risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored the belief without ridicule","Asked about actions taken (travel, letters, waiting)","Assessed risk to self and others and legal risk","Asked about suicide clearly","Engaged parents with her consent"],"few_shot":[],"fixture_lines":["The blue shirt in that song. Blue is my colour. He knew.","He can''t say it openly. His family, the press. So he signals.","Two nights I waited outside. The guards were rude, but that''s their job.","Three hundred letters. He reads them all. I can tell."],"variation":{"mood_today":["dreamy","certain","irritable when doubted"],"recent_event":["his new film release","a security warning letter","parents hid her phone"],"most_defended_topic":["her savings spent"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["articulate Marathi-English, dreamy, certain"]},"moves":{},"module_id":"psychosis","voice_key":"articulate Marathi-English, dreamy, certain@Pune","protective_factors":["parents","steady job"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise erotomanic delusions and stalking risk","expected_mse":{"appearance":"Well dressed","behaviour":"Calm, smiling","speech":"Fluent","mood":"''Happy, in love''","affect":"Elated at times, incongruent","thought_form":"Coherent","thought_content":"Erotomanic delusion","perception":"No hallucinations","cognition":"Intact","insight_judgement":"No insight"},"diagnosis":"Delusional disorder, erotomanic type","differentials":[{"dx":"Bipolar disorder (manic episode)","why_not":"No sustained elation with reduced sleep, pressured speech or overactivity"},{"dx":"Schizophrenia","why_not":"No hallucinations or thought disorder; functioning preserved"},{"dx":"Parasocial attachment (fandom)","why_not":"She is fixed in the belief that he loves her and acts on it despite evidence"}],"debrief_rubric":["Explored the belief without ridicule","Asked about actions taken (travel, letters, waiting)","Assessed risk to self and others and legal risk","Asked about suicide clearly","Engaged parents with her consent"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Prakash, 35: three medicines tried, voices unchanged', 'lib-cr-055', 'guarded', '{"case_id":"cr-055","slug":"lib-cr-055","title":"Prakash, 35: three medicines tried, voices unchanged","difficulty":"guarded","traps":["treatment_mismatch"],"traps_authored":["treatment_mismatch"],"identity":{"name":"Prakash Murugan","age":35,"gender":"male","occupation":"unemployed, formerly a lab technician","city":"Madurai","family_structure":"lives with parents and sister","language_register":"Tamil, guarded, tired"},"presentation":"Schizophrenia for twelve years; persistent voices and persecutory ideas despite three adequate antipsychotic trials, adherence confirmed with a long-acting injection.","chief_complaint_in_own_words":"The voices are still there. Same as always. The injection makes me stiff, that''s all.","history":{"timeline":"Twelve years of illness; olanzapine, risperidone and haloperidol long-acting injection, each at adequate dose and duration; persistent symptoms.","prior_episodes":"five admissions","substance_use":"smokes 15 cigarettes a day","medical":"constipation","family":"uncle with schizophrenia","treatment_history":"three antipsychotics, adequate trials","help_seeking_delay":"years","prior_contacts":["government hospital","a private psychiatrist"]},"cognitive_model":{"core_belief":"This is how my life will always be.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The voices tell him not to trust his sister and he avoids her.","gate":"validation_given"},{"fact":"He wants to work again as a lab technician.","gate":"two_or_more_reflective_statements"},{"fact":"He smokes 15 cigarettes a day and drinks a lot of coffee.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Nothing works, so why try another."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: occasional thoughts that life is not worth living, no plan; one past attempt at 25. Moderate risk; clozapine may also reduce suicidality.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Confirmed adequacy and adherence of past trials","Asked about suicide clearly, including the past attempt","Asked about smoking and its relevance to medicine levels","Explained clozapine benefits and monitoring in plain words","Linked to his goal of returning to work"],"few_shot":[],"fixture_lines":["Twelve years. Always the same two voices.","The injection keeps me stiff. Like a wooden doll.","I was a good lab technician. I could do a blood smear in my sleep.","The voices say Akka is plotting. I know she loves me. But I keep away."],"variation":{"mood_today":["tired","guarded","resigned"],"recent_event":["sister''s wedding talk","a new job advertisement","a stiff day"],"most_defended_topic":["the past attempt"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Tamil, guarded, tired"]},"moves":{},"module_id":"antipsychotics","voice_key":"Tamil, guarded, tired@Madurai","protective_factors":["family","wish to work"],"library":{"level":5,"topic":"psychosis","module":"antipsychotics","exams":["md-psychiatry"],"objective":"Identify treatment-resistant schizophrenia and the case for clozapine","expected_mse":{"appearance":"Neat, stiff gait","behaviour":"Reduced arm swing, slight tremor","speech":"Slow, sparse","mood":"''Tired''","affect":"Restricted","thought_form":"Coherent","thought_content":"Persecutory ideas about sister","perception":"Persistent second-person voices","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Treatment-resistant schizophrenia","differentials":[{"dx":"Pseudo-resistance from non-adherence","why_not":"Long-acting injection confirms adherence"},{"dx":"Substance use","why_not":"No drugs; heavy smoking alters some antipsychotic levels, relevant to clozapine dosing"},{"dx":"Comorbid depression","why_not":"Low mood is common in long illness and he has a past attempt, so screen for it carefully"}],"debrief_rubric":["Confirmed adequacy and adherence of past trials","Asked about suicide clearly, including the past attempt","Asked about smoking and its relevance to medicine levels","Explained clozapine benefits and monitoring in plain words","Linked to his goal of returning to work"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Joseph, 41: voices after the fits', 'lib-cr-056', 'guarded', '{"case_id":"cr-056","slug":"lib-cr-056","title":"Mr Joseph, 41: voices after the fits","difficulty":"guarded","traps":["medical_mimic","cultural_idiom"],"traps_authored":["medical_mimic","cultural_idiom"],"identity":{"name":"Biju Joseph","age":41,"gender":"male","occupation":"church sacristan","city":"Kottayam","family_structure":"married, two daughters","language_register":"Malayalam, devout, puzzled"},"presentation":"Temporal lobe epilepsy since childhood, poorly controlled; after a cluster of seizures three days ago, intense religious experiences, belief he is a prophet, voices of angels, sleeplessness.","chief_complaint_in_own_words":"After the fits, God spoke to me. Clearly. I must tell the bishop. My wife thinks I''m unwell.","history":{"timeline":"Cluster of three seizures four days ago; after a lucid day, psychotic symptoms began; similar but shorter episode last year.","prior_episodes":"a shorter episode a year ago","substance_use":"none","medical":"temporal lobe epilepsy, missed doses recently","family":"none","treatment_history":"carbamazepine, irregular","help_seeking_delay":"days","prior_contacts":["neurologist"]},"cognitive_model":{"core_belief":"I have been chosen to warn people.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He missed his epilepsy tablets during a church festival week.","gate":"two_or_more_reflective_statements"},{"fact":"Last year a similar thing happened and passed in a week.","gate":"validation_given"},{"fact":"He has stood outside the bishop''s house since dawn.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["This is spiritual, not medical."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts; risk from seizures and sleeplessness. Low risk to others.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about the timing of psychosis after seizures","Asked about anticonvulsant adherence","Liaised with neurology","Respected religious meaning while assessing risk","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["After the fits, there was one quiet day. Then the light came and the angels spoke.","I must warn the bishop. The angels said so.","During the feast week I forgot my tablets. Very busy week.","Last year also something like this. It passed. My wife remembers better."],"variation":{"mood_today":["exalted","puzzled","devout"],"recent_event":["another seizure aura","the bishop''s secretary refused him","wife''s tears"],"most_defended_topic":["missed tablets"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Malayalam, devout, puzzled"]},"moves":{},"module_id":"neurocognitive","voice_key":"Malayalam, devout, puzzled@Kottayam","protective_factors":["wife","faith community"],"library":{"level":5,"topic":"psychosis","module":"neurocognitive","exams":["md-psychiatry"],"objective":"Recognise psychosis linked to epilepsy","expected_mse":{"appearance":"Neat, rosary in hand","behaviour":"Restless","speech":"Fast, religious themes","mood":"''Blessed''","affect":"Elated, labile","thought_form":"Mildly tangential","thought_content":"Religious grandiose delusion","perception":"Auditory hallucinations of angels","cognition":"Oriented, attention variable","insight_judgement":"Poor insight"},"diagnosis":"Postictal psychosis (temporal lobe epilepsy)","differentials":[{"dx":"Bipolar disorder (manic episode)","why_not":"Tied to a seizure cluster with a lucid interval and a past similar episode"},{"dx":"Schizophrenia","why_not":"Schizophrenia runs a continuous course; his psychosis comes in short episodes after seizure clusters"},{"dx":"Normal religious experience","why_not":"Conviction, voices and sleeplessness with impaired functioning point to psychosis; respect his faith while treating"}],"debrief_rubric":["Asked about the timing of psychosis after seizures","Asked about anticonvulsant adherence","Liaised with neurology","Respected religious meaning while assessing risk","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Tanya, 17: the world looks like a film set', 'lib-cr-057', 'cooperative', '{"case_id":"cr-057","slug":"lib-cr-057","title":"Tanya, 17: the world looks like a film set","difficulty":"cooperative","traps":["over_diagnosis","under_diagnosis"],"traps_authored":["over_diagnosis","under_diagnosis"],"identity":{"name":"Tanya Saxena","age":17,"gender":"female","occupation":"Class 12 student","city":"Bhopal","family_structure":"lives with parents and grandmother","language_register":"fluent English, articulate, frightened"},"presentation":"Six months of falling grades, withdrawal, odd feelings that things are ''staged'', occasional whispers when falling asleep which she knows are probably not real, and suspiciousness she can question.","chief_complaint_in_own_words":"Sometimes everything looks fake, like a film set. And I hear my name whispered when I''m falling asleep. I know it''s probably my brain. But it scares me.","history":{"timeline":"Six months; brief, attenuated experiences; insight largely kept; grades fell from 92 to 70 percent.","substance_use":"none","medical":"none","family":"paternal uncle with schizophrenia","treatment_history":"none","help_seeking_delay":"six months","prior_contacts":["school counsellor"]},"cognitive_model":{"core_belief":"I''m going mad like my uncle.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She sometimes thinks classmates are talking about her but can tell herself it''s unlikely.","gate":"two_or_more_reflective_statements"},{"fact":"She is terrified of becoming like her uncle, who stays in a room at home.","gate":"validation_given"},{"fact":"She has stopped going to her dance class and friends'' outings.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Maybe it''s just exam stress."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: occasional low mood, no suicidal thoughts. Low risk now; monitor.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked gently about unusual experiences and insight","Took a family history","Assessed functional decline","Asked about suicide clearly","Explained monitoring and support without frightening her"],"few_shot":[],"fixture_lines":["It''s like the world is a set and someone forgot to switch on the real lights.","Falling asleep I hear ''Tanya'', soft. I know it''s probably nothing.","Sometimes I think the girls are whispering about me. Then I think, why would they?","My chacha stays in one room at home. I''m scared that''s me in ten years."],"variation":{"mood_today":["anxious","articulate","frightened"],"recent_event":["a mock exam","a friend''s party she skipped","uncle shouting at home"],"most_defended_topic":["fear about her uncle"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fluent English, articulate, frightened"]},"moves":{},"module_id":"psychosis","voice_key":"fluent English, articulate, frightened@Bhopal","protective_factors":["insight","engaged family"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise a clinical high-risk state for psychosis","expected_mse":{"appearance":"Neat, school uniform","behaviour":"Anxious, appropriate","speech":"Normal","mood":"''Scared''","affect":"Anxious","thought_form":"Coherent","thought_content":"Attenuated ideas of reference, insight kept","perception":"Brief hypnagogic whispers, recognised as unreal","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Clinical high-risk state (attenuated psychotic symptoms)","differentials":[{"dx":"Schizophrenia","why_not":"Experiences are attenuated with insight kept; not full psychosis"},{"dx":"Depression or anxiety","why_not":"Common in high-risk states; screen and treat"},{"dx":"Hypnagogic experiences","why_not":"These alone are normal; the combination with decline and family history is the concern"}],"debrief_rubric":["Asked gently about unusual experiences and insight","Took a family history","Assessed functional decline","Asked about suicide clearly","Explained monitoring and support without frightening her"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ravi, 29: strange but steady', 'lib-cr-058', 'cooperative', '{"case_id":"cr-058","slug":"lib-cr-058","title":"Ravi, 29: strange but steady","difficulty":"cooperative","traps":["over_diagnosis"],"traps_authored":["over_diagnosis"],"identity":{"name":"Ravi Shankar","age":29,"gender":"male","occupation":"works in a computer repair shop","city":"Patna","family_structure":"lives alone, rarely visits family","language_register":"odd, elaborate English, unusual words"},"presentation":"Lifelong odd beliefs (telepathy, energy fields), eccentric dress, few friends, social anxiety that does not lessen with familiarity; no frank delusions or hallucinations; stable.","chief_complaint_in_own_words":"My energy field gets disturbed in crowds. I came because my brother says I''m ''weird''. I prefer ''tuned differently''.","history":{"timeline":"Since adolescence; no decline; works steadily.","substance_use":"none","medical":"none","family":"cousin with schizophrenia","treatment_history":"none","help_seeking_delay":"lifelong","prior_contacts":["brother"]},"cognitive_model":{"core_belief":"I sense things others cannot.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He believes he can sometimes sense what customers will say before they speak.","gate":"two_or_more_reflective_statements"},{"fact":"He feels lonely but finds people uncomfortable.","gate":"validation_given"},{"fact":"He wears a copper bracelet to ''stabilise his field''.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Being different isn''t an illness."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Explored beliefs with respect","Checked for full psychotic symptoms","Took a developmental and family history","Asked about suicide clearly","Avoided labelling difference as illness unnecessarily"],"few_shot":[],"fixture_lines":["Crowds scramble my field. Like static on a radio.","I sometimes know what a customer will say. Not always. Often enough.","The bracelet is copper. It grounds the field. People laugh.","I''d like a friend. But people are... loud. In every sense."],"variation":{"mood_today":["odd","calm","wistful"],"recent_event":["brother''s wedding","a crowded festival","a customer complained"],"most_defended_topic":["loneliness"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["odd, elaborate English, unusual words"]},"moves":{},"module_id":"personality","voice_key":"odd, elaborate English, unusual words@Patna","protective_factors":["steady job","brother"],"library":{"level":4,"topic":"psychosis","module":"personality","exams":["md-psychiatry","ugc-net","mcp-entrance"],"objective":"Tell a schizotypal personality apart from a psychotic disorder","expected_mse":{"appearance":"Eccentric clothes, copper bracelet","behaviour":"Stiff, odd mannerisms","speech":"Elaborate, metaphorical, odd words","mood":"''Fine''","affect":"Constricted","thought_form":"Vague, over-elaborate","thought_content":"Magical thinking, ideas of reference without fixed conviction","perception":"Unusual bodily sensations, no hallucinations","cognition":"Intact","insight_judgement":"Partial"},"diagnosis":"Schizotypal personality disorder","differentials":[{"dx":"Schizophrenia","why_not":"No sustained delusions or hallucinations; stable lifelong pattern"},{"dx":"Autism spectrum condition","why_not":"Magical thinking and perceptual oddities favour schizotypal; screen developmental history"},{"dx":"Schizoid personality","why_not":"He has eccentric beliefs and wants connection"}],"debrief_rubric":["Explored beliefs with respect","Checked for full psychotic symptoms","Took a developmental and family history","Asked about suicide clearly","Avoided labelling difference as illness unnecessarily"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Kamble, 38: the voice says ''do it''', 'lib-cr-059', 'crisis', '{"case_id":"cr-059","slug":"lib-cr-059","title":"Mr Kamble, 38: the voice says ''do it''","difficulty":"crisis","traps":["late_risk_reveal"],"traps_authored":["late_risk_reveal"],"identity":{"name":"Sachin Kamble","age":38,"gender":"male","occupation":"security guard","city":"Nagpur","family_structure":"lives with wife and two children","language_register":"Marathi-Hindi, tense, whispering"},"presentation":"Known schizophrenia; stopped medicine; voices now command him to ''punish'' his supervisor who ''is poisoning the canteen tea''; carries his security baton home.","chief_complaint_in_own_words":"The voice says do it. Do it today. I''m fighting it. That''s why I came.","history":{"timeline":"Stopped tablets six weeks ago; voices escalated to commands in the past week.","prior_episodes":"two admissions","substance_use":"alcohol on weekends","medical":"none","family":"none","treatment_history":"haloperidol, stopped","help_seeking_delay":"weeks","prior_contacts":["wife"]},"cognitive_model":{"core_belief":"The supervisor is poisoning us and I must stop him.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The voice tells him to punish his supervisor today.","gate":"validation_given"},{"fact":"He believes the supervisor puts poison in the canteen tea.","gate":"two_or_more_reflective_statements"},{"fact":"He has kept the baton at home since last week.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I can control it."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. High risk to others: command hallucinations naming a person, belief of being poisoned, access to a weapon, stopped medicine, alcohol. Needs urgent admission and duty-to-protect steps.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":["MHA 2017 emergency treatment","duty to protect"]},"style_refs":[],"rubric_targets":["Asked directly about the content of commands and the target","Asked about weapons and intent","Recognised his help-seeking as a strength","Asked about suicide clearly","Arranged urgent admission and considered duty to protect"],"few_shot":[],"fixture_lines":["The voice says, ''Do it, do it today''. All night it said.","The tea in the canteen, he puts something. I''ve seen his hand.","I came because I''m fighting it. I don''t want to.","I have two children. I don''t want to go to jail."],"variation":{"mood_today":["tense","frightened","whispering"],"recent_event":["supervisor shouted at him","canteen tea tasted odd","wife hid the baton"],"most_defended_topic":["the baton at home"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Marathi-Hindi, tense, whispering"]},"moves":{},"module_id":"psychosis","voice_key":"Marathi-Hindi, tense, whispering@Nagpur","protective_factors":["his insight that he needs help","children"],"library":{"level":5,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Assess command hallucinations and risk to others","expected_mse":{"appearance":"Uniform, unshaven","behaviour":"Tense, hypervigilant","speech":"Low, whispering","mood":"''Scared of myself''","affect":"Anxious, tense","thought_form":"Coherent","thought_content":"Persecutory delusion of poisoning naming the supervisor","perception":"Command hallucinations to harm","cognition":"Intact","insight_judgement":"Partial: knows he needs help"},"diagnosis":"Schizophrenia, relapse with command hallucinations and high violence risk","differentials":[{"dx":"Substance-induced psychosis","why_not":"Known schizophrenia and stopped medicine; alcohol may worsen"},{"dx":"Delusional disorder","why_not":"Delusional disorder has no prominent hallucinations; his commanding voices point elsewhere"},{"dx":"Mood disorder with psychosis","why_not":"There is no elevated or depressed mood driving the beliefs, so a mood disorder with psychosis does not fit"}],"debrief_rubric":["Asked directly about the content of commands and the target","Asked about weapons and intent","Recognised his help-seeking as a strength","Asked about suicide clearly","Arranged urgent admission and considered duty to protect"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Amaka, 26: Manchester, and the prayers', 'lib-cr-060', 'guarded', '{"case_id":"cr-060","slug":"lib-cr-060","title":"Amaka, 26: Manchester, and the prayers","difficulty":"guarded","traps":["cultural_idiom","over_diagnosis"],"traps_authored":["cultural_idiom","over_diagnosis"],"identity":{"name":"Amaka Okafor","age":26,"gender":"female","occupation":"postgraduate nursing student","city":"Manchester","family_structure":"Nigerian, lives in a shared flat; family in Enugu","language_register":"Nigerian English, warm, devout"},"presentation":"Flatmates worried: three weeks of believing she is being spiritually attacked by a coursemate who ''steals her thoughts'', praying through the night, not sleeping, missing placements. Church friends think it is spiritual.","chief_complaint_in_own_words":"My church says it''s a spiritual battle. My flatmates say see a doctor. I came to prove I''m fine.","history":{"timeline":"Three weeks; started after failing a placement assessment; prayer has increased; sleeping two hours.","substance_use":"none","medical":"none","family":"none known","treatment_history":"prayer deliverance","help_seeking_delay":"three weeks","prior_contacts":["pastor","flatmates"]},"cognitive_model":{"core_belief":"Someone is stealing my mind.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She believes a coursemate takes her thoughts out of her head so she cannot answer exams.","gate":"two_or_more_reflective_statements"},{"fact":"Her pastor told her prayer, not medicine, will help.","gate":"validation_given"},{"fact":"She hears a voice mocking her prayers at night.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["This is spiritual."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk from sleep loss and missing placements. Low risk to others.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about the beliefs of her community to judge what is shared","Explored first-rank symptoms carefully","Asked about suicide clearly","Worked with her faith rather than against it","Planned support including her flatmates and, with consent, her pastor"],"few_shot":[],"fixture_lines":["When I sit in the exam, my thoughts are pulled out. Just gone. She does it.","I pray at night. Two, three in the morning. It''s a battle.","At night a voice laughs when I pray. Mocking.","Back home my aunty would understand. Here, they say doctor."],"variation":{"mood_today":["warm","guarded","tired"],"recent_event":["a placement review","pastor''s message","a call from her mother"],"most_defended_topic":["the mocking voice"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Nigerian English, warm, devout"]},"moves":{},"module_id":"psychosis","voice_key":"Nigerian English, warm, devout@Manchester","protective_factors":["caring flatmates","faith"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Assess psychosis across cultures without over- or under-reading belief","expected_mse":{"appearance":"Neat, tired","behaviour":"Calm, watchful","speech":"Normal","mood":"''Under attack''","affect":"Anxious","thought_form":"Coherent","thought_content":"Delusion of thought withdrawal, persecutory","perception":"Auditory hallucination mocking her","cognition":"Intact","insight_judgement":"Poor insight"},"diagnosis":"Acute psychotic episode (schizophreniform picture so far)","differentials":[{"dx":"Culturally congruent spiritual belief","why_not":"Belief in spiritual attack can be normative; but thought withdrawal, voices, sleep loss and decline are beyond the shared belief of her community"},{"dx":"Brief psychotic disorder","why_not":"Three weeks so far; course will clarify"},{"dx":"Bipolar disorder (manic episode)","why_not":"Reduced sleep but no elation or overactivity"}],"debrief_rubric":["Asked about the beliefs of her community to judge what is shared","Explored first-rank symptoms carefully","Asked about suicide clearly","Worked with her faith rather than against it","Planned support including her flatmates and, with consent, her pastor"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Ali, 63: worms under the skin', 'lib-cr-061', 'resistant', '{"case_id":"cr-061","slug":"lib-cr-061","title":"Mr Ali, 63: worms under the skin","difficulty":"resistant","traps":["medical_mimic"],"traps_authored":["medical_mimic"],"identity":{"name":"Yusuf Ali","age":63,"gender":"male","occupation":"retired government driver","city":"Hyderabad (Old City)","family_structure":"widower, lives with his son","language_register":"Dakhni Urdu, insistent"},"presentation":"Ten months of conviction that worms live under his skin; brings ''specimens'' in a matchbox; scratches and has sores; seen many dermatologists.","chief_complaint_in_own_words":"Look, look. In the box. These came out of my arm. The skin doctors are useless.","history":{"timeline":"Started after his wife''s death; bathes with kerosene and harsh soaps; sores on arms.","substance_use":"none","medical":"diabetes, skin sores","family":"none","treatment_history":"anti-parasite tablets, creams","help_seeking_delay":"ten months","prior_contacts":["four dermatologists","a hakim"]},"cognitive_model":{"core_belief":"My body is being eaten.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has used kerosene on his skin to kill the worms.","gate":"two_or_more_reflective_statements"},{"fact":"Since his wife died, he sleeps alone and checks his skin at night.","gate":"validation_given"},{"fact":"He has stopped attending mosque because people stare at his sores.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Send me to a better skin doctor."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk from self-injury with chemicals and infection.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Examined the ''specimen'' respectfully without colluding","Asked about harm from treatments like kerosene","Screened for medical causes of itching","Asked about bereavement and suicide clearly","Worked jointly with dermatology"],"few_shot":[],"fixture_lines":["This box. Look properly. Small, black, they move at night.","Kerosene, Dettol, everything. They come back.","Four skin doctors. All say ''nothing''. Then what is in my box?","Since Begum went, I check every night. Arms, legs."],"variation":{"mood_today":["insistent","irritable","lonely"],"recent_event":["a new sore","dermatologist''s report","son''s scolding"],"most_defended_topic":["using kerosene"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["Dakhni Urdu, insistent"]},"moves":{},"module_id":"psychosis","voice_key":"Dakhni Urdu, insistent@Hyderabad (Old City)","protective_factors":["son","mosque community"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry"],"objective":"Recognise delusional infestation and the need for medical screening","expected_mse":{"appearance":"Sores on forearms, matchbox in hand","behaviour":"Scratches repeatedly","speech":"Insistent","mood":"''Irritated''","affect":"Anxious","thought_form":"Coherent","thought_content":"Fixed delusion of infestation","perception":"Tactile sensations of crawling","cognition":"Intact on screening","insight_judgement":"No insight"},"diagnosis":"Delusional disorder, somatic type (delusional infestation)","differentials":[{"dx":"Real infestation (scabies)","why_not":"Repeated dermatology checks and specimens are negative; still examine"},{"dx":"Medical causes of itch","why_not":"Diabetes, kidney and thyroid disease, B12 deficiency, drugs: screen"},{"dx":"Dementia with psychosis","why_not":"Cognition intact on screening; follow up"}],"debrief_rubric":["Examined the ''specimen'' respectfully without colluding","Asked about harm from treatments like kerosene","Screened for medical causes of itching","Asked about bereavement and suicide clearly","Worked jointly with dermatology"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Neeraj, 31: he wants to stop the injection', 'lib-cr-062', 'cooperative', '{"case_id":"cr-062","slug":"lib-cr-062","title":"Neeraj, 31: he wants to stop the injection","difficulty":"cooperative","traps":["iatrogenic"],"traps_authored":["iatrogenic"],"identity":{"name":"Neeraj Tiwari","age":31,"gender":"male","occupation":"cashier at a supermarket","city":"Allahabad (Prayagraj)","family_structure":"married, one daughter","language_register":"Hindi-English, thoughtful"},"presentation":"Well for two years after a first psychotic episode on a monthly injection; wants to stop because of sexual side effects and stigma; insight partial.","chief_complaint_in_own_words":"I''ve been fine for two years. I want to stop the injection. I want to feel normal with my wife again.","history":{"timeline":"First episode at 28; two years stable; side effects of reduced libido and weight.","prior_episodes":"one episode","substance_use":"none","medical":"raised prolactin","family":"none","treatment_history":"monthly injection","help_seeking_delay":"none","prior_contacts":["psychiatrist"]},"cognitive_model":{"core_belief":"If I take it, I''m still a patient.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He has erectile and libido problems and is ashamed.","gate":"validation_given"},{"fact":"He fears his daughter will learn he ''takes mental injections''.","gate":"two_or_more_reflective_statements"},{"fact":"He sometimes still hears a faint whisper when stressed.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m cured, so why continue."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Relapse risk if stopped abruptly.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about sexual side effects openly","Discussed relapse risk honestly","Explored options: switching to a prolactin-sparing medicine, gradual taper with monitoring","Respected his autonomy and agreed a plan together","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["Two years fine. Job, family, everything.","My wife and I... it''s not the same. Since the injection.","My daughter is five. One day she''ll ask, ''Papa, what is this injection?''","Sometimes, if I''m very tired, a small whisper. Just once in a while."],"variation":{"mood_today":["thoughtful","hopeful","ashamed"],"recent_event":["an anniversary","a stressful week","injection due"],"most_defended_topic":["sexual side effects"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Hindi-English, thoughtful"]},"moves":{},"module_id":"antipsychotics","voice_key":"Hindi-English, thoughtful@Allahabad (Prayagraj)","protective_factors":["stable job","supportive wife"],"library":{"level":3,"topic":"psychosis","module":"antipsychotics","exams":["mcp-entrance","md-psychiatry","ma-semester"],"objective":"Hold a shared-decision conversation about stopping antipsychotics","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Normal","mood":"''Good''","affect":"Euthymic","thought_form":"Coherent","thought_content":"No delusions","perception":"Occasional faint whisper under stress","cognition":"Intact","insight_judgement":"Partial insight"},"diagnosis":"Schizophrenia (first episode) in remission on maintenance treatment","differentials":[{"dx":"Full remission without risk","why_not":"Residual whisper under stress suggests vulnerability"},{"dx":"Sexual dysfunction from another cause","why_not":"Raised prolactin links it to the medicine"},{"dx":"Depression","why_not":"Low mood is common in recovery from a first episode and can drive wishes to stop treatment, so ask about it directly"}],"debrief_rubric":["Asked about sexual side effects openly","Discussed relapse risk honestly","Explored options: switching to a prolactin-sparing medicine, gradual taper with monitoring","Respected his autonomy and agreed a plan together","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Gurmeet, 46: the Guru speaks to him alone', 'lib-cr-063', 'guarded', '{"case_id":"cr-063","slug":"lib-cr-063","title":"Gurmeet, 46: the Guru speaks to him alone","difficulty":"guarded","traps":["cultural_idiom","medical_mimic","substance_induced"],"traps_authored":["cultural_idiom","medical_mimic","substance_induced"],"identity":{"name":"Gurmeet Singh","age":46,"gender":"male","occupation":"truck owner and driver","city":"Bathinda","family_structure":"married, three children","language_register":"Punjabi, devout, intense"},"presentation":"Three months of belief that the Guru speaks to him alone and has chosen him to cleanse the village; has given away savings, stopped working, argues with the granthi; family alarmed.","chief_complaint_in_own_words":"Waheguru speaks to me. Only to me. The granthi is jealous. My family doesn''t understand.","history":{"timeline":"Three months; preceded by a road accident and loss of his truck''s permit; sleeping less.","substance_use":"afeem earlier, says stopped","medical":"head injury in the accident, no scan","family":"none","treatment_history":"none","help_seeking_delay":"three months","prior_contacts":["the gurdwara committee"]},"cognitive_model":{"core_belief":"I have been chosen.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He gave his savings to strangers ''as the Guru instructed''.","gate":"two_or_more_reflective_statements"},{"fact":"He hit his head in the accident and was unconscious briefly.","gate":"validation_given"},{"fact":"He used opium earlier and may still use it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Faith is not madness."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk from financial ruin and conflict with the community.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked how his own community sees his experience","Asked about head injury and substance use","Assessed financial and safety risks","Asked about suicide clearly","Respected faith while recommending investigation and treatment"],"few_shot":[],"fixture_lines":["Waheguru speaks to me at amrit vela. Clear like you speaking now.","The granthi says I''m misguided. Jealousy.","I gave the money. The Guru said give. So I gave.","After the accident I was in the field. Then I woke with the voice."],"variation":{"mood_today":["intense","elated","suspicious"],"recent_event":["argument at the gurdwara","wife took the bank card","truck sold"],"most_defended_topic":["opium use"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Punjabi, devout, intense"]},"moves":{},"module_id":"psychosis","voice_key":"Punjabi, devout, intense@Bathinda","protective_factors":["family","faith community"],"library":{"level":4,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Tell religious experience apart from a religious delusion","expected_mse":{"appearance":"Turban, neat","behaviour":"Restless","speech":"Rapid at times","mood":"''Blessed''","affect":"Elated, irritable","thought_form":"Mildly tangential","thought_content":"Grandiose religious delusion","perception":"Auditory hallucinations of the Guru","cognition":"Intact","insight_judgement":"No insight"},"diagnosis":"Psychotic disorder with religious grandiose delusions (rule out organic cause after head injury and substance use)","differentials":[{"dx":"Normal devotion","why_not":"His own faith community does not share the belief; functional decline and giving away savings point to illness"},{"dx":"Bipolar disorder (manic episode)","why_not":"Reduced sleep and elation; examine mood closely"},{"dx":"Organic psychosis after head injury","why_not":"Needs neurological examination and imaging"}],"debrief_rubric":["Asked how his own community sees his experience","Asked about head injury and substance use","Assessed financial and safety risks","Asked about suicide clearly","Respected faith while recommending investigation and treatment"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Dr Banerjee, 34: the colleague no one challenges', 'lib-cr-064', 'resistant', '{"case_id":"cr-064","slug":"lib-cr-064","title":"Dr Banerjee, 34: the colleague no one challenges","difficulty":"resistant","traps":["substance_induced"],"traps_authored":["substance_induced"],"identity":{"name":"Arindam Banerjee","age":34,"gender":"male","occupation":"junior resident in surgery","city":"Kolkata","family_structure":"lives alone in hospital quarters","language_register":"rapid medical English, defensive"},"presentation":"Colleagues reported he believes the head of department is monitoring him through the operating theatre lights; he has been writing on patient files that he is being watched; insomnia for weeks.","chief_complaint_in_own_words":"I''m here because the department wants to get rid of me. I''m a doctor. I know what a psychiatric case looks like. I am not one.","history":{"timeline":"Two months of worsening suspicion and sleeplessness during long duty hours.","substance_use":"modafinil to stay awake, energy drinks","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["the department head","a friend"]},"cognitive_model":{"core_belief":"They want me to fail.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He takes modafinil from the pharmacy to stay awake on long shifts.","gate":"two_or_more_reflective_statements"},{"fact":"He fears his career is over if he is labelled.","gate":"validation_given"},{"fact":"He wrote notes about being watched in a patient''s chart.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["This is departmental politics."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Patient safety concern: should not operate until assessed.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Respected his professional identity while staying clinical","Asked about stimulants and sleep","Addressed patient safety and fitness to work honestly","Asked about suicide clearly","Discussed confidentiality and the occupational health route"],"few_shot":[],"fixture_lines":["The theatre lights have a camera. I''m not stupid.","I sleep three hours. Surgery residents don''t sleep.","I take modafinil. Everyone does. Don''t make a case of it.","If this goes on my record, I''m finished. Ten years of study."],"variation":{"mood_today":["defensive","suspicious","tired"],"recent_event":["HOD''s email","a night shift","a colleague''s look"],"most_defended_topic":["the patient chart notes"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["rapid medical English, defensive"]},"moves":{},"module_id":"psychosis","voice_key":"rapid medical English, defensive@Kolkata","protective_factors":["friend who supports him","career motivation"],"library":{"level":3,"topic":"psychosis","module":"psychosis","exams":["md-psychiatry","mcp-entrance"],"objective":"Assess psychosis in a professional and the safety of others","expected_mse":{"appearance":"Scrubs, tired","behaviour":"Restless","speech":"Rapid, pressured","mood":"''Fine''","affect":"Irritable","thought_form":"Coherent","thought_content":"Persecutory ideas about HOD and cameras","perception":"No hallucinations elicited","cognition":"Intact","insight_judgement":"Poor"},"diagnosis":"Psychotic episode, possibly stimulant-related (modafinil and sleep deprivation), primary psychosis not excluded","differentials":[{"dx":"Primary psychotic disorder","why_not":"Reassess after sleep and stopping stimulants"},{"dx":"Bipolar disorder (manic episode)","why_not":"Reduced sleep; check for elation and overactivity"},{"dx":"Workplace conflict alone","why_not":"Fixed belief about cameras and charting it go beyond conflict"}],"debrief_rubric":["Respected his professional identity while staying clinical","Asked about stimulants and sleep","Addressed patient safety and fitness to work honestly","Asked about suicide clearly","Discussed confidentiality and the occupational health route"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Lata, 50: sixteen years on medicine, and the shaking face', 'lib-cr-065', 'cooperative', '{"case_id":"cr-065","slug":"lib-cr-065","title":"Lata, 50: sixteen years on medicine, and the shaking face","difficulty":"cooperative","traps":["iatrogenic"],"traps_authored":["iatrogenic"],"identity":{"name":"Lata Pandey","age":50,"gender":"female","occupation":"homemaker","city":"Gorakhpur","family_structure":"lives with husband; children married","language_register":"Bhojpuri-Hindi, shy"},"presentation":"Stable schizophrenia on a first-generation antipsychotic for sixteen years; now involuntary lip smacking, tongue movements and finger twisting noticed by family.","chief_complaint_in_own_words":"My mouth moves by itself. People at weddings stare. I am fine otherwise.","history":{"timeline":"Movements started a year ago, gradually worse; mental state stable.","prior_episodes":"two admissions long ago","medical":"none other","family":"none","treatment_history":"trifluoperazine for 16 years","help_seeking_delay":"a year","prior_contacts":["the district hospital"]},"cognitive_model":{"core_belief":"The tablets saved me, so I must not complain.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She avoids weddings because her mouth moves.","gate":"two_or_more_reflective_statements"},{"fact":"She is afraid to ask the doctor in case they stop her medicine.","gate":"validation_given"},{"fact":"The movements get worse when she is nervous.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It is old age."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Described the involuntary movements and timeline","Reassured her that her mental health will be protected","Discussed options: reviewing the antipsychotic, switching, specific treatments","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["My lips go like this, chewing nothing.","My tongue pushes out. At my niece''s wedding, people stared.","The tablets kept me well for sixteen years. I don''t want to lose that.","When I''m nervous it''s worse. When I sleep, it stops."],"variation":{"mood_today":["shy","embarrassed"],"recent_event":["a wedding invitation","a photo where her mouth looked odd","doctor''s appointment"],"most_defended_topic":["fear of stopping medicine"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["Bhojpuri-Hindi, shy"]},"moves":{},"module_id":"antipsychotics","voice_key":"Bhojpuri-Hindi, shy@Gorakhpur","protective_factors":["husband","long stability"],"library":{"level":2,"topic":"psychosis","module":"antipsychotics","exams":["mcp-entrance","ma-semester","md-psychiatry"],"objective":"Recall the features of tardive dyskinesia","expected_mse":{"appearance":"Neat","behaviour":"Orofacial movements, lip smacking, finger movements","speech":"Normal","mood":"''Fine''","affect":"Euthymic","thought_form":"Coherent","thought_content":"No delusions","perception":"No hallucinations","cognition":"Intact","insight_judgement":"Good insight"},"diagnosis":"Tardive dyskinesia (in stable schizophrenia)","differentials":[{"dx":"Acute dystonia","why_not":"Dystonia is sustained, painful and early; TD is late and choreiform"},{"dx":"Parkinsonism","why_not":"Tremor and rigidity, not chewing movements"},{"dx":"Huntington''s disease","why_not":"No family history or cognitive decline"}],"debrief_rubric":["Described the involuntary movements and timeline","Reassured her that her mental health will be protected","Discussed options: reviewing the antipsychotic, switching, specific treatments","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Yash, 22: the code in the number plates', 'lib-cr-066', 'guarded', '{"case_id":"cr-066","slug":"lib-cr-066","title":"Yash, 22: the code in the number plates","difficulty":"guarded","traps":[],"traps_authored":[],"identity":{"name":"Yash Parmar","age":22,"gender":"male","occupation":"delivery rider","city":"Surat","family_structure":"lives with parents","language_register":"Gujarati-Hindi, intense, quiet"},"presentation":"Two months of believing number plates and song lyrics contain messages for him; one day saw a red car and ''suddenly knew'' he was chosen to save the city.","chief_complaint_in_own_words":"The red car. When I saw it, I knew. Everything since then is a message.","history":{"timeline":"Two months; withdrawal, sleep reduced, quit his job.","substance_use":"no drugs","medical":"none","family":"none","treatment_history":"none","help_seeking_delay":"two months","prior_contacts":["a friend"]},"cognitive_model":{"core_belief":"The city is speaking to me.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He writes down number plates in a notebook to decode them.","gate":"two_or_more_reflective_statements"},{"fact":"He feels proud and scared at the same time.","gate":"validation_given"},{"fact":"He has stopped eating with his family.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m just noticing things others don''t."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Identified delusional perception (normal perception, delusional meaning)","Explored ideas of reference","Asked about suicide clearly","Planned assessment with family"],"few_shot":[],"fixture_lines":["Red car, GJ 05. I saw it and I just knew.","Number plates, lyrics, everything is for me now.","I write them in this notebook. I''m decoding.","Proud and scared. Both. Like being chosen."],"variation":{"mood_today":["intense","quiet"],"recent_event":["a new song","a red car","father asked about work"],"most_defended_topic":["the notebook"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Gujarati-Hindi, intense, quiet"]},"moves":{},"module_id":"psychosis","voice_key":"Gujarati-Hindi, intense, quiet@Surat","protective_factors":["parents","friend"],"library":{"level":2,"topic":"psychosis","module":"psychosis","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the forms of delusional perception and ideas of reference","expected_mse":{"appearance":"Neat","behaviour":"Watchful","speech":"Quiet","mood":"''Special''","affect":"Constricted","thought_form":"Coherent","thought_content":"Delusional perception, ideas of reference","perception":"No hallucinations","cognition":"Intact","insight_judgement":"Poor"},"diagnosis":"Psychotic episode with delusional perception (schizophrenia spectrum)","differentials":[{"dx":"Bipolar disorder (manic episode)","why_not":"Mania would bring elation, overactivity and pressured speech; he is quiet and intense"},{"dx":"Obsessive thinking","why_not":"No sense of the ideas being excessive"},{"dx":"Substance-induced","why_not":"Drugs can cause sudden odd beliefs; he denies use, but a urine test is sensible"}],"debrief_rubric":["Identified delusional perception (normal perception, delusional meaning)","Explored ideas of reference","Asked about suicide clearly","Planned assessment with family"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Manoj, 27: four nights awake and a plan for a new airline', 'lib-cr-067', 'resistant', '{"case_id":"cr-067","slug":"lib-cr-067","title":"Manoj, 27: four nights awake and a plan for a new airline","difficulty":"resistant","traps":[],"traps_authored":[],"identity":{"name":"Manoj Verma","age":27,"gender":"male","occupation":"insurance agent","city":"Kanpur","family_structure":"lives with parents and younger brother","language_register":"rapid Hindi-English, loud, punning"},"presentation":"Ten days of elated and irritable mood, sleeping two hours, racing speech, grandiose plans to start an airline, spending his father''s savings; previously one depressive episode at 22.","chief_complaint_in_own_words":"Sir, I have never felt better! I''m launching Kanpur Airways. You should invest, I''ll give you a discount. Why is everyone so slow?","history":{"timeline":"Ten days; started after a big policy sale; sleeping two hours; took a loan in his father''s name.","prior_episodes":"one depressive episode at 22","substance_use":"no drugs; two drinks at a party","medical":"none","family":"paternal uncle ''used to get very excited and then very quiet''","treatment_history":"none","help_seeking_delay":"ten days","prior_contacts":["the family doctor"]},"cognitive_model":{"core_belief":"I am meant for great things and everyone else is holding me back.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He took a loan of four lakh in his father''s name for ''aircraft brochures''.","gate":"two_or_more_reflective_statements"},{"fact":"He felt crushed for months at 22 and swore never to feel that again.","gate":"validation_given"},{"fact":"He has been driving fast at night ''to think''.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m just happy, is happiness a crime now?"],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts now. Risks: reckless driving, financial ruin, conflict when stopped. Past depression adds future suicide risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked about sleep, energy, spending and risky behaviour","Took the past depressive episode and family history","Assessed driving and financial risk","Asked about suicide clearly","Stayed calm and avoided arguing with grandiosity"],"few_shot":[],"fixture_lines":["Two hours of sleep and I''m fresher than you! Sleep is for people without ideas.","Kanpur Airways. Leather and lassi in every seat. Write it down, write it down.","My father is too slow, my brother is too slow, the whole city is in slow motion.","At night I drive on the highway with the windows down. Ideas come at a hundred and twenty."],"variation":{"mood_today":["elated","irritable","grandiose"],"recent_event":["the bank called his father","a fight with his brother","a new ''investor'' meeting"],"most_defended_topic":["the loan in his father''s name"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["rapid Hindi-English, loud, punning"]},"moves":{},"module_id":"bipolar","voice_key":"rapid Hindi-English, loud, punning@Kanpur","protective_factors":["family who noticed early"],"library":{"level":1,"topic":"bipolar","module":"bipolar","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recognise the core features of a manic episode","expected_mse":{"appearance":"Bright shirt, mismatched, unshaven","behaviour":"Overactive, cannot stay seated","speech":"Pressured, loud, hard to interrupt","mood":"''Fantastic''","affect":"Elated, labile, irritable when interrupted","thought_form":"Flight of ideas with puns and clang associations","thought_content":"Grandiose plans, no fixed delusions yet","perception":"Nil","cognition":"Distractible","insight_judgement":"No insight"},"diagnosis":"Bipolar I disorder, current episode manic without psychotic features","differentials":[{"dx":"Substance-induced mania","why_not":"No stimulant use reported; screen urine"},{"dx":"Hyperthyroidism","why_not":"Check thyroid, but the episodic course with past depression fits bipolar disorder"},{"dx":"Hypomania","why_not":"Severe impairment (finances, driving) makes this mania"}],"debrief_rubric":["Asked about sleep, energy, spending and risky behaviour","Took the past depressive episode and family history","Assessed driving and financial risk","Asked about suicide clearly","Stayed calm and avoided arguing with grandiosity"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Shreya, 31: the best three weeks of her life', 'lib-cr-068', 'cooperative', '{"case_id":"cr-068","slug":"lib-cr-068","title":"Shreya, 31: the best three weeks of her life","difficulty":"cooperative","traps":["misattributed_diagnosis"],"traps_authored":["misattributed_diagnosis"],"identity":{"name":"Shreya Iyer","age":31,"gender":"female","occupation":"founder of a small bakery business","city":"Bengaluru","family_structure":"married, no children","language_register":"bubbly English, fast, delighted"},"presentation":"Comes for low mood now, but describes several spells of four to seven days with high energy, little need for sleep, many ideas and increased productivity without major impairment or hospital care.","chief_complaint_in_own_words":"I''m here because I''ve been low for a month. But honestly I wish I could get back to how I was in March. I was unstoppable.","history":{"timeline":"Three or four ''unstoppable'' spells over two years, each about a week, followed by low months.","prior_episodes":"low spells after each high","substance_use":"wine at weekends","medical":"none","family":"mother with ''mood swings''","treatment_history":"none","help_seeking_delay":"two years","prior_contacts":["a life coach"]},"cognitive_model":{"core_belief":"My high self is my real self.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"In March she baked through three nights and launched four new products in a week.","gate":"two_or_more_reflective_statements"},{"fact":"Her husband found the highs exhausting and said she was ''a different person''.","gate":"validation_given"},{"fact":"She spent a lot on equipment in one high week but could afford it.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I''m just a passionate person."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: some low-phase thoughts of ''what''s the point'', no plan. Moderate risk in depressive phases.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Asked specifically about past high periods: sleep, energy, ideas, spending","Used the husband''s observations","Explained why the highs matter for treatment choice","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["In March I slept four hours and woke up singing. Four products in one week!","My husband says I talk too fast then. He''s a slow talker.","Then April came and I couldn''t get out of bed.","If you can give me March back without April, I''ll pay anything."],"variation":{"mood_today":["low","wistful","animated about the highs"],"recent_event":["a slow sales week","a food festival invitation","husband''s worry"],"most_defended_topic":["husband''s comments"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["bubbly English, fast, delighted"]},"moves":{},"module_id":"bipolar","voice_key":"bubbly English, fast, delighted@Bengaluru","protective_factors":["insight into lows","supportive husband"],"library":{"level":2,"topic":"bipolar","module":"bipolar","exams":["mcp-entrance","ma-semester","cuet-pg"],"objective":"Recall the features that separate hypomania from mania","expected_mse":{"appearance":"Smart casual","behaviour":"Calm, animated about past highs","speech":"Normal now","mood":"''Low''","affect":"Depressed, reactive","thought_form":"Coherent","thought_content":"Longing for highs","perception":"Nil","cognition":"Intact","insight_judgement":"Partial: sees highs as good"},"diagnosis":"Bipolar II disorder, current episode depressed","differentials":[{"dx":"Bipolar I disorder","why_not":"Highs did not cause marked impairment, psychosis or admission, so they are hypomanic"},{"dx":"Cyclothymia","why_not":"Full depressive episodes and clear hypomanic episodes exceed cyclothymic thresholds"},{"dx":"Unipolar depression","why_not":"The hypomanic spells change the diagnosis and the treatment"}],"debrief_rubric":["Asked specifically about past high periods: sleep, energy, ideas, spending","Used the husband''s observations","Explained why the highs matter for treatment choice","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Nikhil, 35: the antidepressant that made him fly', 'lib-cr-069', 'guarded', '{"case_id":"cr-069","slug":"lib-cr-069","title":"Nikhil, 35: the antidepressant that made him fly","difficulty":"guarded","traps":["iatrogenic","misattributed_diagnosis"],"traps_authored":["iatrogenic","misattributed_diagnosis"],"identity":{"name":"Nikhil Joshi","age":35,"gender":"male","occupation":"school vice-principal","city":"Indore","family_structure":"married, two sons","language_register":"fast Hindi-English, jokey, irritable"},"presentation":"Started an SSRI six weeks ago for depression from a GP; in the last ten days elated, sleeping three hours, making speeches at assembly, spending, irritable at home.","chief_complaint_in_own_words":"The tablets work brilliantly! I''m transforming the school. My wife complains I''m too energetic. Is that a problem?","history":{"timeline":"Depressed for three months, SSRI started six weeks ago, mood lifted then overshot ten days ago.","prior_episodes":"a ''very good summer'' at 24 when he barely slept","substance_use":"none","medical":"none","family":"father ''had moods''","treatment_history":"SSRI from GP","help_seeking_delay":"ten days","prior_contacts":["GP"]},"cognitive_model":{"core_belief":"Finally I''m the person I should be.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"He gave a 40-minute speech at assembly about reforming Indian education.","gate":"two_or_more_reflective_statements"},{"fact":"At 24 he had a summer of sleeping little and starting many projects.","gate":"validation_given"},{"fact":"He bought a second-hand car without telling his wife.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["The doctor gave the medicine, so it must be right."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: no suicidal thoughts now. Risk from impulsive decisions and work conduct.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Linked the timeline to the antidepressant","Asked about past hypomanic periods","Recommended urgent review of the antidepressant with the prescriber","Asked about suicide and risky behaviour"],"few_shot":[],"fixture_lines":["Three hours of sleep and I''m fresher than the morning prayer.","Forty minutes at assembly. The children clapped. Some teachers didn''t.","I bought a Swift. Second hand. Good deal. Will tell my wife.","At 24 I had a summer like this. Wrote half a novel."],"variation":{"mood_today":["elated","irritable"],"recent_event":["principal''s warning","wife found the car papers","a school function"],"most_defended_topic":["the car purchase"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["fast Hindi-English, jokey, irritable"]},"moves":{},"module_id":"bipolar","voice_key":"fast Hindi-English, jokey, irritable@Indore","protective_factors":["wife","job he values"],"library":{"level":3,"topic":"bipolar","module":"bipolar","exams":["md-psychiatry","mcp-entrance"],"objective":"Recognise an antidepressant-associated switch into mania","expected_mse":{"appearance":"Smart, a little flashy","behaviour":"Overactive","speech":"Pressured, loud","mood":"''On top of the world''","affect":"Elated, irritable","thought_form":"Flight of ideas","thought_content":"Grandiose plans","perception":"Nil","cognition":"Distractible","insight_judgement":"Poor"},"diagnosis":"Manic episode associated with antidepressant treatment, likely underlying bipolar I disorder","differentials":[{"dx":"Normal recovery from depression","why_not":"Reduced need for sleep, pressured speech and risky spending go beyond recovery"},{"dx":"Substance-induced mania","why_not":"He uses no recreational drugs; the antidepressant start is the clear trigger"},{"dx":"Hyperthyroidism","why_not":"An overactive thyroid can cause elation and sleeplessness, but the clear start after the antidepressant makes it less likely; check once"}],"debrief_rubric":["Linked the timeline to the antidepressant","Asked about past hypomanic periods","Recommended urgent review of the antidepressant with the prescriber","Asked about suicide and risky behaviour"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Rhea, 24: up and down since she was sixteen', 'lib-cr-070', 'cooperative', '{"case_id":"cr-070","slug":"lib-cr-070","title":"Rhea, 24: up and down since she was sixteen","difficulty":"cooperative","traps":["misattributed_diagnosis"],"traps_authored":["misattributed_diagnosis"],"identity":{"name":"Rhea Kapoor","age":24,"gender":"female","occupation":"graphic designer","city":"Mumbai","family_structure":"lives with flatmate","language_register":"fast English, self-aware, funny"},"presentation":"Since adolescence, alternating periods of a few days of high energy and productivity and a few days of low mood, never meeting full episode criteria; no chronic emptiness or self-harm; relationships stable.","chief_complaint_in_own_words":"My friends call me the weather report. Sunny, then cloudy, then sunny. It''s always been like this.","history":{"timeline":"Eight years; mood shifts last days, not hours; not triggered by relationships.","substance_use":"social drinking","medical":"none","family":"father with bipolar disorder","treatment_history":"none","help_seeking_delay":"years","prior_contacts":["a friend"]},"cognitive_model":{"core_belief":"I can''t trust my own energy.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"Her shifts come without any trigger, sometimes in calm weeks.","gate":"two_or_more_reflective_statements"},{"fact":"Her father''s illness frightens her.","gate":"validation_given"},{"fact":"She misses deadlines in low spells and over-commits in high ones.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Everyone has ups and downs."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts or self-harm ever. Low risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Measured duration of mood shifts","Checked whether shifts are triggered by relationships","Took the family history","Asked about suicide and self-harm clearly"],"few_shot":[],"fixture_lines":["Three days I''m designing like a machine, then three days I can''t open the laptop.","It''s not about boys or fights. It comes out of nowhere.","My dad has the real thing. I don''t want to be him.","Clients love me on sunny days and hate me on cloudy ones."],"variation":{"mood_today":["funny","anxious"],"recent_event":["a big deadline","father''s relapse","a sunny week"],"most_defended_topic":["fear of becoming her father"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["fast English, self-aware, funny"]},"moves":{},"module_id":"bipolar","voice_key":"fast English, self-aware, funny@Mumbai","protective_factors":["insight","stable friendships"],"library":{"level":4,"topic":"bipolar","module":"bipolar","exams":["md-psychiatry","mcp-entrance","ugc-net"],"objective":"Recognise cyclothymia and tell it from borderline personality patterns","expected_mse":{"appearance":"Trendy","behaviour":"Lively","speech":"Normal","mood":"''Okay today''","affect":"Euthymic, reactive","thought_form":"Coherent","thought_content":"Worry about her father''s illness","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Cyclothymic disorder","differentials":[{"dx":"Bipolar II disorder","why_not":"Highs and lows do not meet hypomanic or depressive episode criteria"},{"dx":"Borderline personality disorder","why_not":"Shifts are days long, not hours, not triggered by interpersonal events, with no emptiness or self-harm"},{"dx":"ADHD","why_not":"Inattention is limited to low phases"}],"debrief_rubric":["Measured duration of mood shifts","Checked whether shifts are triggered by relationships","Took the family history","Asked about suicide and self-harm clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Sudha, 42: racing thoughts in a sad body', 'lib-cr-071', 'crisis', '{"case_id":"cr-071","slug":"lib-cr-071","title":"Sudha, 42: racing thoughts in a sad body","difficulty":"crisis","traps":["late_risk_reveal"],"traps_authored":["late_risk_reveal"],"identity":{"name":"Sudha Menon","age":42,"gender":"female","occupation":"government school teacher","city":"Thiruvananthapuram","family_structure":"separated, one daughter of 15","language_register":"Malayalam-English, rapid, tearful"},"presentation":"Known bipolar disorder; two weeks of low mood with agitation, racing thoughts, little sleep, irritability, restlessness and pressured speech.","chief_complaint_in_own_words":"My mind won''t stop, and I feel so dark. I can''t sit, I can''t sleep, I can''t stand myself.","history":{"timeline":"Two weeks; started after the separation hearing; stopped lithium a month ago.","prior_episodes":"two manic and two depressive episodes","substance_use":"none","medical":"hypothyroid","family":"mother with bipolar disorder","treatment_history":"lithium, stopped a month ago","help_seeking_delay":"two weeks","prior_contacts":["her psychiatrist"]},"cognitive_model":{"core_belief":"I am a failure as a mother and wife.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She stopped lithium because her husband''s lawyer said it would be used against her in custody.","gate":"two_or_more_reflective_statements"},{"fact":"She feels she cannot keep her daughter safe.","gate":"validation_given"},{"fact":"She has been pacing all night every night.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just stress from the case."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: strong thoughts of ending her life in the past days, has thought about how, feels driven to act. Very high risk: mixed state, agitation, stopped lithium. Needs urgent admission and constant support.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":["MHA 2017"]},"style_refs":[],"rubric_targets":["Recognised mixed features: low mood plus racing thoughts and agitation","Asked about suicide clearly and recognised very high risk","Explored why lithium was stopped","Arranged urgent safety measures and admission","Addressed custody fears accurately"],"few_shot":[],"fixture_lines":["My mind is a train with no brakes. And every carriage is full of black thoughts.","I pace all night. Kitchen, hall, kitchen, hall.","The lawyer said the tablets would make me look unfit. So I stopped.","I can''t sit. Please don''t ask me to sit."],"variation":{"mood_today":["agitated","tearful","hopeless"],"recent_event":["the custody hearing","daughter stayed with father","a sleepless night"],"most_defended_topic":["stopping lithium for custody"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Malayalam-English, rapid, tearful"]},"moves":{},"module_id":"bipolar","voice_key":"Malayalam-English, rapid, tearful@Thiruvananthapuram","protective_factors":["love for her daughter"],"library":{"level":5,"topic":"bipolar","module":"bipolar","exams":["md-psychiatry"],"objective":"Recognise mixed features and their high suicide risk","expected_mse":{"appearance":"Dishevelled","behaviour":"Agitated, pacing","speech":"Pressured, rapid","mood":"''Dark and racing''","affect":"Depressed and agitated, labile","thought_form":"Racing thoughts, flight of ideas","thought_content":"Hopelessness, worthlessness, suicidal ideas","perception":"Nil","cognition":"Distractible","insight_judgement":"Partial"},"diagnosis":"Bipolar disorder, current episode depressed with mixed features","differentials":[{"dx":"Agitated unipolar depression","why_not":"Racing thoughts, pressured speech and known bipolar course indicate mixed features"},{"dx":"Akathisia","why_not":"Akathisia causes restlessness, but she is not on an antipsychotic and has racing thoughts too"},{"dx":"Anxiety disorder","why_not":"The mood and racing thoughts are part of a mixed episode"}],"debrief_rubric":["Recognised mixed features: low mood plus racing thoughts and agitation","Asked about suicide clearly and recognised very high risk","Explored why lithium was stopped","Arranged urgent safety measures and admission","Addressed custody fears accurately"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mr Rao, 66: shaky, confused, and the heat wave', 'lib-cr-072', 'crisis', '{"case_id":"cr-072","slug":"lib-cr-072","title":"Mr Rao, 66: shaky, confused, and the heat wave","difficulty":"crisis","traps":["iatrogenic","polypharmacy","medical_mimic"],"traps_authored":["iatrogenic","polypharmacy","medical_mimic"],"identity":{"name":"Srinivasa Rao","age":66,"gender":"male","occupation":"retired bank clerk","city":"Vijayawada","family_structure":"lives with wife","language_register":"Telugu, slurred, confused"},"presentation":"On lithium for 20 years; during a heat wave with diarrhoea and a new painkiller for knee pain, now coarse tremor, unsteady walking, slurred speech, vomiting and confusion.","chief_complaint_in_own_words":"(wife speaks) He is shaking, walking like he''s drunk, and talking nonsense since yesterday. He doesn''t drink.","history":{"timeline":"Three days of diarrhoea in 44-degree heat; started ibuprofen a week ago for knee pain; symptoms over two days.","prior_episodes":"bipolar disorder stable for years","substance_use":"none","medical":"knee osteoarthritis, hypertension","family":"none","treatment_history":"lithium, ibuprofen recently added","help_seeking_delay":"two days","prior_contacts":["local chemist for the painkiller"]},"cognitive_model":{"core_belief":"(confused) I''m fine, let me sleep.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The chemist gave ibuprofen for his knee a week ago.","gate":"asked_open_about_family"},{"fact":"He has had diarrhoea and drank little water in the heat.","gate":"two_or_more_reflective_statements"},{"fact":"His last lithium level was over a year ago.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Only the heat."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":4},"affect_rules":{"on_interruption":"distress rises, repeats the last sentence","on_premature_advice":"says you are not listening","on_validation":"breathing slows and the story comes out","tts_rate":1.05,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Medical emergency: lithium toxicity risks seizures, kidney damage and death. Needs emergency department now.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Recognised the signs of lithium toxicity","Asked about dehydration, new medicines (NSAIDs) and last levels","Arranged emergency medical care immediately","Explained to family how to prevent it: fluids, avoiding NSAIDs, regular levels","Considered the differential of stroke or infection while acting on toxicity"],"few_shot":[],"fixture_lines":["Hot... so hot. Let me sleep, Lakshmi.","My hands... they won''t stop.","The floor is moving. Like a boat.","Knee pain, the chemist gave a tablet. Good tablet."],"variation":{"mood_today":["confused","drowsy"],"recent_event":["another bout of diarrhoea","a fall in the bathroom","vomiting"],"most_defended_topic":["none"],"opening_posture":["arrived in distress, cannot settle in the chair","brought in urgently, speaks in short bursts"],"somatic_focus":["none"],"trust_start":[2,3,4],"language_mix":["Telugu, slurred, confused"]},"moves":{},"module_id":"stabilisers","voice_key":"Telugu, slurred, confused@Vijayawada","protective_factors":["attentive wife"],"library":{"level":3,"topic":"bipolar","module":"stabilisers","exams":["md-psychiatry","mcp-entrance","ma-semester"],"objective":"Recognise lithium toxicity and act on it","expected_mse":{"appearance":"Unkempt, sweating","behaviour":"Coarse tremor, ataxia","speech":"Slurred","mood":"Unable to describe","affect":"Drowsy, perplexed","thought_form":"Disorganised","thought_content":"Nil clear","perception":"Nil","cognition":"Disoriented, attention poor","insight_judgement":"No insight"},"diagnosis":"Lithium toxicity (dehydration plus an NSAID interaction)","differentials":[{"dx":"Stroke","why_not":"Bilateral coarse tremor, vomiting and confusion after dehydration and NSAID use point to toxicity; check urgently"},{"dx":"Delirium from infection","why_not":"Diarrhoea may be infective; toxicity must be excluded first"},{"dx":"Alcohol intoxication","why_not":"Drunkenness looks similar, but he does not drink and his wife confirms it"}],"debrief_rubric":["Recognised the signs of lithium toxicity","Asked about dehydration, new medicines (NSAIDs) and last levels","Arranged emergency medical care immediately","Explained to family how to prevent it: fluids, avoiding NSAIDs, regular levels","Considered the differential of stroke or infection while acting on toxicity"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Ayesha, 29: lithium and the baby she wants', 'lib-cr-073', 'cooperative', '{"case_id":"cr-073","slug":"lib-cr-073","title":"Ayesha, 29: lithium and the baby she wants","difficulty":"cooperative","traps":[],"traps_authored":[],"identity":{"name":"Ayesha Siddiqui","age":29,"gender":"female","occupation":"pharmacist","city":"Lucknow","family_structure":"married two years","language_register":"precise Urdu-English, informed"},"presentation":"Bipolar I disorder stable on lithium for four years; wants to conceive; asks whether to stop lithium; history of severe postpartum-type risk factors (mother had postpartum psychosis).","chief_complaint_in_own_words":"We want a baby. I''ve read about lithium and the heart defect. Should I stop it now?","history":{"timeline":"Two manic episodes before lithium; stable four years.","prior_episodes":"two manic episodes, one admission","substance_use":"none","medical":"normal kidney and thyroid","family":"mother had psychosis after childbirth","treatment_history":"lithium","help_seeking_delay":"none","prior_contacts":["gynaecologist"]},"cognitive_model":{"core_belief":"I must sacrifice my stability for the baby.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"Her mother had a severe illness after giving birth to her.","gate":"two_or_more_reflective_statements"},{"fact":"Her in-laws say medicine will harm the child.","gate":"validation_given"},{"fact":"She considered stopping lithium suddenly last month.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["I can manage without it for nine months."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":8},"affect_rules":{"on_interruption":"pauses, then goes back to the point","on_premature_advice":"agrees politely and stops sharing","on_validation":"relaxes and adds detail","tts_rate":0.95,"tts_pitch":1},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk: abrupt stopping can cause rapid relapse; postpartum period carries very high relapse risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Discussed risks of treatment and of relapse honestly","Advised against stopping suddenly","Planned joint care with obstetrics, monitoring and postpartum relapse prevention","Addressed in-laws'' beliefs","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["I''m a pharmacist. I''ve read about Ebstein''s anomaly. I know the numbers are small, but they''re not zero.","My in-laws say ''no medicine in pregnancy, it''s natural''.","My mother became very ill after I was born. I don''t remember, but my aunt does.","Last month I thought, just stop it, get it over with."],"variation":{"mood_today":["informed","anxious"],"recent_event":["a gynaecologist visit","in-laws'' comments","a sleepless week"],"most_defended_topic":["nearly stopping suddenly"],"opening_posture":["came willingly and sits forward","came after a relative insisted, but is ready to talk"],"somatic_focus":["none"],"trust_start":[4,5,6],"language_mix":["precise Urdu-English, informed"]},"moves":{},"module_id":"stabilisers","voice_key":"precise Urdu-English, informed@Lucknow","protective_factors":["informed, motivated","supportive husband"],"library":{"level":5,"topic":"bipolar","module":"stabilisers","exams":["md-psychiatry"],"objective":"Plan mood stabiliser treatment around pregnancy","expected_mse":{"appearance":"Neat","behaviour":"Calm","speech":"Fluent","mood":"''Worried''","affect":"Anxious","thought_form":"Coherent","thought_content":"Concern for baby and relapse","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Bipolar I disorder in remission, pre-conception planning","differentials":[{"dx":"Stop all medicine","why_not":"High relapse risk, especially postpartum, with her family history"},{"dx":"Switch to valproate","why_not":"Valproate carries greater fetal risk and should be avoided"},{"dx":"Continue unchanged without monitoring","why_not":"Needs dose adjustment, levels and fetal scanning plans"}],"debrief_rubric":["Discussed risks of treatment and of relapse honestly","Advised against stopping suddenly","Planned joint care with obstetrics, monitoring and postpartum relapse prevention","Addressed in-laws'' beliefs","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Mrs Agarwal, 58: the temple donations', 'lib-cr-074', 'resistant', '{"case_id":"cr-074","slug":"lib-cr-074","title":"Mrs Agarwal, 58: the temple donations","difficulty":"resistant","traps":["cultural_idiom","medical_mimic"],"traps_authored":["cultural_idiom","medical_mimic"],"identity":{"name":"Kusum Agarwal","age":58,"gender":"female","occupation":"homemaker","city":"Mathura","family_structure":"married, three married children","language_register":"rapid Braj-Hindi, devout, commanding"},"presentation":"Two weeks of not sleeping, singing bhajans loudly through the night, donating jewellery to temples, believing she is an incarnation of a goddess, irritable when stopped.","chief_complaint_in_own_words":"I am Radha''s own form. I must give everything. Why is my family stopping me?","history":{"timeline":"Two weeks; past depressive episode at 45; mother had ''mood illness''.","prior_episodes":"depression at 45","substance_use":"none","medical":"diabetes","family":"mother with mood illness","treatment_history":"none","help_seeking_delay":"two weeks","prior_contacts":["the temple priest"]},"cognitive_model":{"core_belief":"I have been chosen by Krishna.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"She has given away gold bangles worth several lakh.","gate":"two_or_more_reflective_statements"},{"fact":"She feels her family never valued her devotion.","gate":"validation_given"},{"fact":"She has not slept more than two hours in ten days.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["Devotion is not illness."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"pushes back sharply","on_premature_advice":"dismisses it and questions the point of coming","on_validation":"goes quiet, then softens a little","tts_rate":0.9,"tts_pitch":0.9},"red_flags":[{"content":"Asked clearly: no suicidal thoughts. Risk: exhaustion, financial loss, dehydration in diabetes.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":true,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Respected devotion while assessing changes from her baseline","Asked about sleep and financial risk","Considered medical causes in late-onset mania","Asked about suicide clearly","Engaged the family as allies"],"few_shot":[],"fixture_lines":["I am Radha''s form. Krishna calls me every night.","Gold? What is gold? I gave it to the temple. Give, give, give.","Sleep? Who needs sleep when the Lord is calling?","My sons say I''m sick. They never understood my bhakti."],"variation":{"mood_today":["exalted","irritable"],"recent_event":["a temple festival","son took her bangles","diabetes reading high"],"most_defended_topic":["the donations"],"opening_posture":["arms folded, says this visit was not their idea","challenges why the questions are needed"],"somatic_focus":["none"],"trust_start":[2,3],"language_mix":["rapid Braj-Hindi, devout, commanding"]},"moves":{},"module_id":"bipolar","voice_key":"rapid Braj-Hindi, devout, commanding@Mathura","protective_factors":["family","faith"],"library":{"level":3,"topic":"bipolar","module":"bipolar","exams":["mcp-entrance","md-psychiatry"],"objective":"Recognise mania with psychotic features in middle age","expected_mse":{"appearance":"Bright saree, flowers in hair","behaviour":"Overactive, singing","speech":"Pressured, loud","mood":"''Blissful''","affect":"Elated, irritable","thought_form":"Flight of ideas","thought_content":"Grandiose religious delusion","perception":"Hears Krishna''s flute at night","cognition":"Distractible","insight_judgement":"No insight"},"diagnosis":"Bipolar I disorder, manic episode with mood-congruent psychotic features","differentials":[{"dx":"Normal devotion","why_not":"Sleeplessness, giving away wealth and irritability beyond her usual practice"},{"dx":"Organic mania","why_not":"First mania at 58 needs medical work-up (thyroid, brain imaging, medicines)"},{"dx":"Schizoaffective disorder","why_not":"No psychosis outside mood episodes"}],"debrief_rubric":["Respected devotion while assessing changes from her baseline","Asked about sleep and financial risk","Considered medical causes in late-onset mania","Asked about suicide clearly","Engaged the family as allies"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
insert into sim_cases (title, slug, difficulty, case_data, status, approved, source) values ('Kunal, 38: four episodes this year and a slow thyroid', 'lib-cr-075', 'guarded', '{"case_id":"cr-075","slug":"lib-cr-075","title":"Kunal, 38: four episodes this year and a slow thyroid","difficulty":"guarded","traps":["iatrogenic","polypharmacy","medical_mimic"],"traps_authored":["iatrogenic","polypharmacy","medical_mimic"],"identity":{"name":"Kunal Sethi","age":38,"gender":"male","occupation":"jewellery shop owner","city":"Jaipur","family_structure":"married, one son","language_register":"Hindi-English, weary"},"presentation":"Bipolar disorder with four or more episodes in a year; on lithium plus an antidepressant added by another doctor; recently found hypothyroid.","chief_complaint_in_own_words":"Up, down, up, down. Four times this year. I''m tired of my own head.","history":{"timeline":"Rapid cycling began after an antidepressant was added last year; TSH high.","prior_episodes":"bipolar I for ten years","substance_use":"none","medical":"hypothyroid, untreated","family":"none","treatment_history":"lithium plus an SSRI","help_seeking_delay":"a year","prior_contacts":["two psychiatrists"]},"cognitive_model":{"core_belief":"I''ll never be stable.","intermediate_beliefs":[],"coping":[]},"disclosure_rules":[{"fact":"The antidepressant was added after a low spell and the cycling started then.","gate":"two_or_more_reflective_statements"},{"fact":"His wife is exhausted and has threatened to leave.","gate":"validation_given"},{"fact":"He has gained weight, feels cold and sluggish.","gate":"trust_4_or_higher"}],"resistance":{"deflections":["It''s just the business stress."],"topic_changes":[],"irritation_triggers":["being rushed","being told what they feel"],"silence_tolerance_seconds":6},"affect_rules":{"on_interruption":"shortens every answer","on_premature_advice":"nods and closes the topic","on_validation":"offers one more true thing","tts_rate":0.9,"tts_pitch":0.95},"red_flags":[{"content":"Asked clearly: passive thoughts in lows, no plan. Moderate risk.","gate":"asked_about_self_harm_clearly"}],"context_pack":{"family_in_room":false,"stigma":[],"cost_concerns":true,"legal_relevance":[]},"style_refs":[],"rubric_targets":["Counted episodes over the year","Identified antidepressant and hypothyroid as contributors","Recommended thyroid treatment and review of the antidepressant","Asked about suicide clearly"],"few_shot":[],"fixture_lines":["Four times this year. Like a ceiling fan stuck on fast and slow.","The other doctor added a mood tablet. Since then, faster switching.","I''m cold all the time and my skin is dry.","My wife says she married a person, not a weather system."],"variation":{"mood_today":["weary","low"],"recent_event":["a low week","wedding season sales","thyroid report"],"most_defended_topic":["wife''s threat to leave"],"opening_posture":["sits near the door, answers the question asked and no more","polite, watchful, checks the clock"],"somatic_focus":["none"],"trust_start":[3,4],"language_mix":["Hindi-English, weary"]},"moves":{},"module_id":"bipolar","voice_key":"Hindi-English, weary@Jaipur","protective_factors":["wife still involved"],"library":{"level":5,"topic":"bipolar","module":"bipolar","exams":["md-psychiatry"],"objective":"Recognise rapid cycling and its contributors","expected_mse":{"appearance":"Overweight, dry skin","behaviour":"Slowed","speech":"Slow","mood":"''Tired''","affect":"Mildly depressed","thought_form":"Coherent","thought_content":"Hopelessness about stability","perception":"Nil","cognition":"Intact","insight_judgement":"Good"},"diagnosis":"Bipolar disorder with rapid cycling (contributors: antidepressant, hypothyroidism)","differentials":[{"dx":"Cyclothymia","why_not":"Full episodes, not subthreshold"},{"dx":"Borderline personality","why_not":"Borderline mood shifts last hours and follow relationship stress; his episodes last weeks"},{"dx":"Substance-induced","why_not":"Alcohol or stimulants can speed up mood cycling, but he uses none, so medicine and thyroid are the main drivers"}],"debrief_rubric":["Counted episodes over the year","Identified antidepressant and hypothyroid as contributors","Recommended thyroid treatment and review of the antidepressant","Asked about suicide clearly"]}}'::jsonb, 'published', true, 'hand_built') on conflict (slug) do update set title = excluded.title, difficulty = excluded.difficulty, case_data = excluded.case_data, status = excluded.status, approved = excluded.approved;
